/* v2.10.0 World civilisations in parallel: researched and checked 24 October 2026 */
const WORLD_EV=[
 {id:"africa-south-border-cave-notched-bones-possi",region:"africa-south",place:"Border Cave, Lebombo Mountains (South Africa–Eswatini border)",ys:-42000,ye:-40000,y:"c. 44,000–42,000 years ago",domain:"maths",also:[],t:"Border Cave notched bones, possibly used for counting",text:"Excavations at Border Cave in the Lebombo Mountains recovered notched bones alongside other early Later Stone Age tools linked to the ancestors of San culture. Researchers suggest the notches may have been used for counting.",disputed:true,note:"Popular accounts single out one piece as the 'Lebombo bone' and call it a lunar calendar. The research team says only that the bones 'may have been used for counting'; the calendar reading is speculative. Dates refer to the onset of the Later Stone Age at the site (44,000–42,000 years ago) rather than to each object.",src:[SRCQ("Later Stone Age got earlier start in South Africa than was previously thought – University of Colorado Boulder","https://www.colorado.edu/asmagazine-archive/node/999","Supports World civilisations in parallel (History page)","The assemblage also included worked tusks of members of the pig family, which likely were used to plane wood, and notched bones that may have been used for counting."),SRCQ("Later Stone Age got earlier start in South Africa than was previously thought – University of Colorado Boulder","https://www.colorado.edu/asmagazine-archive/node/999","Supports World civilisations in parallel (History page)","The study shows the onset of the Later Stone Age in South Africa likely began some 44,000 to 42,000 years ago, said Paola Villa, a curator at the University of Colorado Museum of Natural History and lead study author."),SRCQ("University of the Witwatersrand news, Aug 2012","https://www.wits.ac.za/alumni/archive/alumni-news-items/alumni-2012-08/modern-culture-44-000-years-ago/","Supports World civilisations in parallel (History page)","Organic artefacts, unambiguously reminiscent of San material culture, appear relatively abruptly.")]},
 {id:"africa-central-the-ishango-bone-grouped-notc",region:"africa-central",place:"Ishango, Lake Edward, Democratic Republic of the Congo",ys:-23000,ye:-18000,y:"c. 25,000–20,000 years ago",domain:"maths",also:[],t:"The Ishango bone: grouped notches on a tool handle",text:"A bone tool handle found in 1950 at Ishango, on the Congolese shore of Lake Edward, carries 168 incisions arranged in groups across three columns. Its excavator thought the groupings might reflect a mathematical link, making it one of the most discussed early marked objects.",disputed:true,note:"The meaning of the marks is unresolved. Readings as a tally, a lunar calendar or a record of prime numbers are interpretations, not established facts; the Royal Belgian Institute of Natural Sciences, which holds the bone, says it is still not clear what the marks represent. Dating is given as roughly 25,000–20,000 years ago for the lower layers at the site.",src:[SRCQ("Ishango – Bones with notches (Royal Belgian Institute of Natural Sciences)","https://ishango.naturalsciences.be/en/en-ishango-20.html","Supports World civilisations in parallel (History page)","The arrangement of these cuts made Jean de Heinzelin think there may be a mathematical link."),SRCQ("Ishango – Bones with notches (Royal Belgian Institute of Natural Sciences)","https://ishango.naturalsciences.be/en/en-ishango-20.html","Supports World civilisations in parallel (History page)","However, it is still not clear what they represent because the arrangements of the marks are so unique."),SRCQ("Ishango – Archaeological material (Royal Belgian Institute of Natural Sciences)","https://ishango.naturalsciences.be/en/en-ishango-13.html","Supports World civilisations in parallel (History page)","The majority of the objects were found in the lower layers of the stratigraphy and are very old, dating back to 25 000 to 20 000 years ago.")]},
 {id:"oceania-kuk-independent-invention-of-farming",region:"oceania",place:"Kuk, Western Highlands, Papua New Guinea",ys:-5000,ye:-4400,y:-4700,domain:"agriculture",also:[],t:"Kuk: independent invention of farming in New Guinea",text:"At Kuk swamp, people moved from gathering plants to farming them around 7,000–6,400 years ago, an independent invention of agriculture.",disputed:false,note:"'Years ago' converted to approximate calendar years. Begins before the timeline's 3500 BC start.",src:[SRCQ("Kuk Early Agricultural Site – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/887/","Supports World civilisations in parallel (History page)","demonstrates an independent technological leap which transformed plant exploitation to agriculture around 7,000-6,400 years")]},
 {id:"oceania-gunditjmara-build-eel-traps-at-budj-",region:"oceania",place:"Budj Bim, Victoria, Australia",ys:-4600,ye:1900,y:-1350,domain:"agriculture",also:["architecture"],t:"Gunditjmara build eel traps at Budj Bim",text:"The Gunditjmara people shaped lava-flow waterways at Budj Bim into channels, weirs and ponds to trap and farm eels; a Gunditjmara guide dates the system to about 6,600 years ago.",disputed:false,note:"Continuing practice; end year 1900 marks the timeline's end, not the end of the system.",src:[SRCQ("Indigenous aquaculture site Budj Bim (Council of Australasian Museum Directors)","https://camd.org.au/indigenous-aquaculture-site-budj-bim/","Supports World civilisations in parallel (History page)","this aquaculture system was first built 6,600 years ago")]},
 {id:"americas-north-old-copper-complex-early-nort",region:"americas-north",place:"Western Great Lakes, USA and Canada",ys:-4000,ye:-1000,y:-2500,domain:"metallurgy",also:[],t:"Old Copper complex: early North American metalworking",text:"As early as c. 4000 BC, Great Lakes peoples mined native copper and hammered it into tools and ornaments.",disputed:true,note:"Start dates vary; some studies place the earliest copper working thousands of years earlier. Mostly cold-worked, not smelted.",src:[SRCQ("Old Copper Complex in North America – EBSCO Research Starters","https://ebsco.com/research-starters/anthropology/old-copper-complex-north-america","Supports World civilisations in parallel (History page)","it became clear that Great Lakes Indians had developed a copper-based metal technology as early as 4000 B.C.E."),SRCQ("Old Copper Complex in North America – EBSCO Research Starters","https://ebsco.com/research-starters/anthropology/old-copper-complex-north-america","Supports World civilisations in parallel (History page)","utilizing techniques such as hot- and cold-hammering, grinding, and polishing to create a diverse array of tools and ornaments.")]},
 {id:"americas-north-first-peoples-cross-to-the-ca",region:"americas-north",place:"Caribbean (Trinidad to Cuba)",ys:-3520,ye:-3020,y:-3270,domain:"navigation",also:[],t:"First peoples cross to the Caribbean islands",text:"The earliest known evidence of people migrating into the Caribbean islands dates to c. 3520–3020 BC.",disputed:false,note:"The same source notes people reached Trinidad, then joined to South America, much earlier.",src:[SRCQ("Amerindian Migrations – Grenada National Museum teacher kit","https://www.grenadaarchaeology.com/TeacherKits/Assets/Lessons%20HTML/01_AmerindianMigrations_LessonPlan.htm","Supports World civilisations in parallel (History page)","The earliest known evidence of people migrating to the Caribbean dates back to between 3520-3020 BCE.")]},
 {id:"central-asia-botai-people-and-early-horse-he",region:"central-asia",place:"Botai, northern Kazakhstan",ys:-3500,ye:-3500,y:-3500,domain:"agriculture",also:[],t:"Botai people and early horse herding",text:"At Botai, c. 3500 BC, people kept large numbers of horses. Pottery residues suggest they used horse milk, but whether the horses were truly domesticated is debated.",disputed:true,note:"Strongly contested: ancient DNA studies suggest Botai horses were not ancestors of modern domestic horses.",src:[SRCQ("Humans domesticated horses – The Conversation","https://theconversation.com/humans-domesticated-horses-new-tech-could-help-archaeologists-figure-out-where-and-when-131831","Supports World civilisations in parallel (History page)","Researchers zeroed in on a site called Botai , in northern Kazakhstan, dating back to around 5,500 years ago."),SRCQ("Humans domesticated horses – The Conversation","https://theconversation.com/humans-domesticated-horses-new-tech-could-help-archaeologists-figure-out-where-and-when-131831","Supports World civilisations in parallel (History page)","Newer techniques cast doubt on Botai")]},
 {id:"central-asia-sarazm-bronze-age-metalworking-",region:"central-asia",place:"Sarazm, Tajikistan",ys:-3500,ye:-2000,y:-2750,domain:"metallurgy",also:["trade"],t:"Sarazm: Bronze Age metalworking and long-distance trade",text:"Sarazm was settled from the 4th to the late 3rd millennium BC. Its people worked copper and tin and traded across Central Asia.",disputed:false,note:"",src:[SRCQ("Proto-urban Site of Sarazm – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1141/","Supports World civilisations in parallel (History page)","from the 4th millennium BCE to the end of the 3rd millennium BCE"),SRCQ("Proto-urban Site of Sarazm – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1141/","Supports World civilisations in parallel (History page)","Sarazm demonstrates the existence of inter-regional trade and cultural interchanges over long distances across Central Asia.")]},
 {id:"americas-north-watson-brake-earthworks-built",region:"americas-north",place:"Ouachita Parish, Louisiana, USA",ys:-3500,ye:-2800,y:-3150,domain:"architecture",also:[],t:"Watson Brake earthworks built by hunter-gatherers",text:"Watson Brake, c. 3500–2800 BC, is among the oldest earthwork mound complexes in North America.",disputed:true,note:"Early dates for Watson Brake were resisted by some archaeologists when first published in the 1990s.",src:[SRCQ("Watson Brake Archaeological Site – 64 Parishes (Louisiana Endowment for the Humanities)","https://64parishes.org/?p=56285","Supports World civilisations in parallel (History page)","Watson Brake is a prehistoric Evans culture site in Ouachita Parish dating to 3500–2800 BCE."),SRCQ("Watson Brake Archaeological Site – 64 Parishes (Louisiana Endowment for the Humanities)","https://64parishes.org/?p=56285","Supports World civilisations in parallel (History page)","is among the oldest and best preserved Middle Archaic period (6000–2000 BCE) earthworks in the Southeast.")]},
 {id:"africa-north-early-egyptian-writing-on-royal",region:"africa-north",place:"Abydos, Egypt",ys:-3320,ye:-3320,y:"c. 3320 BC",domain:"writing",also:[],t:"Early Egyptian writing on royal tomb labels",text:"Tags and labels from the tombs of the first Egyptian kings carry some of the earliest writing in the Nile Valley. Egyptians developed their script at about the same time as Mesopotamians.",disputed:true,note:"The page gives \"about 3320 BC\"; dating of the earliest Egyptian writing is debated, and the source does not name the site.",src:[SRCQ("Origins of writing make for engaging new exhibition at Oriental Institute Museum | University of Chicago News","https://news.uchicago.edu/story/origins-writing-make-engaging-new-exhibition-oriental-institute-museum","Supports World civilisations in parallel (History page)","tags and labels from the tombs of the first kings (about 3320 BC)")]},
 {id:"east-asia-liangzhu-early-rice-farming-state-",region:"east-asia",place:"Liangzhu, Zhejiang, China",ys:-3300,ye:-2300,y:-2800,domain:"agriculture",also:["architecture"],t:"Liangzhu: early rice-farming state with water works",text:"Liangzhu, c. 3300–2300 BC, was an early regional state built on rice farming. It had urban planning and a large water conservation system.",disputed:false,note:"",src:[SRCQ("Archaeological Ruins of Liangzhu City – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1592/","Supports World civilisations in parallel (History page)","the archaeological ruins of Liangzhu (about 3,300-2,300 BCE)"),SRCQ("Archaeological Ruins of Liangzhu City – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1592/","Supports World civilisations in parallel (History page)","an early regional state with rice-cultivating agriculture")]},
 {id:"west-asia-uruk-becomes-the-first-true-city",region:"west-asia",place:"Uruk, Iraq",ys:-3200,ye:-3200,y:"c. 3200 BC",domain:"architecture",also:["governance"],t:"Uruk becomes the first true city",text:"Uruk was the largest settlement in southern Mesopotamia, and perhaps the world. It was a true city of monumental mud-brick buildings.",disputed:false,note:"",src:[SRCQ("Uruk: The First City - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/uruk/hd_uruk.htm","Supports World civilisations in parallel (History page)","By around 3200 B.C., the largest settlement in southern Mesopotamia, if not the world, was Uruk"),SRCQ("Uruk: The First City - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/uruk/hd_uruk.htm","Supports World civilisations in parallel (History page)","a true city dominated by monumental mud-brick buildings")]},
 {id:"west-asia-earliest-cuneiform-tablets-pictogr",region:"west-asia",place:"Uruk, Iraq",ys:-3200,ye:-3200,y:"c. 3200 BC",domain:"writing",also:[],t:"Earliest cuneiform tablets: pictographs on clay",text:"Pictographs drawn on clay tablets recorded goods and workers' rations. They developed into cuneiform, one of the first writing systems.",disputed:false,note:"",src:[SRCQ("Origins of writing make for engaging new exhibition at Oriental Institute Museum | University of Chicago News","https://news.uchicago.edu/story/origins-writing-make-engaging-new-exhibition-oriental-institute-museum","Supports World civilisations in parallel (History page)","the earliest cuneiform tablets from Mesopotamia (modern-day Iraq), dating to about 3200 BC"),SRCQ("Uruk: The First City - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/uruk/hd_uruk.htm","Supports World civilisations in parallel (History page)","These pictographs are the precursors of later cuneiform writing.")]},
 {id:"africa-north-memphis-becomes-capital-of-a-un",region:"africa-north",place:"Memphis, Egypt",ys:-3000,ye:-3000,y:"c. 3000 BC",domain:"governance",also:["architecture"],t:"Memphis becomes capital of a unified Egypt",text:"Memphis is traditionally said to have been founded as the capital of a politically unified Egypt. It stayed the seat of royal power for over eight dynasties.",disputed:true,note:"UNESCO gives this as a traditional date.",src:[SRCQ("Memphis and its Necropolis - the Pyramid Fields from Giza to Dahshur - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/86/","Supports World civilisations in parallel (History page)","Traditionally believed to have been founded in 3000 BC as the capital of a politically unified Egypt")]},
 {id:"africa-north-hieroglyphic-numerals-in-use-in",region:"africa-north",place:"Egypt",ys:-3000,ye:-3000,y:"c. 3000 BC",domain:"maths",also:["writing"],t:"Hieroglyphic numerals in use in Egypt",text:"Egyptians wrote numbers with hieroglyphic signs for ones, tens, hundreds and higher powers of ten. This decimal way of counting underpinned later Egyptian mathematics.",disputed:false,note:"Listed under the year -3000 in the MacTutor chronology.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 30000 BC - 500 BC","https://mathshistory.st-andrews.ac.uk/Chronology/1/","Supports World civilisations in parallel (History page)","Hieroglyphic numerals in use in Egypt.")]},
 {id:"europe-first-stonehenge-a-circular-ditch-and",region:"europe",place:"Stonehenge, England",ys:-3000,ye:-3000,y:"c. 3000 BC",domain:"architecture",also:[],t:"First Stonehenge: a circular ditch and bank",text:"The earliest known major event at Stonehenge was digging a circular ditch and bank. It was an early form of henge monument.",disputed:false,note:"",src:[SRCQ("History of Stonehenge | English Heritage","https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/","Supports World civilisations in parallel (History page)","the earliest known major event was the construction of a circular ditch with an inner and outer bank, built about 3000 BC")]},
 {id:"west-asia-base-60-counting-used-for-accounts",region:"west-asia",place:"Mesopotamia",ys:-3000,ye:-3000,y:"c. 3000 BC",domain:"maths",also:["trade"],t:"Base-60 counting used for accounts",text:"Mesopotamians began using a sexagesimal (base-60) place-value number system for financial records. We still use base 60 for hours, minutes and degrees.",disputed:true,note:"Listed under the year -3000 in the MacTutor chronology; the system developed over time.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 30000 BC - 500 BC","https://mathshistory.st-andrews.ac.uk/Chronology/1/","Supports World civilisations in parallel (History page)","Babylonians begin to use a sexagesimal number system for recording financial transactions.")]},
 {id:"south-asia-dholavira-s-walled-city-and-water",region:"south-asia",place:"Dholavira, Gujarat, India",ys:-3000,ye:-1500,y:-2250,domain:"architecture",also:["agriculture"],t:"Dholavira's walled city and water management",text:"Dholavira, a Harappan city in a dry region, was occupied c. 3000–1500 BC. Its people built a sophisticated system to collect and store scarce water.",disputed:false,note:"",src:[SRCQ("Dholavira: a Harappan City – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1645/","Supports World civilisations in parallel (History page)","Occupied between ca. 3000-1500 BCE, the archaeological site, one of the best preserved urban settlements from the period"),SRCQ("Dholavira: a Harappan City – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1645/","Supports World civilisations in parallel (History page)","A sophisticated water management system demonstrates the ingenuity of the Dholavira people in their struggle to survive")]},
 {id:"americas-andes-caral-earliest-known-civilisa",region:"americas-andes",place:"Caral, Supe valley, Peru",ys:-3000,ye:-1800,y:-2400,domain:"architecture",also:["governance"],t:"Caral: earliest known civilisation in the Americas",text:"Caral, built c. 3000–1800 BC, has monumental earthen platforms and sunken circular plazas. UNESCO calls it the earliest known civilisation in the Americas.",disputed:false,note:"",src:[SRCQ("Sacred City of Caral-Supe – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1269/","Supports World civilisations in parallel (History page)","in time between the years 3000 to 1800 B.C."),SRCQ("Sacred City of Caral-Supe – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1269/","Supports World civilisations in parallel (History page)","the earliest known manifestation of civilisation in the Americas.")]},
 {id:"africa-north-egyptian-civil-calendar-in-use",region:"africa-north",place:"Egypt",ys:-2770,ye:-2770,y:"c. 2770 BC",domain:"astronomy",also:[],t:"Egyptian civil calendar in use",text:"Egypt used a calendar to organise the year, linked to the seasons of the Nile. It is one of the earliest calendars on record.",disputed:true,note:"Chronology date; the origin of the Egyptian calendar is debated by scholars.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 30000 BC - 500 BC","https://mathshistory.st-andrews.ac.uk/Chronology/1/","Supports World civilisations in parallel (History page)","-2770 Egyptian calendar used.")]},
 {id:"west-asia-gilgamesh-king-of-uruk-later-hero-",region:"west-asia",place:"Uruk, Iraq",ys:-2700,ye:-2700,y:"c. 2700 BC",domain:"arts",also:["architecture"],t:"Gilgamesh, king of Uruk, later hero of epics",text:"Uruk was surrounded by a massive wall said to have been built by King Gilgamesh. He became the hero of many later stories and epics.",disputed:true,note:"Whether Gilgamesh was a historical king is uncertain.",src:[SRCQ("Uruk: The First City - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/uruk/hd_uruk.htm","Supports World civilisations in parallel (History page)","Although he may have been an actual king of Uruk around 2700 B.C., Gilgamesh became the hero of many later stories and epics.")]},
 {id:"africa-north-great-pyramid-of-khufu-built-at",region:"africa-north",place:"Giza, Egypt",ys:-2585,ye:-2560,y:"c. 2585-2560 BC",domain:"architecture",also:["maths"],t:"Great Pyramid of Khufu built at Giza",text:"The Great Pyramid was built for King Khufu during the Old Kingdom. It was the tallest human-made structure for thousands of years.",disputed:false,note:"",src:[SRCQ("Giza - Great Pyramid of Khufu - Institute of Egyptian Art & Archaeology (University of Memphis)","https://www.memphis.edu/egypt/resources/colortour/giza3.php","Supports World civilisations in parallel (History page)","The jagged edges of the Pyramid of Khufu [Cheops; c.2585-2560 B.C.E.]")]},
 {id:"europe-stonehenge-stones-raised-aligned-on-t",region:"europe",place:"Stonehenge, England",ys:-2500,ye:-2500,y:"c. 2500 BC",domain:"astronomy",also:["architecture"],t:"Stonehenge stones raised, aligned on the solstice",text:"Great stones were set up at the centre of Stonehenge in about 2500 BC. Monuments in the landscape keep their alignment on the solstice sunrise and sunset.",disputed:false,note:"",src:[SRCQ("History of Stonehenge | English Heritage","https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/","Supports World civilisations in parallel (History page)","In about 2500 BC the stones were set up in the centre of the monument."),SRCQ("Stonehenge, Avebury and Associated Sites - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/373/","Supports World civilisations in parallel (History page)","several monuments have retained their alignment on the Solstice sunrise and sunset")]},
 {id:"south-asia-mohenjo-daro-planned-city-with-sa",region:"south-asia",place:"Mohenjo-daro, Sindh, Pakistan",ys:-2500,ye:-1500,y:-2000,domain:"architecture",also:[],t:"Mohenjo-daro: planned city with sanitation and drainage",text:"Mohenjo-daro flourished c. 2500–1500 BC. Its baked-brick streets were laid out in an orderly plan with built-in sanitation and drainage.",disputed:false,note:"",src:[SRCQ("Archaeological Ruins at Moenjodaro – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/138/","Supports World civilisations in parallel (History page)","flourished between 2,500-1,500 BC"),SRCQ("Archaeological Ruins at Moenjodaro – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/138/","Supports World civilisations in parallel (History page)","a highly orderly form of city planning that also incorporated systems of sanitation and drainage")]},
 {id:"south-asia-harappans-adopt-uniform-decimal-w",region:"south-asia",place:"Indus valley (Harappa, Mohenjo-daro)",ys:-2500,ye:-1700,y:-2100,domain:"maths",also:["trade"],t:"Harappans adopt uniform decimal weights and measures",text:"The Indus civilisation, c. 2500–1700 BC, used a standard system of weights based on decimal ratios. Shared standards helped trade between its many towns.",disputed:false,note:"",src:[SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","It was a civilisation which began around 2500 BC and survived until 1700 BC or later."),SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","We do know that the Harappans had adopted a uniform system of weights and measures.")]},
 {id:"south-asia-indus-script-used-on-seals-and-ob",region:"south-asia",place:"Indus valley",ys:-2500,ye:-1700,y:-2100,domain:"writing",also:[],t:"Indus script used on seals and objects",text:"Harappan people wrote with a script of around 500 signs, c. 2500–1700 BC. It has not been convincingly deciphered.",disputed:false,note:"Britannica gives core dates of about 2600–1900 BCE for the civilisation; sources vary.",src:[SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","The people were literate and used a written script containing around 500 characters which some have claimed to have deciphered"),SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","It was a civilisation which began around 2500 BC and survived until 1700 BC or later.")]},
 {id:"south-asia-lothal-serves-as-a-harappan-port-",region:"south-asia",place:"Lothal, Gulf of Khambhat, Gujarat, India",ys:-2500,ye:-1700,y:-2100,domain:"trade",also:["navigation"],t:"Lothal serves as a Harappan port and trading post",text:"Lothal, on the Gulf of Khambhat, worked as a coastal trading station for the Indus civilisation, c. 2500–1700 BC.",disputed:false,note:"Date range is that of the Indus civilisation as a whole; the Lothal page itself gives no dates.",src:[SRCQ("Lothal – Britannica","https://www.britannica.com/place/Lothal","Supports World civilisations in parallel (History page)","the estuarine trading post at Lothal on the Gulf of Khambhat (Cambay)"),SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","It was a civilisation which began around 2500 BC and survived until 1700 BC or later.")]},
 {id:"central-asia-bronze-age-towns-of-the-murghab",region:"central-asia",place:"Merv oasis, Turkmenistan",ys:-2500,ye:-1200,y:-1850,domain:"architecture",also:[],t:"Bronze Age towns of the Murghab oasis",text:"The Merv oasis has supported towns since the 3rd millennium BC, with Bronze Age centres dating c. 2500–1200 BC.",disputed:false,note:"",src:[SRCQ("State Historical and Cultural Park 'Ancient Merv' – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/886/","Supports World civilisations in parallel (History page)","It has supported a series of urban centres since the 3rd millennium BC"),SRCQ("State Historical and Cultural Park 'Ancient Merv' – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/886/","Supports World civilisations in parallel (History page)","Bronze Age centres (2500-1200 BC)")]},
 {id:"americas-andes-quipu-knotted-cord-records",region:"americas-andes",place:"Andes",ys:-2500,ye:1532,y:-484,domain:"maths",also:["governance", "writing"],t:"Quipu: knotted-cord records",text:"Andean peoples recorded numbers on knotted cords, called quipu, from c. 2500 BC. The Inca used them for taxes, census data and storehouse stocks.",disputed:true,note:"Very early quipu dates are debated; the Caral find is cited by UNESCO.",src:[SRCQ("Quipu – Britannica","https://www.britannica.com/technology/quipu","Supports World civilisations in parallel (History page)","quipu, accounting apparatus used by Andean peoples from 2500 bce"),SRCQ("Quipu – Britannica","https://www.britannica.com/technology/quipu","Supports World civilisations in parallel (History page)","was used to record statistical information, such as taxes, census data, and storehouse inventories."),SRCQ("Sacred City of Caral-Supe – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1269/","Supports World civilisations in parallel (History page)","A quipu (the knot system used in Andean civilizations to record information)")]},
 {id:"europe-metalworking-knowledge-reaches-britai",region:"europe",place:"Wessex, England",ys:-2400,ye:-2400,y:"c. 2400 BC",domain:"metallurgy",also:[],t:"Metalworking knowledge reaches Britain with Beaker culture",text:"Knowledge of metalworking arrived in Britain from the Continent as Stonehenge was being built. Rich 'Beaker' graves such as the Amesbury Archer appear nearby.",disputed:false,note:"",src:[SRCQ("History of Stonehenge | English Heritage","https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/","Supports World civilisations in parallel (History page)","the knowledge of metalworking, together with a transition to the burial of individuals with grave goods, were arriving from the Continent"),SRCQ("History of Stonehenge | English Heritage","https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/","Supports World civilisations in parallel (History page)","From about 2400 BC, well-furnished Beaker graves such as that of the Amesbury Archer")]},
 {id:"west-asia-sargon-of-akkad-founds-the-first-e",region:"west-asia",place:"Agade (Akkad), Iraq",ys:-2340,ye:-2285,y:"c. 2340-2285 BC",domain:"governance",also:[],t:"Sargon of Akkad founds the first empire",text:"Sargon conquered southern Mesopotamia and founded the Akkadian empire. At its height it reached as far as Anatolia.",disputed:true,note:"Reign dates are approximate; \"first empire\" is a common description, not in the quoted text.",src:[SRCQ("The Akkadian Period (ca. 2350-2150 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/akka/hd_akka.htm","Supports World civilisations in parallel (History page)","Sargon (r. ca. 2340–2285 B.C.), the dynasty’s first king."),SRCQ("The Akkadian Period (ca. 2350-2150 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/akka/hd_akka.htm","Supports World civilisations in parallel (History page)","At its greatest extent, the empire reached as far as Anatolia in the north,")]},
 {id:"west-asia-dilmun-trading-port-flourishes-in-",region:"west-asia",place:"Qal'at al-Bahrain, Bahrain",ys:-2300,ye:-2300,y:"from c. 2300 BC",domain:"trade",also:["navigation"],t:"Dilmun trading port flourishes in the Gulf",text:"Qal'at al-Bahrain was a trading port and capital of Dilmun, one of the region's most important ancient civilisations.",disputed:false,note:"",src:[SRCQ("Qal'at al-Bahrain - Ancient Harbour and Capital of Dilmun - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1192/","Supports World civilisations in parallel (History page)","The strata of the 300 × 600 m tell testify to continuous human presence from about 2300 BC to the 16th century AD."),SRCQ("Qal'at al-Bahrain - Ancient Harbour and Capital of Dilmun - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1192/","Supports World civilisations in parallel (History page)","They testify to the importance of the site, a trading port, over the centuries.")]},
 {id:"africa-south-san-rock-painting-tradition-in-",region:"africa-south",place:"Maloti-Drakensberg, South Africa and Lesotho",ys:-2000,ye:1900,y:"c. 2000 BC - 19th century AD",domain:"arts",also:["learning"],t:"San rock painting tradition in the Drakensberg",text:"The San painted animals and people in the Drakensberg over some 4,000 years. The paintings show their spiritual life and beliefs, into the 19th century.",disputed:true,note:"Start date estimated from \"4,000 years\"; individual paintings are hard to date.",src:[SRCQ("Maloti-Drakensberg Park - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/985/","Supports World civilisations in parallel (History page)","its wealth of rock paintings made by the San people over a period of 4,000 years"),SRCQ("Maloti-Drakensberg Park - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/985/","Supports World civilisations in parallel (History page)","Rock art paintings dating back to the nineteenth and twentieth centuries")]},
 {id:"west-asia-hattusha-capital-of-the-hittite-em",region:"west-asia",place:"Hattusha, Turkey",ys:-2000,ye:-1200,y:"2nd millennium BC",domain:"governance",also:["architecture"],t:"Hattusha, capital of the Hittite Empire",text:"Hattusha was the capital of the Hittite Empire, which was powerful in Anatolia and northern Syria.",disputed:false,note:"End date approximates the end of the 2nd millennium BC.",src:[SRCQ("Hattusha: the Hittite Capital - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/377/","Supports World civilisations in parallel (History page)","The city enjoyed considerable influence in Anatolia and northern Syria in the 2nd millennium B.C.")]},
 {id:"oceania-kuk-farmers-drain-wetlands-with-ditc",region:"oceania",place:"Kuk, Western Highlands, Papua New Guinea",ys:-2000,ye:-2000,y:-2000,domain:"agriculture",also:[],t:"Kuk farmers drain wetlands with ditches",text:"From about 4,000 years ago, Kuk farmers dug ditches with wooden tools to drain the wetland for cultivation.",disputed:false,note:"",src:[SRCQ("Kuk Early Agricultural Site – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/887/","Supports World civilisations in parallel (History page)","to drainage of the wetlands through digging of ditches with wooden tools from 4,000 BP to the present.")]},
 {id:"west-asia-babylonians-solve-quadratic-equati",region:"west-asia",place:"Babylon, Iraq",ys:-1950,ye:-1950,y:"c. 1950 BC",domain:"maths",also:[],t:"Babylonians solve quadratic equations",text:"Babylonian scribes solved quadratic equations on clay tablets. They also compiled tables of squares and cube roots.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 30000 BC - 500 BC","https://mathshistory.st-andrews.ac.uk/Chronology/1/","Supports World civilisations in parallel (History page)","-1950 Babylonians solve quadratic equations.")]},
 {id:"africa-north-moscow-papyrus-records-egyptian",region:"africa-north",place:"Egypt",ys:-1900,ye:-1900,y:"c. 1900 BC",domain:"maths",also:[],t:"Moscow Papyrus records Egyptian geometry",text:"The Moscow papyrus is one of the oldest surviving mathematical texts. It includes geometry problems such as volumes.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 30000 BC - 500 BC","https://mathshistory.st-andrews.ac.uk/Chronology/1/","Supports World civilisations in parallel (History page)","-1900 The Moscow papyrus (also called the Golenishev papyrus) is written. It gives details of Egyptian geometry.")]},
 {id:"europe-minoan-palaces-and-linear-a-writing",region:"europe",place:"Knossos, Crete",ys:-1900,ye:-1900,y:"c. 1900 BC",domain:"writing",also:["architecture"],t:"Minoan palaces and Linear A writing",text:"Major palaces were built at Knossos and Mallia, and with them came writing. Linear A was perhaps inspired by eastern Mediterranean cuneiform.",disputed:false,note:"Linear A has not been deciphered.",src:[SRCQ("Minoan Crete - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/mino/hd_mino.htm","Supports World civilisations in parallel (History page)","Around 1900 B.C., during the Middle Minoan period"),SRCQ("Minoan Crete - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/mino/hd_mino.htm","Supports World civilisations in parallel (History page)","With the palaces came the development of writing"),SRCQ("Minoan Crete - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/mino/hd_mino.htm","Supports World civilisations in parallel (History page)","a linear script, Linear A, perhaps inspired by the cuneiform of the eastern Mediterranean")]},
 {id:"africa-north-first-alphabet-derived-from-egy",region:"africa-north",place:"Sinai, Egypt",ys:-1800,ye:-1800,y:"c. 1800 BC",domain:"writing",also:[],t:"First alphabet derived from Egyptian hieroglyphs",text:"The earliest alphabetic texts, found in the Sinai, adapted Egyptian hieroglyphs to write sounds. This alphabet is an ancestor of many later alphabets.",disputed:true,note:"Dating of Proto-Sinaitic inscriptions is debated; earlier views placed the first alphabet in Phoenicia about 1000 BC.",src:[SRCQ("Origins of writing make for engaging new exhibition at Oriental Institute Museum | University of Chicago News","https://news.uchicago.edu/story/origins-writing-make-engaging-new-exhibition-oriental-institute-museum","Supports World civilisations in parallel (History page)","This earliest alphabet was derived from Egyptian hieroglyphs as early as 1800 BC")]},
 {id:"west-asia-code-of-hammurabi-carved-on-a-ston",region:"west-asia",place:"Babylon, Iraq",ys:-1792,ye:-1750,y:"1792-1750 BC",domain:"governance",also:[],t:"Code of Hammurabi carved on a stone stele",text:"Hammurabi of Babylon had his laws and judgements carved on a stone stele. It is one of the best-known early law codes.",disputed:false,note:"Source is in French; dates are the reign of Hammurabi. Earlier law codes (such as that of Ur-Nammu) existed.",src:[SRCQ("Code de Hammurabi - Collections du Louvre","https://collections.louvre.fr/en/ark:/53355/cl010174436","Supports World civilisations in parallel (History page)","Code de Hammurabi"),SRCQ("Code de Hammurabi - Collections du Louvre","https://collections.louvre.fr/en/ark:/53355/cl010174436","Supports World civilisations in parallel (History page)","1ère dynastie de Babylone : Hammurabi (-1792 - -1750)")]},
 {id:"africa-north-rhind-papyrus-sets-out-egyptian",region:"africa-north",place:"Thebes, Egypt",ys:-1700,ye:-1650,y:"c. 1700-1650 BC",domain:"maths",also:[],t:"Rhind Papyrus sets out Egyptian arithmetic",text:"The Rhind (Ahmes) papyrus is a teaching text of worked problems. It shows multiplication by doubling and division by halving.",disputed:true,note:"MacTutor lists c. 1700 BC; it is dated by a reign year of the Hyksos king Apophis, usually placed in the mid-17th to 16th century BC. Place is the usual attribution, not stated in the sources.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 30000 BC - 500 BC","https://mathshistory.st-andrews.ac.uk/Chronology/1/","Supports World civilisations in parallel (History page)","-1700 The Rhind papyrus (sometimes called the Ahmes papyrus) is written."),SRCQ("Papyrus Edwin Smith - Science in Ancient Egypt (Saxon Academy of Sciences in Leipzig)","https://sae.saw-leipzig.de/en/documents/papyrus-edwin-smith","Supports World civilisations in parallel (History page)","the Rhind mathematical papyrus (year 33 of the Hyksos king Apophis)")]},
 {id:"americas-north-poverty-point-earthworks-and-",region:"americas-north",place:"Poverty Point, Louisiana, USA",ys:-1700,ye:-1100,y:-1400,domain:"architecture",also:["trade"],t:"Poverty Point earthworks and trade network",text:"Hunter-fisher-gatherers built the Poverty Point earthworks c. 3,700–3,100 years ago, supplied by trade in stone from far away.",disputed:false,note:"'Years ago' converted to approximate calendar years.",src:[SRCQ("Monumental Earthworks of Poverty Point – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1435/","Supports World civilisations in parallel (History page)","in the main constructed 3,700-3,100 years ago in the Late Archaic period."),SRCQ("Monumental Earthworks of Poverty Point – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1435/","Supports World civilisations in parallel (History page)","Thus, an extensive trade network for rocks and minerals from hundreds of kilometres away")]},
 {id:"africa-north-edwin-smith-papyrus-early-surgi",region:"africa-north",place:"Egypt",ys:-1650,ye:-1550,y:"c. 1650-1550 BC",domain:"medicine",also:[],t:"Edwin Smith Papyrus: early surgical treatise copied",text:"The Edwin Smith papyrus describes the examination and treatment of injuries in a careful, case-by-case way. The surviving copy may come from an older original.",disputed:true,note:"Copy date estimates range from c. 1650 to c. 1550 BC; the original text may be centuries older.",src:[SRCQ("Papyrus Edwin Smith - Science in Ancient Egypt (Saxon Academy of Sciences in Leipzig)","https://sae.saw-leipzig.de/en/documents/papyrus-edwin-smith","Supports World civilisations in parallel (History page)","which he situates in the period 1650-1550 BC")]},
 {id:"oceania-lapita-voyagers-settle-the-western-p",region:"oceania",place:"Bismarck Archipelago to Samoa",ys:-1600,ye:-500,y:-1050,domain:"navigation",also:["arts"],t:"Lapita voyagers settle the western Pacific",text:"Lapita seafarers spread from the Bismarck Archipelago to the Solomons from c. 1600 BC and reached Fiji, Tonga and Samoa by 1000 BC.",disputed:true,note:"Many archaeologists now date Lapita's start to c. 1350–1300 BC, later than Britannica's 1600 BC.",src:[SRCQ("Lapita culture – Britannica","https://www.britannica.com/topic/Lapita-culture","Supports World civilisations in parallel (History page)","Beginning about 1600 bce they spread to the Solomon Islands;"),SRCQ("Lapita culture – Britannica","https://www.britannica.com/topic/Lapita-culture","Supports World civilisations in parallel (History page)","they had reached Fiji, Tonga, and the rest of western Polynesia by 1000 bce;")]},
 {id:"americas-andes-chav-n-de-hu-ntar-temple-and-",region:"americas-andes",place:"Chavín de Huántar, Áncash, Peru",ys:-1500,ye:-300,y:-900,domain:"architecture",also:[],t:"Chavín de Huántar temple and galleries",text:"Chavín de Huántar developed c. 1500–300 BC. Its temple has an internal network of galleries, vents and drains unmatched in South America.",disputed:false,note:"",src:[SRCQ("Chavin (Archaeological Site) – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/330/","Supports World civilisations in parallel (History page)","developed between 1500 and 300 B.C. in this high valley of the Peruvian Andes"),SRCQ("Chavin (Archaeological Site) – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/330/","Supports World civilisations in parallel (History page)","containing an internal gallery system with an intricate network of vents and drains unprecedented in South America")]},
 {id:"southeast-asia-ban-chiang-early-bronze-makin",region:"southeast-asia",place:"Ban Chiang, Udon Thani, Thailand",ys:-1495,ye:-900,y:-1198,domain:"metallurgy",also:["agriculture"],t:"Ban Chiang: early bronze-making and rice farming",text:"Ban Chiang was occupied from 1495 BC to c. 900 BC. It holds early evidence of bronze-making and of rice farming in the region.",disputed:true,note:"Ban Chiang's chronology has been revised several times since 1966; UNESCO notes the dating has been 'adjusted and refined'.",src:[SRCQ("Ban Chiang Archaeological Site – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/575/","Supports World civilisations in parallel (History page)","the site was continuously occupied from 1495BC until c. 900BC."),SRCQ("Ban Chiang Archaeological Site – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/575/","Supports World civilisations in parallel (History page)","In addition to ceramics, the site has exceptional and uniquely early evidence of the knowledge of bronze-making")]},
 {id:"east-asia-shang-oracle-bone-inscriptions-ear",region:"east-asia",place:"Yin Xu, Anyang, Henan, China",ys:-1300,ye:-1046,y:-1173,domain:"writing",also:[],t:"Shang oracle-bone inscriptions: earliest mature Chinese writing",text:"At the late Shang capital of Yin Xu (c. 1300–1046 BC), inscriptions on oracle bones are the earliest known mature writing in China.",disputed:false,note:"",src:[SRCQ("Yin Xu – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1114/","Supports World civilisations in parallel (History page)","is an ancient capital city of the late Shang Dynasty (1300 - 1046 BC)."),SRCQ("Yin Xu – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1114/","Supports World civilisations in parallel (History page)","oracle bone inscriptions are the earliest known mature writing in China")]},
 {id:"east-asia-shang-bronze-casting-reaches-a-hig",region:"east-asia",place:"Yin Xu, Anyang, Henan, China",ys:-1300,ye:-1046,y:-1173,domain:"metallurgy",also:["astronomy"],t:"Shang bronze casting reaches a high level",text:"The late Shang capital, c. 1300–1046 BC, shows advanced bronze casting alongside a calendar system.",disputed:false,note:"",src:[SRCQ("Yin Xu – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1114/","Supports World civilisations in parallel (History page)","reflecting highly developed science and architectural technology including bronze casting and a calendar system."),SRCQ("Yin Xu – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1114/","Supports World civilisations in parallel (History page)","is an ancient capital city of the late Shang Dynasty (1300 - 1046 BC).")]},
 {id:"west-asia-elamite-ziggurat-of-choga-zanbil-b",region:"west-asia",place:"Choga Zanbil, Iran",ys:-1250,ye:-1250,y:"c. 1250 BC",domain:"architecture",also:[],t:"Elamite ziggurat of Choga Zanbil built",text:"The Elamite king Untash-Napirisha founded Choga Zanbil with an enormous ziggurat. It is the largest ziggurat outside Mesopotamia.",disputed:false,note:"",src:[SRCQ("Tchogha Zanbil - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/113/","Supports World civilisations in parallel (History page)","Founded c. 1250 B.C."),SRCQ("Tchogha Zanbil - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/113/","Supports World civilisations in parallel (History page)","It is the largest ziggurat outside of Mesopotamia and the best preserved of this type of stepped pyramidal monument.")]},
 {id:"americas-meso-olmec-civilisation-sets-mesoam",region:"americas-meso",place:"Gulf Coast, Mexico",ys:-1200,ye:-400,y:-800,domain:"arts",also:["governance"],t:"Olmec civilisation sets Mesoamerican patterns",text:"The Olmec, c. 1200–400 BC, were the first elaborate civilisation of Mesoamerica, known for colossal basalt heads.",disputed:false,note:"",src:[SRCQ("Olmec – Britannica","https://www.britannica.com/topic/Olmec","Supports World civilisations in parallel (History page)","the first elaborate pre-Columbian civilization of Mesoamerica (c. 1200–400 BCE)"),SRCQ("Olmec – Britannica","https://www.britannica.com/topic/Olmec","Supports World civilisations in parallel (History page)","set many of the fundamental patterns evinced by later American Indian cultures of Mexico and Central America")]},
 {id:"west-asia-phoenician-alphabet-spreads-across",region:"west-asia",place:"Byblos and Phoenician cities, Lebanon",ys:-1000,ye:-1000,y:"c. 1000 BC",domain:"writing",also:[],t:"Phoenician alphabet spreads across the Mediterranean",text:"The Phoenicians used an alphabetic script that became the root of Western alphabets. Byblos is linked with its spread.",disputed:true,note:"Earlier alphabetic texts from Sinai (c. 1800 BC) mean the Phoenician script was a development, not the first alphabet.",src:[SRCQ("The Phoenicians (1500-300 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/phoe/hd_phoe.htm","Supports World civilisations in parallel (History page)","an alphabetic writing system that became the root of the Western alphabets"),SRCQ("Origins of writing make for engaging new exhibition at Oriental Institute Museum | University of Chicago News","https://news.uchicago.edu/story/origins-writing-make-engaging-new-exhibition-oriental-institute-museum","Supports World civilisations in parallel (History page)","Long believed to have been invented in Phoenicia about 1000 BC"),SRCQ("Byblos - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/295/","Supports World civilisations in parallel (History page)","Byblos is also directly associated with the history and diffusion of the Phoenician alphabet.")]},
 {id:"africa-north-napatan-kush-builds-temples-pal",region:"africa-north",place:"Napata (Gebel Barkal), Sudan",ys:-900,ye:-270,y:"900-270 BC",domain:"architecture",also:["governance"],t:"Napatan Kush builds temples, palaces and pyramids",text:"At Gebel Barkal the Napatan kingdom of Kush built temples, palaces and royal tombs, some with pyramids. Kush was a major Nile power in its own right.",disputed:false,note:"",src:[SRCQ("Gebel Barkal and the Sites of the Napatan Region - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1073/","Supports World civilisations in parallel (History page)","Napatan (900 to 270 BC) and Meroitic (270 BC to 350 AD) cultures, of the second kingdom of Kush.")]},
 {id:"africa-north-carthage-founded-on-the-gulf-of",region:"africa-north",place:"Carthage, Tunisia",ys:-814,ye:-814,y:"814 BC (traditional)",domain:"trade",also:["navigation", "governance"],t:"Carthage founded on the Gulf of Tunis",text:"Phoenician settlers founded Carthage, which became a great trading empire across much of the Mediterranean. It lasted until Rome destroyed it in 146 BC.",disputed:true,note:"814 BC is the traditional date.",src:[SRCQ("The Phoenicians (1500-300 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/phoe/hd_phoe.htm","Supports World civilisations in parallel (History page)","Carthage (a Phoenician colony traditionally founded in 814 B.C.)"),SRCQ("Archaeological Site of Carthage - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/37/","Supports World civilisations in parallel (History page)","Carthage was founded in the 9th century B.C. on the Gulf of Tunis.")]},
 {id:"south-asia-baudhayana-sulbasutra-geometry-fo",region:"south-asia",place:"Northern India",ys:-800,ye:-800,y:-800,domain:"maths",also:[],t:"Baudhayana Sulbasutra: geometry for altar building",text:"The Baudhayana Sulbasutra, written c. 800 BC, gave geometric rules for building altars, including Pythagorean triples.",disputed:true,note:"Dates of the Sulbasutras are approximate; MacTutor gives the texts a span of about the 15th to 5th century BC.",src:[SRCQ("The Indian Sulbasutras – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_sulbasutras/","Supports World civilisations in parallel (History page)","The most important of these documents are the Baudhayana Sulbasutra written about 800 BC"),SRCQ("The Indian Sulbasutras – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_sulbasutras/","Supports World civilisations in parallel (History page)","there are many examples of Pythagorean triples in the Sulbasutras.")]},
 {id:"oceania-polynesian-ancestors-settle-samoa",region:"oceania",place:"Samoa",ys:-800,ye:-800,y:-800,domain:"navigation",also:[],t:"Polynesian ancestors settle Samoa",text:"Polynesian ancestors had settled in Samoa by around 800 BC.",disputed:false,note:"",src:[SRCQ("East Polynesia colonized faster and more recently than previously thought – University of Hawaiʻi","https://manoa.hawaii.edu/news/article.php?aId=4097","Supports World civilisations in parallel (History page)","Polynesian ancestors settled in Samoa around 800 B.C.")]},
 {id:"africa-north-kingdom-of-kush-rules-the-middl",region:"africa-north",place:"Meroe, Sudan",ys:-750,ye:350,y:"8th century BC - 4th century AD",domain:"governance",also:["trade"],t:"Kingdom of Kush rules the Middle Nile",text:"Kush was a major power for over a thousand years and its rulers occupied Egypt for close to a century. Meroe was its heartland.",disputed:false,note:"",src:[SRCQ("Archaeological Sites of the Island of Meroe - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1336/","Supports World civilisations in parallel (History page)","was the heartland of the Kingdom of Kush, a major power from the 8th century B.C. to the 4th century A.D."),SRCQ("Archaeological Sites of the Island of Meroe - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1336/","Supports World civilisations in parallel (History page)","It was the seat of the rulers who occupied Egypt for close to a century")]},
 {id:"west-asia-phoenician-sea-traders-found-tradi",region:"west-asia",place:"Phoenicia (Lebanon) and the Mediterranean",ys:-750,ye:-700,y:"by late 8th century BC",domain:"navigation",also:["trade"],t:"Phoenician sea traders found trading posts",text:"Phoenician sailors set up trading posts around the Mediterranean, alongside the Greeks. They were famous seafarers and traders.",disputed:false,note:"",src:[SRCQ("The Phoenicians (1500-300 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/phoe/hd_phoe.htm","Supports World civilisations in parallel (History page)","By the late eighth century B.C., the Phoenicians, alongside the Greeks, had founded trading posts"),SRCQ("The Phoenicians (1500-300 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/phoe/hd_phoe.htm","Supports World civilisations in parallel (History page)","Sea traders from Phoenicia and Carthage")]},
 {id:"central-asia-samarkand-founded-as-afrasiab",region:"central-asia",place:"Samarkand (Afrasiab), Uzbekistan",ys:-700,ye:-601,y:-650,domain:"architecture",also:["trade"],t:"Samarkand founded as Afrasiab",text:"Samarkand was founded as Afrasiab in the 7th century BC and grew into a great crossroads city of the Silk Roads.",disputed:false,note:"",src:[SRCQ("Samarkand – Crossroad of Cultures – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/603/","Supports World civilisations in parallel (History page)","Founded in the 7th century B.C. as ancient Afrasiab")]},
 {id:"west-asia-ashurbanipal-s-library-gathers-ove",region:"west-asia",place:"Nineveh, Iraq",ys:-668,ye:-631,y:"668-631 BC",domain:"learning",also:["writing"],t:"Ashurbanipal's library gathers over 30,000 tablets",text:"King Ashurbanipal assembled a great library at Nineveh. Over 30,000 cuneiform tablets were found in its ruins.",disputed:false,note:"",src:[SRCQ("What was Ashurbanipal's Library? - British Museum","https://www.britishmuseum.org/research/projects/what-was-ashurbanipals-library","Supports World civilisations in parallel (History page)","Over 30,000 clay tablets covered in cuneiform writing were found in the ruins of Nineveh (Iraq)"),SRCQ("What was Ashurbanipal's Library? - British Museum","https://www.britishmuseum.org/research/projects/what-was-ashurbanipals-library","Supports World civilisations in parallel (History page)","the capital of the Assyrian King Ashurbanipal's (668–631 BC) empire.")]},
 {id:"west-asia-lydians-invent-coinage",region:"west-asia",place:"Sardis, Turkey",ys:-650,ye:-600,y:"7th century BC",domain:"trade",also:["metallurgy"],t:"Lydians invent coinage",text:"Ancient writers credited the Lydians with inventing coins, first made of electrum, a natural gold-silver alloy. Coins were minted at Sardis for about 1,000 years.",disputed:true,note:"Exact date of the first coins is debated (late 7th century BC is widely cited).",src:[SRCQ("The Coins of Sardis (J. H. Kroll), The Lydians and their World - The Archaeological Exploration of Sardis (Harvard)","https://sardisexpedition.org/en/essays/latw-kroll-coins-of-sardis","Supports World civilisations in parallel (History page)","Xenophanes of Colophon, explicitly attributed the very invention of coinage to the Lydians"),SRCQ("The Coins of Sardis (J. H. Kroll), The Lydians and their World - The Archaeological Exploration of Sardis (Harvard)","https://sardisexpedition.org/en/essays/latw-kroll-coins-of-sardis","Supports World civilisations in parallel (History page)","the history of coinage produced at Sardis stretched from the seventh century BCE to the third century CE")]},
 {id:"west-asia-babylon-rebuilt-as-neo-babylonian-",region:"west-asia",place:"Babylon, Iraq",ys:-626,ye:-539,y:"626-539 BC",domain:"architecture",also:["governance"],t:"Babylon rebuilt as Neo-Babylonian capital",text:"Babylon was the capital of the Neo-Babylonian Empire under rulers such as Nebuchadnezzar. It is linked with the Hanging Gardens, a wonder of the ancient world.",disputed:true,note:"The existence and location of the Hanging Gardens are debated.",src:[SRCQ("Babylon - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/278/","Supports World civilisations in parallel (History page)","between 626 and 539 BCE, was the capital of the Neo-Babylonian Empire"),SRCQ("Babylon - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/278/","Supports World civilisations in parallel (History page)","The city's association with one of the seven wonders of the ancient world—the Hanging Gardens")]},
 {id:"south-asia-sushruta-s-treatise-on-surgery",region:"south-asia",place:"Ancient India",ys:-600,ye:-501,y:-550,domain:"medicine",also:[],t:"Sushruta's treatise on surgery",text:"The surgeon Sushruta, active c. 6th century BC, is known for the Sushruta-samhita and early operations such as rebuilding the nose.",disputed:true,note:"Dating of Sushruta and the compilation of the Sushruta-samhita is debated; many scholars place the text later.",src:[SRCQ("Sushruta – Britannica","https://www.britannica.com/biography/Sushruta","Supports World civilisations in parallel (History page)","Sushruta (flourished c. 6th century bce) was an ancient Indian surgeon known for his pioneering operations and techniques"),SRCQ("Sushruta – Britannica","https://www.britannica.com/biography/Sushruta","Supports World civilisations in parallel (History page)","Examples of some of his groundbreaking operations include rhinoplasty (the repairing or remaking of a nose),")]},
 {id:"west-asia-first-pure-gold-coins-struck-in-ly",region:"west-asia",place:"Sardis, Turkey",ys:-560,ye:-546,y:"before c. 545 BC",domain:"metallurgy",also:["trade"],t:"First pure gold coins struck in Lydia",text:"Lydia's king Croesus introduced coins of solid gold, called Croeseids. Making them needed ways to separate gold from silver.",disputed:true,note:"Croesus reigned c. 560-546 BC (not stated in the quoted text); the start of refining is debated.",src:[SRCQ("The Coins of Sardis (J. H. Kroll), The Lydians and their World - The Archaeological Exploration of Sardis (Harvard)","https://sardisexpedition.org/en/essays/latw-kroll-coins-of-sardis","Supports World civilisations in parallel (History page)","The earliest coins made of solid gold were known throughout the ancient Greek world as “Croeseids,” after the Lydian king who introduced them."),SRCQ("The Coins of Sardis (J. H. Kroll), The Lydians and their World - The Archaeological Exploration of Sardis (Harvard)","https://sardisexpedition.org/en/essays/latw-kroll-coins-of-sardis","Supports World civilisations in parallel (History page)","demolished during the Persian capture of Sardis in the mid-540s BCE, the excavators discovered two small specimens of the reformed coinage")]},
 {id:"east-asia-confucius-teaches-ethics-and-state",region:"east-asia",place:"Qufu, state of Lu, China",ys:-551,ye:-479,y:-515,domain:"learning",also:["governance"],t:"Confucius teaches ethics and statecraft",text:"Confucius (551–479 BC) became China's most famous teacher and political thinker. The Analects record his teaching.",disputed:false,note:"",src:[SRCQ("Confucius – Britannica","https://www.britannica.com/biography/Confucius","Supports World civilisations in parallel (History page)","(born 551, Qufu, state of Lu [now in Shandong province, China]—died 479 bce, Lu)"),SRCQ("Confucius – Britannica","https://www.britannica.com/biography/Confucius","Supports World civilisations in parallel (History page)","China’s most famous teacher, philosopher, and political theorist")]},
 {id:"west-asia-achaemenid-persia-builds-roads-and",region:"west-asia",place:"Persia (Iran)",ys:-550,ye:-486,y:"550-486 BC",domain:"governance",also:["trade"],t:"Achaemenid Persia builds roads and a governor system",text:"The Achaemenid Empire formed from 550 BC. Darius I stabilised it with roads for communication and provincial governors (satraps).",disputed:false,note:"",src:[SRCQ("The Achaemenid Persian Empire (550-330 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/acha/hd_acha.htm","Supports World civilisations in parallel (History page)","Its formation began in 550 B.C."),SRCQ("The Achaemenid Persian Empire (550-330 B.C.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/acha/hd_acha.htm","Supports World civilisations in parallel (History page)","Under Darius the empire was stabilized, with roads for communication and a system of governors (satraps) established.")]},
 {id:"south-asia-panini-writes-a-scientific-gramma",region:"south-asia",place:"Shalatula, near Attock, Pakistan",ys:-520,ye:-460,y:-490,domain:"learning",also:[],t:"Panini writes a scientific grammar of Sanskrit",text:"Panini, c. 520–460 BC, set out a comprehensive theory of Sanskrit sound and word structure. His dates are uncertain.",disputed:true,note:"MacTutor gives about 520–460 BC but notes experts date him anywhere from the 7th to the 4th century BC.",src:[SRCQ("Panini – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Panini/","Supports World civilisations in parallel (History page)","Panini was a Sanskrit grammarian who gave a comprehensive and scientific theory of phonetics, phonology, and morphology."),SRCQ("Panini – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Panini/","Supports World civilisations in parallel (History page)","Experts give dates in the 4 th , 5 th , 6 th and 7 th century BC")]},
 {id:"west-asia-darius-i-founds-persepolis",region:"west-asia",place:"Persepolis, Iran",ys:-518,ye:-518,y:"518 BC",domain:"architecture",also:[],t:"Darius I founds Persepolis",text:"Darius I founded Persepolis as a capital of the Achaemenid Empire. Its terrace palaces are among the great works of ancient architecture.",disputed:false,note:"",src:[SRCQ("Persepolis - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/114/","Supports World civilisations in parallel (History page)","Founded by Darius I in 518 B.C., Persepolis was the capital of the Achaemenid Empire.")]},
 {id:"africa-west-nok-culture-early-ironworking-an",region:"africa-west",place:"Nok, Jos Plateau, Nigeria",ys:-500,ye:200,y:"500 BC - AD 200",domain:"metallurgy",also:["arts"],t:"Nok culture: early ironworking and terracotta sculpture",text:"The Nok culture made striking terracotta figures and was one of the earliest centres of ironworking in Africa. Many questions about it remain open.",disputed:true,note:"Date range is the Met heading; ironworking dates in the region are debated.",src:[SRCQ("Nok Terracottas (500 B.C.-200 A.D.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/nok/hd_nok.htm","Supports World civilisations in parallel (History page)","Nok Terracottas (500 B.C.–200 A.D.)"),SRCQ("Nok Terracottas (500 B.C.-200 A.D.) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/nok/hd_nok.htm","Supports World civilisations in parallel (History page)","One of the earliest African centers of ironworking and terracotta figure production, the Nok culture remains an enigma.")]},
 {id:"west-asia-shushtar-hydraulic-system-for-wate",region:"west-asia",place:"Shushtar, Iran",ys:-500,ye:-401,y:"5th century BC",domain:"agriculture",also:["architecture"],t:"Shushtar hydraulic system for water and mills",text:"The hydraulic system at Shushtar, traced back to Darius the Great, used tunnels and channels to supply water to the city and its mills.",disputed:false,note:"",src:[SRCQ("Shushtar Historical Hydraulic System - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1315/","Supports World civilisations in parallel (History page)","can be traced back to Darius the Great in the 5th century B.C."),SRCQ("Shushtar Historical Hydraulic System - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1315/","Supports World civilisations in parallel (History page)","providing water to the city of Shushtar via a series of tunnels that supply water to mills")]},
 {id:"west-asia-babylonians-predict-planetary-posi",region:"west-asia",place:"Babylon, Iraq",ys:-500,ye:-500,y:"c. 500 BC",domain:"astronomy",also:["maths"],t:"Babylonians predict planetary positions mathematically",text:"Babylonian astronomers used their base-60 numbers to record and predict the positions of the Sun, Moon and planets.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-500 The Babylonian sexagesimal number system is used to record and predict the positions of the Sun, Moon and planets.")]},
 {id:"south-asia-taxila-becomes-a-buddhist-centre-",region:"south-asia",place:"Taxila, Punjab, Pakistan",ys:-500,ye:200,y:-150,domain:"learning",also:[],t:"Taxila becomes a Buddhist centre of learning",text:"From c. 5th century BC to the 2nd century AD, Taxila was an important Buddhist centre of learning on routes linking South and Central Asia.",disputed:false,note:"",src:[SRCQ("Taxila – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/139/","Supports World civilisations in parallel (History page)","from the 5th century B.C. to the 2nd century A.D., was an important Buddhist centre of learning.")]},
 {id:"east-asia-grand-canal-links-china-s-great-ri",region:"east-asia",place:"Eastern China",ys:-500,ye:1300,y:400,domain:"trade",also:["architecture"],t:"Grand Canal links China's great rivers",text:"Built in sections from the 5th century BC, the Grand Canal became one unified waterway in the 7th century AD. By the 13th century it ran over 2,000 km.",disputed:false,note:"",src:[SRCQ("The Grand Canal – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1443/","Supports World civilisations in parallel (History page)","Constructed in sections from the 5th century BC onwards,"),SRCQ("The Grand Canal – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1443/","Supports World civilisations in parallel (History page)","By the 13th century it consisted of more than 2,000 km of artificial waterways, linking five of China's main river basins.")]},
 {id:"southeast-asia-dong-son-bronze-culture",region:"southeast-asia",place:"Red River valley, northern Viet Nam",ys:-500,ye:-1,y:-250,domain:"metallurgy",also:["arts"],t:"Dong Son bronze culture",text:"The Dong Son culture of northern Viet Nam, c. 5th–1st century BC, is known for its bronze work, including large decorated drums.",disputed:false,note:"The quote is a section heading on the Britannica page; the drums are not described on that page.",src:[SRCQ("Southeast Asian arts – Vietnam – Britannica","https://www.britannica.com/art/Southeast-Asian-arts/Vietnam-kingdom-of-Champa-c-2nd-15th-century","Supports World civilisations in parallel (History page)","Bronze Age: Dong Son culture (c. 5th–1st century bce)")]},
 {id:"central-asia-pazyryk-tombs-preserve-textiles",region:"central-asia",place:"Pazyryk, Altai Mountains, Russia",ys:-500,ye:-201,y:-350,domain:"arts",also:[],t:"Pazyryk tombs preserve textiles and tattoos",text:"Frozen tombs at Pazyryk, c. 5th–3rd century BC, preserved some of the oldest surviving textiles and a man covered in tattoos.",disputed:false,note:"",src:[SRCQ("Pazyryk – Britannica","https://www.britannica.com/place/Pazyryk","Supports World civilisations in parallel (History page)","dates from about the 5th to the 3rd century bc"),SRCQ("Pazyryk – Britannica","https://www.britannica.com/place/Pazyryk","Supports World civilisations in parallel (History page)","an embalmed man covered with tattoos, some of the oldest textiles extant.")]},
 {id:"americas-meso-monte-alb-n-zapotec-capital",region:"americas-meso",place:"Oaxaca, Mexico",ys:-500,ye:850,y:175,domain:"governance",also:["writing"],t:"Monte Albán: Zapotec capital",text:"Monte Albán was the great Zapotec capital for thirteen centuries, from 500 BC to AD 850. Its monuments carry hieroglyphic inscriptions.",disputed:false,note:"",src:[SRCQ("Historic Centre of Oaxaca and Archaeological Site of Monte Albán – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/415/","Supports World civilisations in parallel (History page)","flourished for thirteen centuries, from the year 500 B.C to 850 A.D."),SRCQ("Historic Centre of Oaxaca and Archaeological Site of Monte Albán – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/415/","Supports World civilisations in parallel (History page)","bas-reliefs with hieroglyphic inscriptions")]},
 {id:"americas-andes-nasca-lines-scratched-into-th",region:"americas-andes",place:"Nasca desert, Peru",ys:-500,ye:500,y:"-500",domain:"arts",also:[],t:"Nasca lines scratched into the desert",text:"Between 500 BC and AD 500 people scratched huge lines and figures into the surface of the Nasca desert.",disputed:false,note:"",src:[SRCQ("Lines and Geoglyphs of Nasca and Palpa – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/700/","Supports World civilisations in parallel (History page)","These lines, which were scratched on the surface of the ground between 500 B.C. and A.D. 500")]},
 {id:"americas-north-saladoid-farmers-and-potters-",region:"americas-north",place:"Lesser and Greater Antilles",ys:-500,ye:-500,y:-500,domain:"agriculture",also:["navigation", "arts"],t:"Saladoid farmers and potters settle the Caribbean",text:"Around 500 BC Saladoid people from the Orinoco basin in Venezuela moved into the Caribbean islands, bringing farming and pottery.",disputed:false,note:"",src:[SRCQ("Amerindian Migrations – Grenada National Museum teacher kit","https://www.grenadaarchaeology.com/TeacherKits/Assets/Lessons%20HTML/01_AmerindianMigrations_LessonPlan.htm","Supports World civilisations in parallel (History page)","Around 500 BCE, the Saladoid people from the Orinoco River Basin in Venezuela entered the Lesser Antilles and traveled northwest to Cuba."),SRCQ("Amerindian Migrations – Grenada National Museum teacher kit","https://www.grenadaarchaeology.com/TeacherKits/Assets/Lessons%20HTML/01_AmerindianMigrations_LessonPlan.htm","Supports World civilisations in parallel (History page)","These settlers are credited with advances in agriculture and their use of ceramics and pottery.")]},
 {id:"europe-parthenon-and-acropolis-monuments-bui",region:"europe",place:"Athens, Greece",ys:-450,ye:-401,y:"second half of 5th century BC",domain:"arts",also:["architecture"],t:"Parthenon and Acropolis monuments built in Athens",text:"Under the statesman Pericles, artists built the Parthenon and other monuments on the Acropolis. UNESCO links the site with the birth of democracy and philosophy.",disputed:false,note:"",src:[SRCQ("Acropolis, Athens - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/404/","Supports World civilisations in parallel (History page)","In the second half of the fifth century bc, Athens, following the victory against the Persians"),SRCQ("Acropolis, Athens - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/404/","Supports World civilisations in parallel (History page)","The most important monuments were built during that time: the Parthenon, built by Ictinus")]},
 {id:"europe-first-compilation-of-the-elements-of-",region:"europe",place:"Chios and Athens, Greece",ys:-440,ye:-440,y:"c. 440 BC",domain:"maths",also:[],t:"First compilation of the elements of geometry",text:"Hippocrates of Chios wrote the first known collection of the basic results of geometry, before Euclid.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-440 Hippocrates of Chios writes the Elements which is the first compilation of the elements of geometry.")]},
 {id:"west-asia-babylonians-use-a-placeholder-sign",region:"west-asia",place:"Babylon, Iraq",ys:-400,ye:-400,y:"c. 400 BC",domain:"maths",also:[],t:"Babylonians use a placeholder sign like zero",text:"Babylonian scribes used a sign to mark an empty place in numbers. It was an early step towards zero, though not yet a number.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-400 Babylonians use a symbol to indicate an empty place in their numbers recorded in cuneiform writing.")]},
 {id:"west-asia-nabataean-petra-becomes-a-caravan-",region:"west-asia",place:"Petra, Jordan",ys:-400,ye:100,y:"4th century BC - 1st century AD",domain:"trade",also:["architecture", "agriculture"],t:"Nabataean Petra becomes a caravan city",text:"Petra, the rock-cut capital of the Nabataeans, was a major caravan centre for incense, silks and spices. A clever water system made life possible in the desert.",disputed:false,note:"",src:[SRCQ("Petra - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/326/","Supports World civilisations in parallel (History page)","the now lost Nabataean civilization of the fourth century BC to the first century AD"),SRCQ("Petra - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/326/","Supports World civilisations in parallel (History page)","An ingenious water management system allowed extensive settlement of an essentially arid area")]},
 {id:"americas-andes-moche-copper-and-gold-metalwo",region:"americas-andes",place:"Moche valley, north coast of Peru",ys:-400,ye:600,y:100,domain:"metallurgy",also:["arts"],t:"Moche copper and gold metalwork",text:"Moche artisans made masks of copper–gold alloy. A mask from Huaca de la Luna is dated c. 400 BC–AD 600.",disputed:true,note:"The date is from a Britannica image caption; the Moche culture is usually dated c. AD 100–800.",src:[SRCQ("Pre-Columbian civilizations – Early Intermediate period – Britannica","https://www.britannica.com/topic/pre-Columbian-civilizations/The-Early-Intermediate-period","Supports World civilisations in parallel (History page)","Mask of copper and gold alloy with eyes of shell, found in the Huaca de la Luna, Moche River valley, c. 400 bce–600 ce")]},
 {id:"europe-plato-founds-the-academy-in-athens",region:"europe",place:"Athens, Greece",ys:-387,ye:-387,y:"c. 387 BC",domain:"learning",also:[],t:"Plato founds the Academy in Athens",text:"Plato set up his Academy, a school of philosophy and mathematics that lasted for centuries.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-387 Plato founds his Academy in Athens")]},
 {id:"africa-north-iron-working-and-trade-at-meroe",region:"africa-north",place:"Meroe, Sudan",ys:-300,ye:300,y:"c. 300 BC - AD 300",domain:"metallurgy",also:["trade"],t:"Iron-working and trade at Meroe",text:"Excavations at Meroe show production of ceramics and iron along a major trade corridor. This makes Meroe an important early ironworking centre on the Nile.",disputed:true,note:"Dates are approximate (\"later centuries BCE and the first few centuries CE\").",src:[SRCQ("Archaeological Sites of the Island of Meroe - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1336/","Supports World civilisations in parallel (History page)","evidence of production and trade, including ceramics and iron-works"),SRCQ("Archaeological Sites of the Island of Meroe - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1336/","Supports World civilisations in parallel (History page)","in the later centuries BCE and the first few centuries CE")]},
 {id:"africa-north-library-of-alexandria-founded",region:"africa-north",place:"Alexandria, Egypt",ys:-300,ye:-275,y:"c. 300-275 BC",domain:"learning",also:[],t:"Library of Alexandria founded",text:"The Ptolemies built a library and research institute at Alexandria. It became the most famous centre of scholarship in the ancient Mediterranean.",disputed:true,note:"Founding dates are approximate; Britannica also says Alexander the Great initiated the collection in 334 BCE.",src:[SRCQ("Library of Alexandria | Britannica","https://www.britannica.com/topic/Library-of-Alexandria","Supports World civilisations in parallel (History page)","It formed part of the research institute at Alexandria in Egypt that is known as the Alexandrian Museum."),SRCQ("Library of Alexandria | Britannica","https://www.britannica.com/topic/Library-of-Alexandria","Supports World civilisations in parallel (History page)","c. 300 BCE - c. 275"),SRCQ("Eratosthenes of Cyrene - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Eratosthenes/","Supports World civilisations in parallel (History page)","The library at Alexandria was planned by Ptolemy I Soter and the project came to fruition under his son Ptolemy II Philadelphus.")]},
 {id:"africa-north-euclid-s-elements-written-at-al",region:"africa-north",place:"Alexandria, Egypt",ys:-300,ye:-300,y:"c. 300 BC",domain:"maths",also:["learning"],t:"Euclid's Elements written at Alexandria",text:"Euclid, who taught at Alexandria, set out geometry as a system built from definitions and proofs. The Elements was used as a textbook for over 2,000 years.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-300 Euclid gives a systematic development of geometry in his Stoicheion (The Elements)."),SRCQ("Euclid of Alexandria - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Euclid/","Supports World civilisations in parallel (History page)","little is known of Euclid's life except that he taught at Alexandria in Egypt")]},
 {id:"south-asia-nalanda-mahavihara-monastic-unive",region:"south-asia",place:"Nalanda, Bihar, India",ys:-300,ye:1300,y:500,domain:"learning",also:[],t:"Nalanda Mahavihara: monastic university",text:"Nalanda was a monastic and scholarly institution from the 3rd century BC to the 13th century AD. It passed on knowledge without a break for some 800 years.",disputed:false,note:"Many sources date Nalanda as a university to the 5th century AD; UNESCO dates the wider site's remains from the 3rd century BC.",src:[SRCQ("Archaeological Site of Nalanda Mahavihara at Nalanda, Bihar – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1502/","Supports World civilisations in parallel (History page)","dating from the 3rd century BCE to the 13th century CE."),SRCQ("Archaeological Site of Nalanda Mahavihara at Nalanda, Bihar – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1502/","Supports World civilisations in parallel (History page)","It engaged in the organized transmission of knowledge over an uninterrupted period of 800 years.")]},
 {id:"east-asia-huangdi-neijing-sets-out-chinese-m",region:"east-asia",place:"China",ys:-300,ye:-201,y:-250,domain:"medicine",also:[],t:"Huangdi neijing sets out Chinese medical theory",text:"The Huangdi neijing, the theoretical base of traditional Chinese medicine, was composed around the 3rd century BC. It stresses prevention and balance.",disputed:true,note:"Dating is approximate; the text was compiled over time.",src:[SRCQ("Huangdi neijing – Britannica","https://www.britannica.com/topic/Huangdi-neijing","Supports World civilisations in parallel (History page)","it was actually composed around the 3rd century BCE."),SRCQ("Huangdi neijing – Britannica","https://www.britannica.com/topic/Huangdi-neijing","Supports World civilisations in parallel (History page)","This revered work provides the theoretical framework for TCM, emphasizing preventive medicine.")]},
 {id:"europe-aristarchus-proposes-that-the-earth-o",region:"europe",place:"Greek world (Samos)",ys:-290,ye:-290,y:"c. 290 BC",domain:"astronomy",also:["maths"],t:"Aristarchus proposes that the Earth orbits the Sun",text:"Aristarchus of Samos used geometry to estimate the distances of the Sun and Moon. He also suggested that the Earth moves around the Sun.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-290 Aristarchus of Samos uses a geometric method to calculate the distance of the Sun and the Moon from Earth."),SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","He also proposes that the Earth orbits the Sun.")]},
 {id:"south-asia-ashoka-s-edicts-carved-on-rocks-a",region:"south-asia",place:"Maurya empire, South Asia",ys:-265,ye:-238,y:-252,domain:"governance",also:["writing"],t:"Ashoka's edicts carved on rocks and pillars",text:"The Maurya emperor Ashoka (reigned c. 265–238 BC) published his policies in rock and pillar edicts and appointed officers to promote dharma.",disputed:true,note:"Britannica gives two reign ranges: c. 265–238 BC and c. 273–232 BC.",src:[SRCQ("Ashoka – Britannica","https://www.britannica.com/biography/Ashoka","Supports World civilisations in parallel (History page)","his reign (c. 265–238 bce; also given as c. 273–232 bce)"),SRCQ("Ashoka – Britannica","https://www.britannica.com/biography/Ashoka","Supports World civilisations in parallel (History page)","These inscriptions—the rock edicts and pillar edicts")]},
 {id:"east-asia-dujiangyan-irrigation-system-begun",region:"east-asia",place:"Dujiangyan, Sichuan, China",ys:-256,ye:-256,y:-256,domain:"agriculture",also:[],t:"Dujiangyan irrigation system begun",text:"The Dujiangyan system, begun around 256 BC, diverts the Minjiang River to irrigate the Chengdu plain. It is still in use.",disputed:false,note:"The UNESCO page also once gives '2nd century BCE'; the c. 256 BC date is the one most often cited.",src:[SRCQ("Mount Qingcheng and the Dujiangyan Irrigation System – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1001/","Supports World civilisations in parallel (History page)","Construction of the Dujiangyan irrigation system began in the 3rd century B.C."),SRCQ("Mount Qingcheng and the Dujiangyan Irrigation System – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1001/","Supports World civilisations in parallel (History page)","Begun over 2,250 years ago, it now irrigates 668,700 hectares of farmland.")]},
 {id:"africa-west-djenne-settled-later-a-trans-sah",region:"africa-west",place:"Djenne, Mali",ys:-250,ye:-250,y:"from c. 250 BC",domain:"trade",also:["architecture"],t:"Djenne settled; later a trans-Saharan gold market",text:"The Djenne area has been lived in since about 250 BC. Djenne grew into a market centre and an important link in the trans-Saharan gold trade.",disputed:false,note:"UNESCO spells it Djenné; accents removed here.",src:[SRCQ("Old Towns of Djenne - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/116/","Supports World civilisations in parallel (History page)","Inhabited since 250 B.C., Djenné became a market centre and an important link in the trans-Saharan gold trade.")]},
 {id:"europe-archimedes-calculates-volumes-of-sphe",region:"europe",place:"Syracuse, Sicily",ys:-250,ye:-250,y:"c. 250 BC",domain:"maths",also:[],t:"Archimedes calculates volumes of spheres and cylinders",text:"Archimedes found formulae for the volume of a sphere and cylinder and approximated pi. He also stated the principle of floating bodies.",disputed:false,note:"Place is where Archimedes lived; not stated in the quoted entry.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-250 In On the Sphere and the Cylinder, Archimedes gives the formulae for calculating the volume of a sphere and a cylinder.")]},
 {id:"south-asia-brahmi-numerals-ancestors-of-toda",region:"south-asia",place:"India",ys:-250,ye:-250,y:-250,domain:"maths",also:["writing"],t:"Brahmi numerals: ancestors of today's digits",text:"By around the mid-3rd century BC, Brahmi numerals were in use. After many changes they became the digits 1 to 9 used worldwide.",disputed:false,note:"",src:[SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","around the middle of the third century BC, the Brahmi numerals had begun to appear."),SRCQ("An overview of Indian mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Indian_mathematics/","Supports World civilisations in parallel (History page)","These are the earliest numerals which, after a multitude of changes, eventually developed into the numerals")]},
 {id:"americas-andes-chankillo-s-thirteen-towers-t",region:"americas-andes",place:"Casma valley, Peru",ys:-250,ye:-200,y:-225,domain:"astronomy",also:[],t:"Chankillo's thirteen towers track the Sun",text:"Chankillo, used c. 250–200 BC, has a line of 13 towers that marked sunrise and sunset to fix dates through the year.",disputed:false,note:"",src:[SRCQ("Chankillo Archaeoastronomical Complex – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1624","Supports World civilisations in parallel (History page)","a prehistoric site (250-200 BC)"),SRCQ("Chankillo Archaeoastronomical Complex – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1624","Supports World civilisations in parallel (History page)","functioned as a calendrical instrument, using the sun to define dates throughout the year.")]},
 {id:"africa-north-eratosthenes-measures-the-earth",region:"africa-north",place:"Alexandria, Egypt",ys:-235,ye:-235,y:"c. 235 BC",domain:"astronomy",also:["maths", "navigation"],t:"Eratosthenes measures the Earth's circumference",text:"Eratosthenes, librarian at Alexandria, estimated the Earth's size using shadows and geometry. His result was close to the true value.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-235 Eratosthenes of Cyrene estimates the Earth's circumference with remarkable accuracy"),SRCQ("Eratosthenes of Cyrene - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Eratosthenes/","Supports World civilisations in parallel (History page)","Eratosthenes became the third librarian at Alexandria")]},
 {id:"east-asia-terracotta-army-guards-the-first-e",region:"east-asia",place:"Lintong, Shaanxi, China",ys:-221,ye:-210,y:-216,domain:"arts",also:["governance"],t:"Terracotta army guards the first emperor's tomb",text:"Qin Shi Huang, first unifier of China, died in 210 BC. His tomb is guarded by thousands of life-size terracotta warriors.",disputed:false,note:"",src:[SRCQ("Mausoleum of the First Qin Emperor – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/441/","Supports World civilisations in parallel (History page)","Qin (d. 210 B.C.), the first unifier of China, is buried, surrounded by the famous terracotta warriors,"),SRCQ("Mausoleum of the First Qin Emperor – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/441/","Supports World civilisations in parallel (History page)","and that of the short-lived Empire of a Thousand Generations (221-210 BCE).")]},
 {id:"east-asia-competitive-examinations-to-recrui",region:"east-asia",place:"China",ys:-206,ye:1905,y:850,domain:"governance",also:["learning"],t:"Competitive examinations to recruit officials",text:"China's examination system, with roots in the Han imperial university (from 206 BC), selected officials by competitive tests until it was abolished in 1905.",disputed:false,note:"Start date marks the Han roots; the full examination system developed later, especially under the Sui and Song.",src:[SRCQ("Chinese examination system – Britannica","https://www.britannica.com/topic/Chinese-examination-system","Supports World civilisations in parallel (History page)","roots date to the imperial university established in the Han dynasty (206 bc–ad 220)."),SRCQ("Chinese examination system – Britannica","https://www.britannica.com/topic/Chinese-examination-system","Supports World civilisations in parallel (History page)","Too inflexible to be capable of modernization, the system was finally abolished in 1905.")]},
 {id:"south-asia-sanchi-stupas-and-buddhist-monume",region:"south-asia",place:"Sanchi, Madhya Pradesh, India",ys:-200,ye:-1,y:-100,domain:"architecture",also:["arts"],t:"Sanchi stupas and Buddhist monuments",text:"Most of Sanchi's Buddhist monuments date from the 2nd and 1st centuries BC. It is the oldest Buddhist sanctuary still in existence.",disputed:false,note:"",src:[SRCQ("Buddhist Monuments at Sanchi – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/524/","Supports World civilisations in parallel (History page)","most of which date back to the 2nd and 1st centuries B.C."),SRCQ("Buddhist Monuments at Sanchi – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/524/","Supports World civilisations in parallel (History page)","It is the oldest Buddhist sanctuary in existence and was a major Buddhist centre in India until the 12th century A.D.")]},
 {id:"south-asia-ajanta-cave-paintings-and-sculptu",region:"south-asia",place:"Ajanta, Maharashtra, India",ys:-200,ye:600,y:200,domain:"arts",also:[],t:"Ajanta cave paintings and sculpture",text:"Buddhist caves at Ajanta were begun in the 2nd and 1st centuries BC. Many richly decorated caves were added in the 5th and 6th centuries AD.",disputed:false,note:"",src:[SRCQ("Ajanta Caves – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/242/","Supports World civilisations in parallel (History page)","The first Buddhist cave monuments at Ajanta date from the 2nd and 1st centuries B.C."),SRCQ("Ajanta Caves – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/242/","Supports World civilisations in parallel (History page)","During the Gupta period (5th and 6th centuries A.D.), many more richly decorated caves were added to the original group.")]},
 {id:"east-asia-nine-chapters-on-the-mathematical-",region:"east-asia",place:"China",ys:-200,ye:-200,y:-200,domain:"maths",also:[],t:"Nine Chapters on the Mathematical Art",text:"The Nine Chapters, a key Chinese mathematics text, probably took shape around 200 BC. It was later explained by Liu Hui.",disputed:true,note:"Liu Hui believed parts were much older (around 1000 BC); MacTutor says most historians favour about 200 BC.",src:[SRCQ("Nine chapters on the Mathematical Art – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Nine_chapters/","Supports World civilisations in parallel (History page)","In fact most historians think that the text originated around 200 BC after the burning of the books by Shih Huang Ti.")]},
 {id:"southeast-asia-pyu-city-states-south-east-as",region:"southeast-asia",place:"Halin, Beikthano and Sri Ksetra, Myanmar",ys:-200,ye:900,y:350,domain:"governance",also:["architecture"],t:"Pyu city-states: South-East Asia's first large cities",text:"From c. 2nd century BC to the 9th century AD, the Pyu built the region's earliest large walled cities, with skilled water management.",disputed:false,note:"",src:[SRCQ("Pyu Ancient Cities – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1444/","Supports World civilisations in parallel (History page)","Pyu urban transformation from ca. 2nd century BCE to the 9th century CE"),SRCQ("Pyu Ancient Cities – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1444/","Supports World civilisations in parallel (History page)","the rise of the first, largest, and longest-lived urbanized settlements of the region up until the 9th century")]},
 {id:"central-asia-silk-roads-network-takes-shape",region:"central-asia",place:"Chang'an–Tianshan corridor (China, Kazakhstan, Kyrgyzstan)",ys:-200,ye:1600,y:700,domain:"trade",also:[],t:"Silk Roads network takes shape",text:"Between the 2nd century BC and 1st century AD a 5,000 km network of trade routes formed across Central Asia. It stayed in use until the 16th century.",disputed:false,note:"",src:[SRCQ("Silk Roads: the Routes Network of Chang'an-Tianshan Corridor – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1442/","Supports World civilisations in parallel (History page)","It took shape between the 2nd century BC and 1st century AD and remained in use until the 16th century,"),SRCQ("Silk Roads: the Routes Network of Chang'an-Tianshan Corridor – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1442/","Supports World civilisations in parallel (History page)","Extending across a distance of around 5,000 km, it encompassed a complex network of trade routes")]},
 {id:"europe-hipparchus-discovers-the-precession-o",region:"europe",place:"Rhodes, Greece",ys:-127,ye:-127,y:"c. 127 BC",domain:"astronomy",also:["maths"],t:"Hipparchus discovers the precession of the equinoxes",text:"Hipparchus found the slow shift of the equinoxes and measured the year very accurately. His work used an early form of trigonometry.",disputed:false,note:"Place is where Hipparchus worked; not stated in the quoted entry.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 BC - 1","https://mathshistory.st-andrews.ac.uk/Chronology/2/","Supports World civilisations in parallel (History page)","-127 Hipparchus discovers the precession of the equinoxes")]},
 {id:"southeast-asia-ifugao-rice-terraces-climb-th",region:"southeast-asia",place:"Ifugao, Cordillera, Philippines",ys:-100,ye:100,y:"-100",domain:"agriculture",also:["architecture"],t:"Ifugao rice terraces climb the Cordillera",text:"UNESCO describes the Ifugao rice terraces as about 2,000 years old, farmed by communities who pass the skills between generations.",disputed:true,note:"UNESCO's '2,000 years' is a round figure; some recent archaeological studies argue many terraces are much younger. Year range here is a placeholder for 'about 2,000 years ago'.",src:[SRCQ("Rice Terraces of the Philippine Cordilleras – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/722/","Supports World civilisations in parallel (History page)","For 2,000 years, the high rice fields of the Ifugao have followed the contours of the mountains.")]},
 {id:"americas-meso-early-maya-hieroglyphs-at-san-",region:"americas-meso",place:"San Bartolo, Petén, Guatemala",ys:-100,ye:-100,y:-100,domain:"writing",also:[],t:"Early Maya hieroglyphs at San Bartolo",text:"Maya hieroglyphs found at San Bartolo date from as early as c. 100 BC.",disputed:true,note:"Other studies date the earliest San Bartolo writing to c. 300–200 BC; Britannica gives c. 100 BC.",src:[SRCQ("Pre-Columbian civilizations – Late Formative Period – Britannica","https://www.britannica.com/topic/pre-Columbian-civilizations/Late-Formative-Period-300-bce-100-ce","Supports World civilisations in parallel (History page)","dating from as early as c. 100 bce at the site of San Bartolo in northeastern Guatemala")]},
 {id:"americas-meso-stela-c-early-long-count-calen",region:"americas-meso",place:"Tres Zapotes, Veracruz, Mexico",ys:-31,ye:-31,y:-31,domain:"astronomy",also:["maths"],t:"Stela C: early Long Count calendar date",text:"Stela C at Tres Zapotes bears a Long Count date read as 31 BC, over a century before any dated Maya monument.",disputed:false,note:"Other sources give 32 BC or cite an earlier Long Count date at Chiapa de Corzo (36 BC).",src:[SRCQ("Pre-Columbian civilizations – Late Formative Period – Britannica","https://www.britannica.com/topic/pre-Columbian-civilizations/Late-Formative-Period-300-bce-100-ce","Supports World civilisations in parallel (History page)","as a date in the Maya calendar corresponding to 31 bce"),SRCQ("Pre-Columbian civilizations – Late Formative Period – Britannica","https://www.britannica.com/topic/pre-Columbian-civilizations/Late-Formative-Period-300-bce-100-ce","Supports World civilisations in parallel (History page)","more than a century earlier than any known dated inscription from the Maya area itself.")]},
 {id:"africa-east-aksum-raises-monolithic-obelisks",region:"africa-east",place:"Aksum, Ethiopia",ys:1,ye:1300,y:"1st-13th centuries AD",domain:"architecture",also:["governance", "arts"],t:"Aksum raises monolithic obelisks",text:"Massive ruins at Aksum, dated from the 1st to the 13th century AD, include monolithic obelisks.",disputed:false,note:"",src:[SRCQ("Aksum - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/15/","Supports World civilisations in parallel (History page)","The massive ruins, dating from between the 1st and the 13th century A.D., include monolithic obelisks")]},
 {id:"americas-meso-teotihuacan-s-pyramids-of-the-",region:"americas-meso",place:"Teotihuacan, Mexico",ys:1,ye:700,y:350,domain:"architecture",also:["governance"],t:"Teotihuacan's Pyramids of the Sun and Moon",text:"Teotihuacan was built between the 1st and 7th centuries AD, laid out on geometric principles around the Pyramids of the Sun and Moon.",disputed:false,note:"",src:[SRCQ("Pre-Hispanic City of Teotihuacan – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/414/","Supports World civilisations in parallel (History page)","Built between the 1st and 7th centuries A.D., it is characterized by the vast size of its monuments"),SRCQ("Pre-Hispanic City of Teotihuacan – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/414/","Supports World civilisations in parallel (History page)","the Pyramids of the Sun and the Moon, laid out on geometric and symbolic principles")]},
 {id:"americas-north-hopewell-earthworks-aligned-t",region:"americas-north",place:"Ohio, USA",ys:1,ye:400,y:200,domain:"astronomy",also:["maths", "architecture"],t:"Hopewell earthworks aligned to Sun and Moon",text:"Between AD 1 and 400, Hopewell communities built huge geometric earthworks aligned with the cycles of the Sun and Moon.",disputed:false,note:"",src:[SRCQ("Hopewell Ceremonial Earthworks – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1689/","Supports World civilisations in parallel (History page)","who lived in small, dispersed, egalitarian groups, between 1 and 400 CE"),SRCQ("Hopewell Ceremonial Earthworks – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1689/","Supports World civilisations in parallel (History page)","There are alignments with the cycles of the Sun and the far more complex cycles of the Moon.")]},
 {id:"east-asia-cai-lun-presents-paper-to-the-empe",region:"east-asia",place:"Luoyang, China",ys:105,ye:105,y:105,domain:"writing",also:[],t:"Cai Lun presents paper to the emperor",text:"About AD 105 the court official Cai Lun made sheets of paper from tree bark and other fibres. It wrote better than silk cloth.",disputed:false,note:"Britannica says Cai Lun is 'traditionally credited'; archaeology has found earlier paper in China.",src:[SRCQ("Cai Lun – Britannica","https://www.britannica.com/biography/Cai-Lun","Supports World civilisations in parallel (History page)","About the year 105 Cai conceived the idea of forming sheets of paper from the macerated bark of trees"),SRCQ("Cai Lun – Britannica","https://www.britannica.com/biography/Cai-Lun","Supports World civilisations in parallel (History page)","was a Chinese court official who is traditionally credited with the invention of paper.")]},
 {id:"africa-north-ptolemy-s-astronomy-dominant-fo",region:"africa-north",place:"Alexandria, Egypt",ys:127,ye:150,y:"AD 127-c. 150",domain:"astronomy",also:["maths"],t:"Ptolemy's astronomy, dominant for over a thousand years",text:"Ptolemy observed the sky from Alexandria and wrote a full mathematical model of the heavens. His system was accepted for well over 1,000 years.",disputed:false,note:"",src:[SRCQ("Claudius Ptolemy - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Ptolemy/","Supports World civilisations in parallel (History page)","He made astronomical observations from Alexandria in Egypt during the years AD 127-41."),SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1 - 500","https://mathshistory.st-andrews.ac.uk/Chronology/3/","Supports World civilisations in parallel (History page)","His version of astronomy will be the accepted one for well over one thousand years.")]},
 {id:"west-asia-galen-of-pergamum-shapes-medicine-",region:"west-asia",place:"Pergamum, Turkey",ys:129,ye:216,y:"AD 129-c. 216 (lifetime)",domain:"medicine",also:[],t:"Galen of Pergamum shapes medicine for centuries",text:"Galen, born in Pergamum, wrote medical works that dominated medical theory in Europe and the Islamic world until the 17th century.",disputed:false,note:"",src:[SRCQ("Galen | Britannica","https://www.britannica.com/biography/Galen","Supports World civilisations in parallel (History page)","Born: 129 ce, Pergamum, Mysia, Anatolia [now Bergama, Turkey]"),SRCQ("Galen | Britannica","https://www.britannica.com/biography/Galen","Supports World civilisations in parallel (History page)","exercised a dominant influence on medical theory and practice in Europe from the Middle Ages until the mid-17th century.")]},
 {id:"east-asia-zhang-heng-builds-a-seismoscope",region:"east-asia",place:"Luoyang, China",ys:132,ye:132,y:132,domain:"astronomy",also:[],t:"Zhang Heng builds a seismoscope",text:"In AD 132 Zhang Heng built an instrument to detect earthquakes. He also made an early equatorial armillary sphere.",disputed:false,note:"",src:[SRCQ("Zhang Heng – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Zhang_Heng/","Supports World civilisations in parallel (History page)","In 132 Zhang invented the first seismograph for measuring earthquakes."),SRCQ("Zhang Heng – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Zhang_Heng/","Supports World civilisations in parallel (History page)","Zhang appears to have been the first person in China to construct an equatorial armillary sphere.")]},
 {id:"south-asia-bakhshali-manuscript-oldest-recor",region:"south-asia",place:"Bakhshali, near Peshawar, Pakistan",ys:200,ye:400,y:300,domain:"maths",also:[],t:"Bakhshali manuscript: oldest recorded zero symbol",text:"Radiocarbon dating in 2017 suggested parts of the Bakhshali manuscript date from the 3rd or 4th century AD. It contains hundreds of zeros used as placeholders.",disputed:true,note:"Highly contested. Before 2017, Hayashi dated it to the 8th–12th centuries; the Oxford radiocarbon dates differ between leaves, and some scholars question the interpretation.",src:[SRCQ("Carbon dating finds Bakhshali manuscript contains oldest recorded origins of the symbol 'zero' – Bodleian Libraries, University of Oxford","https://www.glam.ox.ac.uk/node/218481","Supports World civilisations in parallel (History page)","it dates from as early as the 3rd or 4th century - approximately five centuries older than scholars previously believed."),SRCQ("The Bakhshali manuscript – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Bakhshali_manuscript/","Supports World civilisations in parallel (History page)","Channabasappa in [ 6 ] gives the range 200 - 400 AD as the most probable date.")]},
 {id:"africa-north-diophantus-writes-arithmetica-o",region:"africa-north",place:"Alexandria, Egypt",ys:250,ye:250,y:"c. AD 250",domain:"maths",also:[],t:"Diophantus writes Arithmetica on number problems",text:"Diophantus of Alexandria wrote Arithmetica, a collection of number problems. It later influenced algebra in the Islamic world and Europe.",disputed:true,note:"Listed under AD 250 in the MacTutor chronology; his dates are uncertain.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1 - 500","https://mathshistory.st-andrews.ac.uk/Chronology/3/","Supports World civilisations in parallel (History page)","Diophantus of Alexandria writes Arithmetica, a study of number theory problems in which only rational numbers are allowed as solutions.")]},
 {id:"americas-meso-tikal-s-dated-stelae-span-577-",region:"americas-meso",place:"Tikal, Petén, Guatemala",ys:292,ye:869,y:580,domain:"writing",also:["governance"],t:"Tikal's dated stelae span 577 years",text:"Tikal's earliest carved monument, Stela 29, is dated 292 AD; the last, Stela 11, is dated 869.",disputed:false,note:"",src:[SRCQ("Tikal National Park – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/64/","Supports World civilisations in parallel (History page)","The earliest stone sculpture is Stela 29 dated to the year 292"),SRCQ("Tikal National Park – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/64/","Supports World civilisations in parallel (History page)","the last monument sculptured is Stela 11 dated to the year 869")]},
 {id:"africa-east-aksum-s-coins-carry-ge-ez-and-gr",region:"africa-east",place:"Aksum, Ethiopia",ys:300,ye:400,y:"4th century AD",domain:"writing",also:["trade"],t:"Aksum's coins carry Ge'ez and Greek inscriptions",text:"Aksum minted its own coins. Gold coins were inscribed in Greek for export, and silver and copper coins in Ge'ez, the Aksumite script.",disputed:true,note:"Aksumite coinage began earlier (under King Endubis); exact dates are debated. 'insribed' is the source's spelling.",src:[SRCQ("Aksumite Coins - Smarthistory","https://smarthistory.org/aksumite-coins","Supports World civilisations in parallel (History page)","while silver and copper coins were insribed in Ge’ez (Aksumite script)"),SRCQ("Aksumite Coins - Smarthistory","https://smarthistory.org/aksumite-coins","Supports World civilisations in parallel (History page)","From the fourth century C.E., an increasing number of copper coins were issued")]},
 {id:"southeast-asia-my-son-tower-temples-of-the-c",region:"southeast-asia",place:"Mỹ Sơn, Quảng Nam, Viet Nam",ys:300,ye:1300,y:800,domain:"architecture",also:[],t:"My Son tower temples of the Cham kingdom",text:"The Cham people built tower temples at My Son from the 4th to the 13th centuries AD.",disputed:false,note:"",src:[SRCQ("My Son Sanctuary – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/949/","Supports World civilisations in parallel (History page)","My Son Sanctuary dates from the 4th to the 13th centuries CE.")]},
 {id:"africa-east-king-ezana-of-aksum-converts-to-",region:"africa-east",place:"Aksum, Ethiopia",ys:340,ye:356,y:"c. 340-356",domain:"governance",also:["trade"],t:"King Ezana of Aksum converts to Christianity",text:"King Ezana's conversion made Aksum one of the earliest Christian states. Its coins changed to carry Christian symbols.",disputed:false,note:"",src:[SRCQ("Aksumite Coins - Smarthistory","https://smarthistory.org/aksumite-coins","Supports World civilisations in parallel (History page)","But after the conversion of King Ezana around 340–356 C.E.")]},
 {id:"east-asia-ge-hong-s-fever-remedy-that-later-",region:"east-asia",place:"China",ys:340,ye:340,y:"c. AD 340",domain:"medicine",also:[],t:"Ge Hong's fever remedy that later led to artemisinin",text:"Around AD 340 the Chinese physician Ge Hong described a remedy made by taking juice from sweet wormwood (Artemisia annua, qinghao) leaves with cold water rather than boiling them. Centuries later Tu Youyou used this clue to extract artemisinin, a malaria drug that won her a share of the 2015 Nobel Prize.",disputed:false,note:"Ge Hong wrote long before the modern understanding of malaria; the scientific link between his recipe and the malaria parasite was made by Tu Youyou's team from the late 1960s.",src:[SRCQ("The Nobel Prize in Physiology or Medicine 2015 – Advanced information, NobelPrize.org","https://www.nobelprize.org/prizes/medicine/2015/advanced-information/","Supports World civilisations in parallel (History page)","So again Tu turned to ancient literature and studied recipes by Ge Hong 340 AD."),SRCQ("The Nobel Prize in Physiology or Medicine 2015 – Press release, NobelPrize.org","https://www.nobelprize.org/prizes/medicine/2015/press-release/","Supports World civilisations in parallel (History page)","Tu was the first to show that this component, later called Artemisinin, was highly effective against the Malaria parasite, both in infected animals and in humans (Figure 4)."),SRCQ("Indian Pediatrics 2011;48:914 (news item)","https://www.indianpediatrics.net/nov2011/nov-914.htm","Supports World civilisations in parallel (History page)","A handful of qinghao immersed with two liters of water, wring out the juice and drink it all.")]},
 {id:"africa-north-hypatia-heads-the-neo-platonist",region:"africa-north",place:"Alexandria, Egypt",ys:400,ye:400,y:"c. AD 400",domain:"learning",also:["maths"],t:"Hypatia heads the Neo-Platonist school at Alexandria",text:"Hypatia wrote commentaries on mathematics and led a philosophical school in Alexandria. She is the first recorded woman mathematician.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1 - 500","https://mathshistory.st-andrews.ac.uk/Chronology/3/","Supports World civilisations in parallel (History page)","400 Hypatia writes commentaries on Diophantus and Apollonius."),SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1 - 500","https://mathshistory.st-andrews.ac.uk/Chronology/3/","Supports World civilisations in parallel (History page)","She becomes head of the Neo-Platonist school at Alexandria.")]},
 {id:"africa-north-camel-caravans-begin-crossing-t",region:"africa-north",place:"Sahara",ys:400,ye:500,y:"c. 5th century AD",domain:"trade",also:["navigation"],t:"Camel caravans begin crossing the Sahara",text:"With camels, Berber-speaking peoples began crossing the Sahara. This opened the trade routes that later linked West Africa with the Mediterranean.",disputed:true,note:"Approximate date.",src:[SRCQ("The Trans-Saharan Gold Trade (7th-14th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/gold/hd_gold.htm","Supports World civilisations in parallel (History page)","Around the fifth century, thanks to the availability of the camel, Berber-speaking people began crossing the Sahara Desert.")]},
 {id:"east-asia-zu-chongzhi-calculates-pi-as-355-1",region:"east-asia",place:"Jiankang (Nanjing), China",ys:429,ye:501,y:465,domain:"maths",also:[],t:"Zu Chongzhi calculates pi as 355/113",text:"Zu Chongzhi (429–501) gave 355/113 as a value for pi, correct to six decimal places.",disputed:false,note:"",src:[SRCQ("Zu Chongzhi – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Zu_Chongzhi/","Supports World civilisations in parallel (History page)","Therefore the precise value of the ratio of the circumference of a circle to its diameter is as 355 to 113"),SRCQ("Zu Chongzhi – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Zu_Chongzhi/","Supports World civilisations in parallel (History page)","Born 429 Jiankang, (now Nanjing, Kiangsu province), China Died 501 China")]},
 {id:"americas-north-ancestral-pueblo-farming-and-",region:"americas-north",place:"Mesa Verde, Colorado, USA",ys:450,ye:1300,y:875,domain:"agriculture",also:["architecture"],t:"Ancestral Pueblo farming and cliff dwellings",text:"Ancestral Pueblo people lived at Mesa Verde c. 450–1300, farming with terraces and check dams and building some 600 cliff dwellings.",disputed:false,note:"",src:[SRCQ("Mesa Verde National Park – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/27/","Supports World civilisations in parallel (History page)","which lasted for almost nine hundred years from c. 450 to 1300."),SRCQ("Mesa Verde National Park – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/27/","Supports World civilisations in parallel (History page)","Non-habitation sites include farming terraces and check dams")]},
 {id:"south-asia-aryabhata-completes-the-aryabhati",region:"south-asia",place:"Kusumapura (Patna), India",ys:499,ye:499,y:499,domain:"astronomy",also:["maths"],t:"Aryabhata completes the Aryabhatiya",text:"Aryabhata finished the Aryabhatiya in 499 AD. He argued that the heavens appear to turn because the Earth rotates on its axis.",disputed:false,note:"",src:[SRCQ("Aryabhata I – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Aryabhata_I/","Supports World civilisations in parallel (History page)","he was twenty-three years of age when he wrote Aryabhatiya Ⓣ ( The work of Aryabhata ) which he finished in 499 ."),SRCQ("Aryabhata I – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Aryabhata_I/","Supports World civilisations in parallel (History page)","He believed that the apparent rotation of the heavens was due to the axial rotation of the Earth.")]},
 {id:"africa-west-ife-grows-from-hamlets-into-a-sa",region:"africa-west",place:"Ife, Nigeria",ys:500,ye:600,y:"from c. 6th century",domain:"governance",also:[],t:"Ife grows from hamlets into a sacred kingdom",text:"Ife began as a cluster of about thirteen hamlets and became the seat of Yoruba sacred kingship. Yoruba monarchs still trace their lineage to its founding.",disputed:false,note:"",src:[SRCQ("Ife (from ca. 6th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/ife/hd_ife.htm","Supports World civilisations in parallel (History page)","Ife's origins can be traced as far back as the sixth century, when it began as a cluster of some thirteen hamlets."),SRCQ("Ife (from ca. 6th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/ife/hd_ife.htm","Supports World civilisations in parallel (History page)","it remains the seat of Yoruba sacred kingship")]},
 {id:"americas-meso-palenque-at-its-height",region:"americas-meso",place:"Palenque, Chiapas, Mexico",ys:500,ye:700,y:600,domain:"architecture",also:["arts"],t:"Palenque at its height",text:"Palenque, a Classic Maya city, was at its height between AD 500 and 700.",disputed:false,note:"",src:[SRCQ("Pre-Hispanic City and National Park of Palenque – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/411/","Supports World civilisations in parallel (History page)","Palenque was at its height between AD 500 and 700")]},
 {id:"americas-andes-tiwanaku-raised-fields-feed-a",region:"americas-andes",place:"Tiwanaku, near Lake Titicaca, Bolivia",ys:500,ye:900,y:700,domain:"agriculture",also:["governance"],t:"Tiwanaku raised fields feed an empire",text:"Tiwanaku reached its height between AD 500 and 900, fed by almost 50,000 raised farm fields known as Sukakollos.",disputed:false,note:"",src:[SRCQ("Tiwanaku: Spiritual and Political Centre of the Tiwanaku Culture – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/567/","Supports World civilisations in parallel (History page)","reached its apogee between 500 and 900 AD"),SRCQ("Tiwanaku: Spiritual and Political Centre of the Tiwanaku Culture – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/567/","Supports World civilisations in parallel (History page)","almost 50.000 agricultural fields, known locally as Sukakollos")]},
 {id:"europe-hagia-sophia-designed-by-mathematicia",region:"europe",place:"Constantinople (Istanbul)",ys:532,ye:537,y:"AD 532-537",domain:"architecture",also:["maths"],t:"Hagia Sophia designed by mathematician Anthemius",text:"The great domed church of Hagia Sophia was designed by Anthemius of Tralles, a mathematician. Its dome was an engineering landmark.",disputed:false,note:"Completion date 537 is general knowledge, not in the quoted source.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 - 900","https://mathshistory.st-andrews.ac.uk/Chronology/4/","Supports World civilisations in parallel (History page)","532 Anthemius of Tralles, a mathematician of note, is the architect for the Hagia Sophia at Constantinople.")]},
 {id:"southeast-asia-srivijaya-controls-sea-trade-",region:"southeast-asia",place:"Palembang, Sumatra, Indonesia",ys:600,ye:1300,y:950,domain:"trade",also:["navigation", "learning"],t:"Srivijaya controls sea trade through the Strait of Malacca",text:"Srivijaya, a maritime kingdom from the 7th to 13th centuries, controlled the Strait of Malacca. It was also a Buddhist centre visited by Chinese pilgrims.",disputed:false,note:"",src:[SRCQ("Srivijaya empire – Britannica","https://www.britannica.com/place/Srivijaya-empire","Supports World civilisations in parallel (History page)","maritime and commercial kingdom that flourished between the 7th and the 13th centuries."),SRCQ("Srivijaya empire – Britannica","https://www.britannica.com/place/Srivijaya-empire","Supports World civilisations in parallel (History page)","Srivijaya’s power was based on its control of international sea trade.")]},
 {id:"americas-meso-dresden-codex-astronomical-tab",region:"americas-meso",place:"Maya lowlands (codex now in Dresden)",ys:600,ye:1100,y:850,domain:"astronomy",also:[],t:"Dresden Codex astronomical tables",text:"The Dresden Codex, an astronomy treatise, was probably copied in the 11th century AD from an original of the 7th or 8th century.",disputed:true,note:"Dating of the Dresden Codex varies between sources (often 11th–13th century for the copy).",src:[SRCQ("Mayan mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Mayan_mathematics/","Supports World civilisations in parallel (History page)","thought to have been copied in the eleventh century AD from an original document dating from the seventh or eighth centuries AD.")]},
 {id:"south-asia-brahmagupta-defines-zero-and-rule",region:"south-asia",place:"Bhillamala, Rajasthan, India",ys:628,ye:628,y:628,domain:"maths",also:[],t:"Brahmagupta defines zero and rules for negative numbers",text:"In 628 AD Brahmagupta wrote the Brahmasphutasiddhanta. He defined zero as a number subtracted from itself and gave rules for arithmetic with zero.",disputed:false,note:"",src:[SRCQ("Brahmagupta – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Brahmagupta/","Supports World civilisations in parallel (History page)","In particular he wrote Brahmasphutasiddhanta Ⓣ ( Correctly Established Doctrine of Brahma ) , in 628 ."),SRCQ("Brahmagupta – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Brahmagupta/","Supports World civilisations in parallel (History page)","he defined zero as the result of subtracting a number from itself.")]},
 {id:"east-asia-cheomseongdae-observatory-built-in",region:"east-asia",place:"Gyeongju, Republic of Korea",ys:632,ye:647,y:640,domain:"astronomy",also:[],t:"Cheomseongdae observatory built in Silla",text:"Cheomseongdae in Gyeongju was built under Queen Seondeok of Silla, who ruled 632–647. It is described as Asia's oldest astronomical observatory.",disputed:true,note:"Its exact use as an observatory is debated by scholars; source is the Korean government's official website.",src:[SRCQ("[World Heritage Festival ②] Silla heritage shines in Gyeongju – Korea.net","https://www.korea.net/NewsFocus/FoodTravel/view?articleId=279715","Supports World civilisations in parallel (History page)","Built during the reign of Silla Queen Seondeok, who ruled from 632-647"),SRCQ("[World Heritage Festival ②] Silla heritage shines in Gyeongju – Korea.net","https://www.korea.net/NewsFocus/FoodTravel/view?articleId=279715","Supports World civilisations in parallel (History page)","Cheomseongdae is the oldest astronomical observatory in Asia.")]},
 {id:"americas-meso-maya-base-20-place-value-with-",region:"americas-meso",place:"Maya lowlands",ys:665,ye:665,y:665,domain:"maths",also:[],t:"Maya base-20 place value with a zero",text:"By 665 the Maya used a place-value number system in base 20 with its own symbol for zero.",disputed:false,note:"665 is MacTutor's 'by' date; Maya zero signs in Long Count dates are found earlier.",src:[SRCQ("A history of zero – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Zero/","Supports World civilisations in parallel (History page)","We know that by 665 they used a place-value number system to base 20 with a symbol for zero."),SRCQ("Mayan mathematics – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Mayan_mathematics/","Supports World civilisations in parallel (History page)","Surprising and advanced features of the Mayan number system are the zero, denoted by a shell")]},
 {id:"africa-north-kairouan-founded-with-the-great",region:"africa-north",place:"Kairouan, Tunisia",ys:670,ye:670,y:"AD 670",domain:"architecture",also:["learning"],t:"Kairouan founded, with the Great Mosque",text:"Kairouan was founded in 670 and its Great Mosque became a model for mosques across the Maghreb. The city was capital of Ifriqiya for five centuries.",disputed:false,note:"",src:[SRCQ("Kairouan - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/499/","Supports World civilisations in parallel (History page)","Founded in 670, Kairouan flourished under the Aghlabid dynasty in the 9th century."),SRCQ("Kairouan - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/499/","Supports World civilisations in parallel (History page)","the Great Mosque, an architectural masterpiece that served as a model for several other Maghreban mosques")]},
 {id:"east-asia-horyu-ji-among-the-oldest-survivin",region:"east-asia",place:"Ikaruga, Nara, Japan",ys:670,ye:720,y:695,domain:"architecture",also:[],t:"Horyu-ji: among the oldest surviving wooden buildings",text:"After a fire in 670, Horyu-ji was rebuilt into the early 8th century. Several of its buildings are among the oldest surviving wooden buildings in the world.",disputed:false,note:"",src:[SRCQ("Buddhist Monuments in the Horyu-ji Area – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/660/","Supports World civilisations in parallel (History page)","Several date from the late 7th or early 8th century, making them some of the oldest surviving wooden buildings in the world."),SRCQ("Buddhist Monuments in the Horyu-ji Area – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/660/","Supports World civilisations in parallel (History page)","Rebuilding commenced almost immediately and continued into the early years of the 8th century.")]},
 {id:"southeast-asia-early-dated-zeros-in-south-ea",region:"southeast-asia",place:"Sumatra and Cambodia",ys:683,ye:686,y:684,domain:"maths",also:[],t:"Early dated zeros in South-East Asian inscriptions",text:"Stone inscriptions from Sumatra and Cambodia carry dates equal to AD 683–686 written with a zero placeholder. Some scholars see these as the earliest dated zeros.",disputed:true,note:"The claim to the 'first' zero is contested between South Asian and South-East Asian evidence (see Bakhshali and Gwalior). Source is an opinion article by the researchers making the case.",src:[SRCQ("The Elusive Origin of Zero – Scientific American","https://www.scientificamerican.com/article/the-elusive-origin-of-zero1/","Supports World civilisations in parallel (History page)","Translated into our Common Era chronological systems, those numerals would be: 683, 684 and 686."),SRCQ("The Elusive Origin of Zero – Scientific American","https://www.scientificamerican.com/article/the-elusive-origin-of-zero1/","Supports World civilisations in parallel (History page)","the central glyph was an empty placeholder, a zero."),SRCQ("The Elusive Origin of Zero – Scientific American","https://www.scientificamerican.com/article/the-elusive-origin-of-zero1/","Supports World civilisations in parallel (History page)","the numeration system used in the inscribed date, 605, was decimal in nature and positional in conception")]},
 {id:"east-asia-kojiki-japan-s-earliest-surviving-",region:"east-asia",place:"Nara, Japan",ys:712,ye:712,y:712,domain:"learning",also:["writing"],t:"Kojiki: Japan's earliest surviving chronicle",text:"The Kojiki, compiled in 712, records events reign by reign. It is the oldest surviving Japanese chronicle.",disputed:false,note:"'Oldest surviving' is widely stated but is not in the quoted source.",src:[SRCQ("Chronology – Japanese – Britannica","https://www.britannica.com/topic/chronology/Japanese","Supports World civilisations in parallel (History page)","The Koji-ki (compiled in ad 712) related events under the reign of each emperor without a strict chronological order.")]},
 {id:"central-asia-orkhon-inscriptions-oldest-surv",region:"central-asia",place:"Orkhon Valley, Mongolia",ys:732,ye:735,y:734,domain:"writing",also:[],t:"Orkhon inscriptions: oldest surviving Turkic writings",text:"Two large stone monuments, put up in 732 and 735 for the prince Kül and his brother, carry the oldest surviving Turkic texts.",disputed:false,note:"",src:[SRCQ("Orhon inscriptions – Britannica","https://www.britannica.com/topic/Orhon-inscriptions","Supports World civilisations in parallel (History page)","They are on two large monuments, erected in ad 732 and 735 in honour of the Turkish prince Kül (d. 731) and"),SRCQ("Orhon inscriptions – Britannica","https://www.britannica.com/topic/Orhon-inscriptions","Supports World civilisations in parallel (History page)","oldest extant Turkish writings")]},
 {id:"africa-central-kisalian-culture-works-iron-a",region:"africa-central",place:"Upemba Depression, DR Congo",ys:750,ye:900,y:"c. 750-900",domain:"metallurgy",also:["arts"],t:"Kisalian culture works iron and copper",text:"Graves of the Kisalian culture contain many iron tools and ornaments and copper jewellery. They show a skilled metalworking society with emerging elites.",disputed:false,note:"",src:[SRCQ("Upemba Depression (N. Nikis, 2021) - Royal Museum for Central Africa","https://www.africamuseum.be/publication_docs/Nikis%202021%20Upemba%20depression.pdf","Supports World civilisations in parallel (History page)","Early phases of the Kisalian (ca. mid-eighth century-late ninth century ce) have been identified in all the excavated sites."),SRCQ("Upemba Depression (N. Nikis, 2021) - Royal Museum for Central Africa","https://www.africamuseum.be/publication_docs/Nikis%202021%20Upemba%20depression.pdf","Supports World civilisations in parallel (History page)","Iron was used for tools - spearheads, axes, hoes, harpoons, fishhooks, etc. - and for ornaments.")]},
 {id:"southeast-asia-borobudur-built-under-the-sai",region:"southeast-asia",place:"Central Java, Indonesia",ys:750,ye:850,y:800,domain:"arts",also:["architecture"],t:"Borobudur built under the Sailendra dynasty",text:"Borobudur, a vast Buddhist monument covered in carved reliefs, was built in the 8th and 9th centuries AD.",disputed:false,note:"",src:[SRCQ("Borobudur Temple Compounds – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/592/","Supports World civilisations in parallel (History page)","This famous Buddhist temple, dating from the 8th and 9th centuries, is located in central Java.")]},
 {id:"africa-west-igbo-ukwu-bronzes-cast-with-grea",region:"africa-west",place:"Igbo-Ukwu, Nigeria",ys:800,ye:900,y:"c. 9th century",domain:"metallurgy",also:["arts", "trade"],t:"Igbo-Ukwu bronzes cast with great skill",text:"Bronze objects from Igbo-Ukwu show very fine casting. The materials were obtained partly through long-distance trade.",disputed:true,note:"The Met notes the ninth-century date remains controversial.",src:[SRCQ("Igbo-Ukwu (ca. 9th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/igbo/hd_igbo.htm","Supports World civilisations in parallel (History page)","flourished as early as the ninth century"),SRCQ("Igbo-Ukwu (ca. 9th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/igbo/hd_igbo.htm","Supports World civilisations in parallel (History page)","though this date remains controversial")]},
 {id:"africa-east-swahili-trading-city-of-kilwa-oc",region:"africa-east",place:"Kilwa Kisiwani, Tanzania",ys:800,ye:900,y:"from 9th century",domain:"trade",also:["navigation"],t:"Swahili trading city of Kilwa occupied",text:"Kilwa Kisiwani was a Swahili trading city occupied from the 9th to the 19th century. It shows the growth of Swahili culture and commerce on the coast.",disputed:false,note:"",src:[SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","The larger, Kilwa Kisiwani, was occupied from the 9th to the 19th century")]},
 {id:"africa-central-copper-cross-ingots-used-acro",region:"africa-central",place:"Copperbelt and Upemba Depression",ys:800,ye:1400,y:"9th-14th centuries",domain:"trade",also:["metallurgy"],t:"Copper cross ingots used across south-central Africa",text:"Cross-shaped copper ingots made in the Copperbelt spread widely. In time small ingots acted as a general purpose currency.",disputed:false,note:"The currency use is of the later, smaller ingots.",src:[SRCQ("Upemba Depression (N. Nikis, 2021) - Royal Museum for Central Africa","https://www.africamuseum.be/publication_docs/Nikis%202021%20Upemba%20depression.pdf","Supports World civilisations in parallel (History page)","They were produced between the ninth and fourteenth centuries in the Copperbelt"),SRCQ("Upemba Depression (N. Nikis, 2021) - Royal Museum for Central Africa","https://www.africamuseum.be/publication_docs/Nikis%202021%20Upemba%20depression.pdf","Supports World civilisations in parallel (History page)","these ingots acted as a general purpose currency")]},
 {id:"southeast-asia-angkor-khmer-capitals-and-res",region:"southeast-asia",place:"Angkor, Siem Reap, Cambodia",ys:800,ye:1500,y:1150,domain:"architecture",also:["agriculture"],t:"Angkor: Khmer capitals and reservoirs",text:"Angkor holds the capitals of the Khmer Empire from the 9th to the 15th century, with temples, canals and large water reservoirs.",disputed:false,note:"",src:[SRCQ("Angkor – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/668/","Supports World civilisations in parallel (History page)","from the 9th to the 15th century."),SRCQ("Angkor – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/668/","Supports World civilisations in parallel (History page)","hydraulic structures (basins, dykes, reservoirs, canals)")]},
 {id:"central-asia-bukhara-becomes-a-great-centre-",region:"central-asia",place:"Bukhara, Uzbekistan",ys:800,ye:1600,y:1200,domain:"learning",also:[],t:"Bukhara becomes a great centre of Islamic learning",text:"Bukhara became a major cultural centre in the 8th century. From the 9th to the 16th century it was the largest centre of Muslim theology.",disputed:false,note:"",src:[SRCQ("Historic Centre of Bukhara – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/602/","Supports World civilisations in parallel (History page)","became a major cultural center of the Caliphate in the 8th century."),SRCQ("Historic Centre of Bukhara – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/602/","Supports World civilisations in parallel (History page)","Between the 9th and 16th centuries, Bukhara was the largest centre for Muslim theology, particularly on Sufism")]},
 {id:"west-asia-house-of-wisdom-set-up-in-baghdad",region:"west-asia",place:"Baghdad, Iraq",ys:810,ye:810,y:"c. 810",domain:"learning",also:[],t:"House of Wisdom set up in Baghdad",text:"Scholars at the House of Wisdom translated Greek and Indian mathematics and astronomy into Arabic. Its library was the largest since Alexandria.",disputed:true,note:"Founding date is approximate.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 - 900","https://mathshistory.st-andrews.ac.uk/Chronology/4/","Supports World civilisations in parallel (History page)","810 House of Wisdom set up in Baghdad."),SRCQ("Al-Khwarizmi - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Khwarizmi/","Supports World civilisations in parallel (History page)","founded an academy called the House of Wisdom where Greek philosophical and scientific works were translated")]},
 {id:"west-asia-al-khwarizmi-writes-the-book-that-",region:"west-asia",place:"Baghdad, Iraq",ys:810,ye:830,y:"c. 810-830",domain:"maths",also:["astronomy"],t:"Al-Khwarizmi writes the book that gives us algebra",text:"Al-Khwarizmi's book on 'completion and balancing' gave us the word algebra. The word algorithm comes from his name.",disputed:false,note:"Listed under the year 810 in the MacTutor chronology.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 500 - 900","https://mathshistory.st-andrews.ac.uk/Chronology/4/","Supports World civilisations in parallel (History page)","Al-Khwarizmi writes important works on arithmetic, algebra, geography, and astronomy.")]},
 {id:"africa-central-kanem-empire-founded-near-lak",region:"africa-central",place:"Njimi, north-east of Lake Chad",ys:850,ye:850,y:"c. mid-9th century",domain:"governance",also:["trade"],t:"Kanem empire founded near Lake Chad",text:"Kanem-Bornu was probably founded in the mid-9th century, with its first capital at Njimi. It controlled the Lake Chad region until the 19th century.",disputed:true,note:"Britannica says \"probably\".",src:[SRCQ("Kanem-Bornu | Britannica","https://www.britannica.com/place/Kanem-Bornu","Supports World civilisations in parallel (History page)","Kanem-Bornu was probably founded about the mid-9th century, and its first capital was at Njimi, northeast of Lake Chad.")]},
 {id:"americas-andes-chan-chan-largest-earthen-cit",region:"americas-andes",place:"Chan Chan, Trujillo, Peru",ys:850,ye:1470,y:1160,domain:"architecture",also:["agriculture"],t:"Chan Chan: largest earthen city in the Americas",text:"Chan Chan, capital of the Chimú kingdom (9th–15th centuries), was the largest earthen-built city of pre-Columbian America, fed by a long irrigation canal.",disputed:false,note:"End date c. 1470 (Inca conquest) is implied by 'not long before falling to the Incas'.",src:[SRCQ("Chan Chan Archaeological Zone – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/366/","Supports World civilisations in parallel (History page)","attained by Chimú society between the ninth and fifteenth centuries are still clearly to be discerned."),SRCQ("Chan Chan Archaeological Zone – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/366/","Supports World civilisations in parallel (History page)","The planning of the largest earthen city of pre-Columbian America is an absolute masterpiece of town planning.")]},
 {id:"americas-north-chaco-great-houses-linked-by-",region:"americas-north",place:"Chaco Canyon, New Mexico, USA",ys:850,ye:1250,y:1050,domain:"trade",also:["architecture"],t:"Chaco: great houses linked by engineered roads",text:"Chaco Canyon was a major Ancestral Pueblo centre from 850 to 1250. Its great houses were linked by carefully engineered roads.",disputed:false,note:"",src:[SRCQ("Chaco Culture – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/353/","Supports World civilisations in parallel (History page)","a major centre of ancestral Pueblo culture between 850 and 1250."),SRCQ("Chaco Culture – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/353/","Supports World civilisations in parallel (History page)","The sites were linked by an elaborate system of carefully engineered and constructed roads.")]},
 {id:"west-asia-al-razi-tells-smallpox-and-measles",region:"west-asia",place:"Rayy and Baghdad (present-day Iran and Iraq)",ys:850,ye:925,y:"c. 900 (al-Razi lived c. 850–925)",domain:"medicine",also:[],t:"Al-Razi tells smallpox and measles apart",text:"The Persian physician al-Razi (Rhazes), who ran hospitals in Rayy and Baghdad, was the first to distinguish smallpox from measles in a written treatise. In 1970 the World Health Organization praised the originality and accuracy of his account.",disputed:false,note:"The exact year of the treatise is not known; the dates span his working life.",src:[SRCQ("Circulating Now / NLM in Focus – US National Library of Medicine","https://infocus.nlm.nih.gov/2010/06/22/nestled_among_the_national_lib/","Supports World civilisations in parallel (History page)","His wide-ranging curiosity and habit of careful observation led him to distinguish smallpox from measles for the first time in medical history, an accomplishment cited by the World Health Organization (WHO), in 1970, which praised the originality and accuracy of his treatise."),SRCQ("Haddad 1986, Journal of the Islamic Medical Association 18(1)","https://jima.imana.org/article/view/11732","Supports World civilisations in parallel (History page)","Originally from Rayy, he became the Chief Physician of the famous Baghdad Hospital.")]},
 {id:"africa-north-al-qarawiyyin-founded-in-fez",region:"africa-north",place:"Fez, Morocco",ys:859,ye:859,y:"AD 859",domain:"learning",also:[],t:"Al-Qarawiyyin founded in Fez",text:"Al-Qarawiyyin in Fez is often described as the world's oldest existing, continually operating educational institution. It was founded by Fatima al-Fihri.",disputed:true,note:"Founded as a mosque with teaching; its status as the 'oldest university' depends on how a university is defined. The founder's name comes from wider sources, not the quoted page.",src:[SRCQ("Oldest university | Guinness World Records (institutional source)","https://sites.brown.edu/archaeology/?p=216","Supports World civilisations in parallel (History page)","The Mosque cum Madrasa is known to have been founded in 859 CE by Fatima bint Muhammad al-Fihri"),SRCQ("Oldest university | Guinness World Records (institutional source)","https://sites.brown.edu/archaeology/?p=216","Supports World civilisations in parallel (History page)","The Mosque cum Madrasa is known to have been founded in 859 CE by Fatima bint Muhammad al-Fihri")]},
 {id:"east-asia-diamond-sutra-earliest-dated-print",region:"east-asia",place:"Dunhuang, Gansu, China",ys:868,ye:868,y:868,domain:"writing",also:[],t:"Diamond Sutra: earliest dated printed book",text:"A woodblock-printed copy of the Diamond Sutra, made in AD 868, is the world's earliest dated printed book. It is held by the British Library.",disputed:false,note:"",src:[SRCQ("The Diamond Sutra – International Dunhuang Programme, British Library","https://idp.bl.uk/blog/the-diamond-sutra/","Supports World civilisations in parallel (History page)","The Diamond Sutra (Or.8210/P.2) at the British Library is the world's earliest dated printed book, and was made in AD 868.")]},
 {id:"africa-north-mosque-of-ahmad-ibn-tulun-built",region:"africa-north",place:"Cairo, Egypt",ys:876,ye:879,y:"AD 876-879",domain:"architecture",also:[],t:"Mosque of Ahmad ibn Tulun built",text:"The mosque of Ahmad ibn Tulun is one of the oldest and largest mosques in Cairo. Its date is recorded precisely.",disputed:false,note:"",src:[SRCQ("Historic Cairo - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/89/","Supports World civilisations in parallel (History page)","The mosque of Ahmed ibn Tulun (876-79 AD)")]},
 {id:"south-asia-gwalior-inscription-agreed-early-",region:"south-asia",place:"Gwalior, Madhya Pradesh, India",ys:876,ye:876,y:876,domain:"maths",also:[],t:"Gwalior inscription: agreed early dated Indian zero",text:"A stone inscription at Gwalior dated 876 AD is the first Indian use of zero that all scholars accept as genuine and dated.",disputed:false,note:"",src:[SRCQ("A history of zero – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/HistTopics/Zero/","Supports World civilisations in parallel (History page)","The first record of the Indian use of zero which is dated and agreed by all to be genuine was written in 876 .")]},
 {id:"africa-east-harar-some-of-its-82-mosques-dat",region:"africa-east",place:"Harar, Ethiopia",ys:900,ye:1000,y:"10th century",domain:"architecture",also:["learning"],t:"Harar: some of its 82 mosques date from 10th century",text:"Harar is a sacred Muslim city with 82 mosques, three of them from the 10th century. It became an important centre of Islamic culture.",disputed:false,note:"",src:[SRCQ("Harar Jugol, the Fortified Historic Town - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1189/","Supports World civilisations in parallel (History page)","numbers 82 mosques, three of which date from the 10th century")]},
 {id:"africa-south-mapungubwe-first-indigenous-kin",region:"africa-south",place:"Mapungubwe, South Africa",ys:900,ye:1300,y:"c. AD 900-1300",domain:"governance",also:[],t:"Mapungubwe: first indigenous kingdom in southern Africa",text:"Mapungubwe grew into the largest kingdom in the sub-continent, with a sacred king set apart from commoners. It was abandoned in the 14th century.",disputed:true,note:"UNESCO gives 900-1300 for the wider landscape; the Met dates the city itself to 1220-1290/1300.",src:[SRCQ("Mapungubwe Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1099/","Supports World civilisations in parallel (History page)","the first indigenous kingdom in Southern Africa between 900 and 1,300 AD"),SRCQ("Mapungubwe Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1099/","Supports World civilisations in parallel (History page)","an elite class with a sacred leadership where the king was secluded from the commoners")]},
 {id:"americas-meso-el-caracol-observatory-at-chic",region:"americas-meso",place:"Chichén Itzá, Yucatán, Mexico",ys:900,ye:1450,y:1175,domain:"astronomy",also:["architecture"],t:"El Caracol observatory at Chichén Itzá",text:"Chichén Itzá, a major Maya–Toltec city of the 10th–15th centuries, includes El Caracol, a round building used to watch the sky.",disputed:false,note:"",src:[SRCQ("Pre-Hispanic City of Chichen-Itza – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/483/","Supports World civilisations in parallel (History page)","Chichen-Itza is the most important archaeological vestige of the Maya-Toltec civilization in Yucatan (10th-15th centuries)."),SRCQ("Pre-Hispanic City of Chichen-Itza – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/483/","Supports World civilisations in parallel (History page)","the Caracol, a circular stellar observatory whose spiral staircase accounts for its name,")]},
 {id:"west-asia-al-battani-s-astronomical-tables-a",region:"west-asia",place:"Raqqa, Syria",ys:920,ye:920,y:"c. 920",domain:"astronomy",also:["maths"],t:"Al-Battani's astronomical tables advance trigonometry",text:"Al-Battani wrote a major astronomy work in 57 chapters with advances in trigonometry. It was later used by European astronomers.",disputed:false,note:"Place is where al-Battani worked; not in the quoted entry.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 900 - 1100","https://mathshistory.st-andrews.ac.uk/Chronology/5/","Supports World civilisations in parallel (History page)","920 Al-Battani writes Kitab al-Zij a major work on astronomy in 57 chapters.")]},
 {id:"africa-north-fatimids-found-cairo-as-their-c",region:"africa-north",place:"Cairo, Egypt",ys:969,ye:969,y:"AD 969",domain:"governance",also:["learning"],t:"Fatimids found Cairo as their capital",text:"Cairo was founded as the headquarters of the Fatimid Caliphate. It became a leading centre of the Islamic world, home to the Al-Azhar mosque and school.",disputed:false,note:"",src:[SRCQ("Historic Cairo - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/89/","Supports World civilisations in parallel (History page)","Cairo was founded as the headquarter of the Fatimid Caliphate in 969 AD."),SRCQ("Historic Cairo - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/89/","Supports World civilisations in parallel (History page)","Al-Azhar has been a leading theological, religious academic centre for the entire Islamic world")]},
 {id:"west-asia-abu-l-wafa-invents-the-wall-quadra",region:"west-asia",place:"Baghdad, Iraq",ys:970,ye:970,y:"c. 970",domain:"astronomy",also:["maths"],t:"Abu'l-Wafa invents the wall quadrant",text:"Abu'l-Wafa built a wall quadrant to measure the positions of stars accurately. He also improved trigonometric tables.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 900 - 1100","https://mathshistory.st-andrews.ac.uk/Chronology/5/","Supports World civilisations in parallel (History page)","970 Abu'l-Wafa invents the wall quadrant for the accurate measurement of the declination of stars in the sky.")]},
 {id:"europe-first-evidence-of-decimal-numerals-in",region:"europe",place:"Spain",ys:976,ye:976,y:"AD 976",domain:"maths",also:[],t:"First evidence of decimal numerals in Europe",text:"The Codex Vigilanus, copied in Spain, shows Indian-Arabic numerals. It is the first evidence of decimal numbers in Europe.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 900 - 1100","https://mathshistory.st-andrews.ac.uk/Chronology/5/","Supports World civilisations in parallel (History page)","976 Codex Vigilanus copied in Spain. Contains the first evidence of decimal numbers in Europe.")]},
 {id:"central-asia-ibn-sina-writes-the-canon-of-me",region:"central-asia",place:"Kharmaithen, near Bukhara, Uzbekistan",ys:980,ye:1037,y:1008,domain:"medicine",also:["learning"],t:"Ibn Sina writes The Canon of Medicine",text:"Ibn Sina (980–1037), born near Bukhara, wrote The Canon of Medicine and The Book of Healing, both hugely influential.",disputed:false,note:"Range is Ibn Sina's lifetime; the sources checked do not give a completion date for the Canon.",src:[SRCQ("Avicenna – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Avicenna/","Supports World civilisations in parallel (History page)","Born 980 Kharmaithen (near Bukhara), Central Asia (now Uzbekistan) Died June 1037 Hamadan, Persia (now Ira"),SRCQ("Avicenna – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Avicenna/","Supports World civilisations in parallel (History page)","Ibn Sina's two most important works are The Book of Healing and The Canon of Medicine .")]},
 {id:"africa-north-ibn-yunus-compiles-the-hakimi-a",region:"africa-north",place:"Cairo, Egypt",ys:990,ye:1009,y:"c. 990-1009",domain:"astronomy",also:["maths"],t:"Ibn Yunus compiles the Hakimi astronomical tables",text:"Ibn Yunus, working in Fatimid Egypt, compiled a large astronomical handbook of observations and tables. It included calendar tables for several calendars.",disputed:true,note:"Exact date of the handbook not given; range runs to his death in 1009.",src:[SRCQ("Ibn Yunus (950 - 1009) - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Yunus/","Supports World civilisations in parallel (History page)","Ibn Yunus (950 - 1009)"),SRCQ("Ibn Yunus (950 - 1009) - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Yunus/","Supports World civilisations in parallel (History page)","Ibn Yunus's major work, an astronomical handbook, was al-Zij al-Hakimi al-kabir.")]},
 {id:"africa-north-ibn-al-haytham-writes-on-optics",region:"africa-north",place:"Cairo, Egypt",ys:1000,ye:1040,y:"c. 1000-1040",domain:"learning",also:["maths", "astronomy"],t:"Ibn al-Haytham writes on optics in Cairo",text:"Ibn al-Haytham (Alhazen) developed theories of light and vision and wrote on mathematics and astronomy. He spent his later life in Cairo.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 900 - 1100","https://mathshistory.st-andrews.ac.uk/Chronology/5/","Supports World civilisations in parallel (History page)","1000 Ibn al-Haytham (often called Alhazen) writes works on optics, including a theory of light and a theory of vision"),SRCQ("Ibn al-Haytham - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Haytham/","Supports World civilisations in parallel (History page)","ibn al-Haytham lived for the rest of his life near the Azhar Mosque in Cairo writing mathematics texts")]},
 {id:"africa-west-saharan-caravan-towns-founded-la",region:"africa-west",place:"Ouadane, Chinguetti, Tichitt and Oualata, Mauritania",ys:1000,ye:1200,y:"11th-12th centuries",domain:"trade",also:["learning"],t:"Saharan caravan towns founded, later centres of learning",text:"These towns were founded to serve caravans crossing the Sahara. They became trading and religious centres and focal points of Islamic culture.",disputed:false,note:"",src:[SRCQ("Ancient Ksour of Ouadane, Chinguetti, Tichitt and Oualata - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/750/","Supports World civilisations in parallel (History page)","Founded in the 11th and 12th centuries to serve the caravans crossing the Sahara"),SRCQ("Ancient Ksour of Ouadane, Chinguetti, Tichitt and Oualata - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/750/","Supports World civilisations in parallel (History page)","these trading and religious centres became focal points of Islamic culture.")]},
 {id:"africa-east-kilwa-mints-its-own-coins",region:"africa-east",place:"Kilwa Kisiwani, Tanzania",ys:1000,ye:1400,y:"11th-14th centuries",domain:"trade",also:["metallurgy"],t:"Kilwa mints its own coins",text:"Kilwa issued its own currency, a sign of its wealth and independence as a trading state.",disputed:false,note:"",src:[SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","Kilwa Kisiwani minted its own currency in the 11th to 14th centuries.")]},
 {id:"africa-south-great-zimbabwe-stone-city-built",region:"africa-south",place:"Great Zimbabwe, Zimbabwe",ys:1000,ye:1450,y:"11th-15th centuries",domain:"architecture",also:["governance"],t:"Great Zimbabwe stone city built",text:"Bantu-speaking ancestors of the Shona began Great Zimbabwe in the 11th century and enlarged it for more than 300 years. Its dry-stone walls are the largest ancient structures south of the Sahara.",disputed:false,note:"",src:[SRCQ("Great Zimbabwe (11th-15th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/zimb/hd_zimb.htm","Supports World civilisations in parallel (History page)","Begun during the eleventh century A.D. by Bantu-speaking ancestors of the Shona"),SRCQ("Great Zimbabwe (11th-15th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/zimb/hd_zimb.htm","Supports World civilisations in parallel (History page)","was constructed and expanded for more than 300 years")]},
 {id:"africa-south-great-zimbabwe-becomes-a-major-",region:"africa-south",place:"Great Zimbabwe, Zimbabwe",ys:1000,ye:1500,y:"11th-15th centuries",domain:"trade",also:[],t:"Great Zimbabwe becomes a major trading centre",text:"Great Zimbabwe was an important trading centre, known from the Middle Ages onwards. It is a unique record of Shona civilisation.",disputed:false,note:"",src:[SRCQ("Great Zimbabwe National Monument - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/364/","Supports World civilisations in parallel (History page)","are a unique testimony to the Bantu civilization of the Shona between the 11th and 15th centuries"),SRCQ("Great Zimbabwe National Monument - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/364/","Supports World civilisations in parallel (History page)","was an important trading centre and was renowned from the Middle Ages onwards")]},
 {id:"west-asia-ibn-sina-writes-the-canon-of-medic",region:"west-asia",place:"Persia (Iran)",ys:1000,ye:1037,y:"c. 1000-1037",domain:"medicine",also:["learning"],t:"Ibn Sina writes The Canon of Medicine",text:"Ibn Sina (Avicenna) wrote The Canon of Medicine, which was used as a medical textbook in the Islamic world and Europe for centuries.",disputed:true,note:"The Canon is usually dated to the early 11th century; the source gives his lifetime.",src:[SRCQ("Avicenna (980 - 1037) - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Avicenna/","Supports World civilisations in parallel (History page)","Avicenna (980 - 1037)"),SRCQ("Avicenna (980 - 1037) - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Avicenna/","Supports World civilisations in parallel (History page)","Ibn Sina's two most important works are The Book of Healing and The Canon of Medicine.")]},
 {id:"east-asia-murasaki-shikibu-writes-the-tale-o",region:"east-asia",place:"Heian-kyō (Kyoto), Japan",ys:1000,ye:1010,y:1005,domain:"arts",also:[],t:"Murasaki Shikibu writes The Tale of Genji",text:"Murasaki Shikibu, a lady at the Japanese court, probably completed The Tale of Genji about 1010. It is often called the world's first novel.",disputed:false,note:"",src:[SRCQ("The Tale of Genji – Britannica","https://www.britannica.com/topic/The-Tale-of-Genji","Supports World civilisations in parallel (History page)","Murasaki Shikibu composed The Tale of Genji while a lady in attendance at the Japanese court, likely completing it about 1010."),SRCQ("The Tale of Genji – Britannica","https://www.britannica.com/topic/The-Tale-of-Genji","Supports World civilisations in parallel (History page)","Written at the start of the 11th century, it is generally considered the world’s first novel.")]},
 {id:"southeast-asia-bagan-royal-temple-building-a",region:"southeast-asia",place:"Bagan, Myanmar",ys:1000,ye:1300,y:1150,domain:"governance",also:["architecture"],t:"Bagan: royal temple-building as statecraft",text:"At its peak in the 11th–13th centuries, Bagan was capital of a regional empire. Kings used Buddhist gift-giving and temple building to hold power.",disputed:false,note:"",src:[SRCQ("Bagan – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1588/","Supports World civilisations in parallel (History page)","of Bagan civilisation in the 11th-13th centuries when it was the capital of a regional empire."),SRCQ("Bagan – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1588/","Supports World civilisations in parallel (History page)","when redistributional Buddhism became a mechanism of political control, with the king effectively acting as the chief donor.")]},
 {id:"oceania-rapa-nui-people-carve-and-raise-the-",region:"oceania",place:"Rapa Nui (Easter Island)",ys:1000,ye:1600,y:1300,domain:"arts",also:["architecture"],t:"Rapa Nui people carve and raise the moai",text:"From the 10th to the 16th century, the people of Rapa Nui built shrines and raised huge stone figures called moai.",disputed:true,note:"UNESCO's settlement date (c. AD 300) conflicts with radiocarbon work placing settlement c. 1190–1290 (oc-07).",src:[SRCQ("Rapa Nui National Park – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/715/","Supports World civilisations in parallel (History page)","From the 10th to the 16th century this society built shrines and erected enormous stone figures known as moai"),SRCQ("Rapa Nui National Park – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/715/","Supports World civilisations in parallel (History page)","A society of Polynesian origin that settled there c. A.D. 300")]},
 {id:"south-asia-chola-king-builds-the-brihadisvar",region:"south-asia",place:"Thanjavur, Tamil Nadu, India",ys:1003,ye:1010,y:1006,domain:"architecture",also:["arts"],t:"Chola king builds the Brihadisvara temple",text:"The Chola king Rajaraja I began the great Brihadisvara temple at Thanjavur c. 1003–04 and consecrated it in 1009–10.",disputed:false,note:"",src:[SRCQ("Great Living Chola Temples – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/250/","Supports World civilisations in parallel (History page)","possibly in the 19th regal year (1003-1004 CE)"),SRCQ("Great Living Chola Temples – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/250/","Supports World civilisations in parallel (History page)","consecrated by his own hands in the 25th regal year (1009-1010 CE)")]},
 {id:"central-asia-al-biruni-s-solar-observations-",region:"central-asia",place:"Jurjaniyya, Khwarazm (Uzbekistan/Turkmenistan)",ys:1016,ye:1016,y:1016,domain:"astronomy",also:["maths"],t:"Al-Biruni's solar observations in Khwarazm",text:"In 1016 al-Biruni, born in Khwarazm, built an instrument at Jurjaniyya and made 15 observations of the Sun crossing the meridian.",disputed:false,note:"",src:[SRCQ("Al-Biruni – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Biruni/","Supports World civilisations in parallel (History page)","he made 15 such observations with the instrument between 7 June 1016 and 7 December 1016 .")]},
 {id:"oceania-voyagers-reach-the-central-society-i",region:"oceania",place:"Society Islands, French Polynesia",ys:1025,ye:1120,y:1072,domain:"navigation",also:[],t:"Voyagers reach the central Society Islands",text:"High-precision radiocarbon dating suggests people first settled the Society Islands between AD 1025 and 1120.",disputed:true,note:"Earlier studies put East Polynesian settlement centuries earlier; dates remain debated.",src:[SRCQ("East Polynesia colonized faster and more recently than previously thought – University of Hawaiʻi","https://manoa.hawaii.edu/news/article.php?aId=4097","Supports World civilisations in parallel (History page)","earliest in the central Society Islands between A.D. 1025 and 1120, four centuries later than previously assumed.")]},
 {id:"central-asia-merv-capital-of-the-great-selju",region:"central-asia",place:"Merv, Turkmenistan",ys:1040,ye:1157,y:1098,domain:"governance",also:["architecture"],t:"Merv, capital of the Great Seljuk Empire",text:"In the 11th and 12th centuries Merv was a capital of the Great Seljuk Empire; its walled city of Sultan Kala dates from this time.",disputed:false,note:"",src:[SRCQ("State Historical and Cultural Park 'Ancient Merv' – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/886/","Supports World civilisations in parallel (History page)","as a capital of the Great Seljuks Empire at the 11th-12th centuries."),SRCQ("State Historical and Cultural Park 'Ancient Merv' – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/886/","Supports World civilisations in parallel (History page)","Medieval Sultan Kala was walled in the 11th century, with its Mausoleum of Sultan Sanjar (1118-57)")]},
 {id:"east-asia-bi-sheng-invents-movable-type",region:"east-asia",place:"China",ys:1041,ye:1048,y:1044,domain:"writing",also:[],t:"Bi Sheng invents movable type",text:"About 1041–48 Bi Sheng (Pi Sheng) made movable type from baked clay and glue.",disputed:false,note:"",src:[SRCQ("Printing – History of printing – Britannica","https://www.britannica.com/topic/printing-publishing/History-of-printing","Supports World civilisations in parallel (History page)","About 1041–48 a Chinese alchemist named Pi Sheng appears to have conceived of movable type"),SRCQ("Printing – History of printing – Britannica","https://www.britannica.com/topic/printing-publishing/History-of-printing","Supports World civilisations in parallel (History page)","made of an amalgam of clay and glue hardened by baking.")]},
 {id:"africa-west-ghana-empire-controls-the-gold-t",region:"africa-west",place:"Kumbi Saleh and Audaghost",ys:1050,ye:1050,y:"by 1050",domain:"governance",also:["trade"],t:"Ghana Empire controls the gold trade",text:"The Soninke empire of Ghana grew rich on the trans-Saharan gold trade. By 1050 it controlled the trading town of Audaghost.",disputed:false,note:"",src:[SRCQ("The Trans-Saharan Gold Trade (7th-14th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/gold/hd_gold.htm","Supports World civilisations in parallel (History page)","The rise of the Soninke empire of Ghana appears to be related to the beginnings of the trans-Saharan gold trade"),SRCQ("The Trans-Saharan Gold Trade (7th-14th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/gold/hd_gold.htm","Supports World civilisations in parallel (History page)","By 1050, Ghana was strong enough to assume control of the Islamic Berber town of Audaghost.")]},
 {id:"americas-north-cahokia-largest-city-north-of",region:"americas-north",place:"Cahokia, Illinois, USA",ys:1050,ye:1150,y:1100,domain:"governance",also:["architecture", "agriculture"],t:"Cahokia: largest city north of Mexico",text:"At its peak, c. 1050–1150, the Mississippian city of Cahokia may have had 10,000–20,000 people, as many as many European cities.",disputed:false,note:"",src:[SRCQ("Cahokia Mounds State Historic Site – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/198/","Supports World civilisations in parallel (History page)","This agricultural society may have had a population of 10,000–20,000 at its peak between 1050 and 1150,"),SRCQ("Cahokia Mounds State Historic Site – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/198/","Supports World civilisations in parallel (History page)","which was equivalent to the population of many European cities at that time.")]},
 {id:"southeast-asia-temple-of-literature-founded-",region:"southeast-asia",place:"Thăng Long (Hanoi), Viet Nam",ys:1070,ye:1070,y:1070,domain:"learning",also:[],t:"Temple of Literature founded in Hanoi",text:"The Temple of Literature was founded in 1070, dedicated to Confucius, and first served as a university for the royal family and scholars.",disputed:false,note:"",src:[SRCQ("Temple of Literature – Britannica","https://www.britannica.com/topic/Temple-of-Literature","Supports World civilisations in parallel (History page)","Founded in 1070, it was originally built as a university for the royal family and scholars.")]},
 {id:"west-asia-omar-khayyam-classifies-cubic-equa",region:"west-asia",place:"Isfahan, Iran",ys:1072,ye:1072,y:"c. 1072",domain:"maths",also:["astronomy"],t:"Omar Khayyam classifies cubic equations",text:"Omar Khayyam classified cubic equations and solved them with geometry. He also measured the length of the year very accurately.",disputed:false,note:"Place is approximate; not in the quoted entry.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 900 - 1100","https://mathshistory.st-andrews.ac.uk/Chronology/5/","Supports World civilisations in parallel (History page)","1072 Al-Khayyami (usually known as Omar Khayyam) writes Treatise on Demonstration of Problems of Algebra")]},
 {id:"east-asia-magnetic-compass-described-then-us",region:"east-asia",place:"Dream Brook, Zhenjiang, China",ys:1086,ye:1200,y:1143,domain:"navigation",also:[],t:"Magnetic compass described, then used at sea",text:"Shen Kuo's Brush Talks from Dream Brook, written in his last years (1086–95), refers to a magnetic compass. By the 12th century Chinese sailors used compasses.",disputed:true,note:"Earlier Chinese lodestone 'south-pointers' existed; Britannica dates maritime use to the 12th century, in China and Europe apparently independently.",src:[SRCQ("Shen Kua – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Shen_Kua/","Supports World civilisations in parallel (History page)","There is also a reference to a magnetic compass and its use in cartography."),SRCQ("Shen Kua – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Shen_Kua/","Supports World civilisations in parallel (History page)","He spent the last seven years of his life in isolation at Dream Brook."),SRCQ("Compass – Britannica","https://www.britannica.com/technology/compass-navigational-instrument","Supports World civilisations in parallel (History page)","Sometime in the 12th century, mariners in China and Europe made the discovery, apparently independently,")]},
 {id:"europe-university-of-bologna-founded",region:"europe",place:"Bologna, Italy",ys:1088,ye:1088,y:"1088 (conventional)",domain:"learning",also:[],t:"University of Bologna founded",text:"Bologna is considered the oldest university in the Western world. 1088 is the year conventionally given for its founding.",disputed:true,note:"1088 is a conventional date.",src:[SRCQ("Our history - University of Bologna","https://www.unibo.it/en/university/who-we-are/our-history","Supports World civilisations in parallel (History page)","from as far back as 1088, conventionally referred to as the year in which the Studium of Bologna was founded")]},
 {id:"africa-east-rock-hewn-churches-of-lalibela-c",region:"africa-east",place:"Lalibela, Ethiopia",ys:1100,ye:1300,y:"12th-13th centuries",domain:"architecture",also:["arts"],t:"Rock-hewn churches of Lalibela carved",text:"King Lalibela set out to build a 'New Jerusalem' of 11 churches cut from solid rock. They have drawn pilgrims since the 12th century.",disputed:true,note:"UNESCO gives both 12th and 13th centuries.",src:[SRCQ("Rock-Hewn Churches, Lalibela - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/18/","Supports World civilisations in parallel (History page)","Their building is attributed to King Lalibela who set out to construct in the 12th century a 'New Jerusalem'"),SRCQ("Rock-Hewn Churches, Lalibela - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/18/","Supports World civilisations in parallel (History page)","The 11 medieval monolithic cave churches of this 13th-century 'New Jerusalem'")]},
 {id:"south-asia-bhaskara-ii-extends-brahmagupta-s",region:"south-asia",place:"Vijayapura and Ujjain, India",ys:1114,ye:1185,y:1150,domain:"maths",also:["astronomy"],t:"Bhaskara II extends Brahmagupta's number work",text:"Bhaskara II (1114–1185) wrote the Lilavati on arithmetic and the Bijaganita on algebra, building on Brahmagupta.",disputed:false,note:"",src:[SRCQ("Bhaskara II – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Bhaskara_II/","Supports World civilisations in parallel (History page)","Bhaskara II or Bhaskaracharya was an Indian mathematician and astronomer who extended Brahmagupta's work on number systems."),SRCQ("Bhaskara II – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Bhaskara_II/","Supports World civilisations in parallel (History page)","Born 1114 Vijayapura, India Died 1185 Ujjain, India")]},
 {id:"europe-lubeck-leads-the-hanseatic-trading-ne",region:"europe",place:"Lubeck, Germany",ys:1143,ye:1600,y:"12th-16th centuries",domain:"trade",also:["navigation"],t:"Lubeck leads the Hanseatic trading network",text:"Lubeck, founded in the 12th century, became capital of the Hanseatic League and the main trading centre of northern Europe until the 16th century.",disputed:false,note:"UNESCO spells it Lübeck.",src:[SRCQ("Hanseatic City of Lubeck - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/272/","Supports World civilisations in parallel (History page)","was founded in the 12th century and prospered until the 16th century as the major trading centre for northern Europe"),SRCQ("Hanseatic City of Lubeck - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/272/","Supports World civilisations in parallel (History page)","the former capital and Queen City of the Hanseatic League")]},
 {id:"europe-arabic-science-translated-into-latin",region:"europe",place:"Spain (Latin translators)",ys:1144,ye:1144,y:"c. 1144",domain:"learning",also:["maths", "astronomy"],t:"Arabic science translated into Latin",text:"Gherard of Cremona began translating Arabic works, and Arabic versions of Greek works, into Latin. This brought Islamic and Greek science into European learning.",disputed:false,note:"Gherard worked in Toledo, Spain; the quoted entry does not name the city.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1100 - 1300","https://mathshistory.st-andrews.ac.uk/Chronology/6/","Supports World civilisations in parallel (History page)","1144 Gherard of Cremona begins translating Arabic works (and Arabic translations of Greek works) into Latin.")]},
 {id:"oceania-rapid-voyaging-to-hawai-i-new-zealan",region:"oceania",place:"Hawaiʻi, Aotearoa New Zealand, Rapa Nui",ys:1190,ye:1290,y:1240,domain:"navigation",also:[],t:"Rapid voyaging to Hawaiʻi, New Zealand and Rapa Nui",text:"In one rapid burst between AD 1190 and 1290, voyagers reached the far corners of Polynesia, including Hawaiʻi, New Zealand and Rapa Nui.",disputed:true,note:"Contested: UNESCO dates Rapa Nui settlement c. AD 300 (see oc-09).",src:[SRCQ("East Polynesia colonized faster and more recently than previously thought – University of Hawaiʻi","https://manoa.hawaii.edu/news/article.php?aId=4097","Supports World civilisations in parallel (History page)","including New Zealand, Hawai`i and Easter Island (Rapa Nui) between A.D. 1190 and 1290.")]},
 {id:"south-asia-qutb-minar-rises-in-delhi",region:"south-asia",place:"Delhi, India",ys:1199,ye:1503,y:1351,domain:"architecture",also:[],t:"Qutb Minar rises in Delhi",text:"The Qutb Minar was built in the early 13th century south of Delhi. Work on the minaret continued between 1199 and 1503.",disputed:false,note:"",src:[SRCQ("Qutb Minar and its Monuments, Delhi – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/233/","Supports World civilisations in parallel (History page)","Built in the early 13th century a few kilometres south of Delhi"),SRCQ("Qutb Minar and its Monuments, Delhi – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/233/","Supports World civilisations in parallel (History page)","they constructed a minar (minaret) at the south-eastern corner of the Quwwatu'l-Islam between 1199 and 1503")]},
 {id:"africa-west-ife-becomes-a-flourishing-artist",region:"africa-west",place:"Ife, Nigeria",ys:1200,ye:1500,y:"c. 1200-1500",domain:"arts",also:["metallurgy"],t:"Ife becomes a flourishing artistic centre",text:"Between about 1200 and 1500 Ife produced celebrated naturalistic sculpture. Its works are among the masterpieces of African art.",disputed:false,note:"",src:[SRCQ("Ife (from ca. 6th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/ife/hd_ife.htm","Supports World civilisations in parallel (History page)","Between ca. 1200 and 1500, Ife developed into a flourishing artistic center.")]},
 {id:"africa-west-manden-charter-proclaimed-for-th",region:"africa-west",place:"Kurukan Fuga, Mali",ys:1200,ye:1250,y:"early 13th century",domain:"governance",also:[],t:"Manden Charter proclaimed for the Mali Empire",text:"After a major victory, the founder of the Mali (Mandingo) Empire proclaimed the Manden Charter. It is one of the oldest constitutions in the world, passed down mainly orally.",disputed:true,note:"Oral tradition; the year 1236 is often given but is not stated in the source used.",src:[SRCQ("Manden Charter, proclaimed in Kurukan Fuga - UNESCO Intangible Cultural Heritage","https://ich.unesco.org/en/RL/manden-charter-proclaimed-in-kurukan-fuga-00290","Supports World civilisations in parallel (History page)","In the early thirteenth century, following a major military victory, the founder of the Mandingo Empire"),SRCQ("Manden Charter, proclaimed in Kurukan Fuga - UNESCO Intangible Cultural Heritage","https://ich.unesco.org/en/RL/manden-charter-proclaimed-in-kurukan-fuga-00290","Supports World civilisations in parallel (History page)","The Charter, one of the oldest constitutions in the world albeit mainly in oral form")]},
 {id:"africa-east-kilwa-s-great-mosque-gains-east-",region:"africa-east",place:"Kilwa Kisiwani, Tanzania",ys:1200,ye:1300,y:"13th century",domain:"architecture",also:[],t:"Kilwa's Great Mosque gains East Africa's largest dome",text:"Kilwa's Great Mosque is the oldest standing mosque on the East African coast. Its 13th-century dome was the largest in East Africa until the 19th century.",disputed:false,note:"",src:[SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","The Great Mosque of Kilwa Kisiwani is the oldest standing mosque on the East African coast"),SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","Its true great dome dating from the 13th was the largest dome in East Africa until the 19th century.")]},
 {id:"africa-east-kilwa-merchants-control-indian-o",region:"africa-east",place:"Kilwa Kisiwani, Tanzania",ys:1200,ye:1600,y:"13th-16th centuries",domain:"navigation",also:["trade"],t:"Kilwa merchants control Indian Ocean gold trade",text:"Kilwa merchants traded gold, silver, pearls and other goods, so much Indian Ocean trade passed through their hands. Gold and ivory from inland were exchanged for imports.",disputed:false,note:"",src:[SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","From the 13th to the 16th century, the merchants of Kilwa dealt in gold, silver,"),SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","much of the trade in the Indian Ocean thus passed through their hands.")]},
 {id:"africa-east-harar-walls-built-around-the-sac",region:"africa-east",place:"Harar, Ethiopia",ys:1200,ye:1600,y:"13th-16th centuries",domain:"architecture",also:["governance"],t:"Harar walls built around the sacred city",text:"The walls of Harar were built between the 13th and 16th centuries. The fortified town became a major trading and religious centre.",disputed:false,note:"",src:[SRCQ("Harar Jugol, the Fortified Historic Town - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1189/","Supports World civilisations in parallel (History page)","The walls surrounding this sacred Muslim city were built between the 13th and 16th centuries.")]},
 {id:"central-asia-pax-mongolica-opens-safer-trade",region:"central-asia",place:"Mongol Eurasia",ys:1200,ye:1400,y:1300,domain:"trade",also:[],t:"Pax Mongolica opens safer trade across Eurasia",text:"In the 13th and 14th centuries, Mongol rule made travel and trade safer across much of Eurasia, linking East Asia, Central Asia and Europe.",disputed:false,note:"",src:[SRCQ("Pax Mongolica – Britannica","https://www.britannica.com/event/Pax-Mongolica","Supports World civilisations in parallel (History page)","It enabled safer travel and trade across much of Eurasia."),SRCQ("Pax Mongolica – Britannica","https://www.britannica.com/event/Pax-Mongolica","Supports World civilisations in parallel (History page)","during the 13th and 14th centuries")]},
 {id:"oceania-nan-madol-basalt-city-of-the-saudele",region:"oceania",place:"Pohnpei, Federated States of Micronesia",ys:1200,ye:1500,y:1350,domain:"architecture",also:["governance"],t:"Nan Madol: basalt city of the Saudeleur dynasty",text:"Between 1200 and 1500 the Saudeleur dynasty built stone palaces, temples and tombs on artificial islets at Nan Madol.",disputed:false,note:"",src:[SRCQ("Nan Madol: Ceremonial Centre of Eastern Micronesia – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1503/","Supports World civilisations in parallel (History page)","These islets harbour the remains of stone palaces, temples, tombs and residential domains built between 1200 and 1500 CE.")]},
 {id:"europe-fibonacci-s-liber-abaci-brings-arab-a",region:"europe",place:"Pisa, Italy",ys:1202,ye:1202,y:"1202",domain:"maths",also:["trade"],t:"Fibonacci's Liber abaci brings Arab arithmetic to Europe",text:"Fibonacci set out the arithmetic and algebra he had learnt in Arab lands, including Indian-Arabic numerals. It helped European merchants adopt them.",disputed:false,note:"He learnt much of this in North Africa (Bejaia); place Pisa is his home city, not stated in the quoted entry.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1100 - 1300","https://mathshistory.st-andrews.ac.uk/Chronology/6/","Supports World civilisations in parallel (History page)","1202 Fibonacci writes Liber abaci (The Book of the Abacus), which sets out the arithmetic and algebra he had learnt in Arab countries.")]},
 {id:"europe-king-john-accepts-magna-carta",region:"europe",place:"Runnymede, England",ys:1215,ye:1215,y:"1215",domain:"governance",also:[],t:"King John accepts Magna Carta",text:"King John agreed to Magna Carta to end a civil war with his barons. It became a symbol of limits on royal power.",disputed:false,note:"",src:[SRCQ("Magna Carta 1214-1225 - The National Archives","https://www.nationalarchives.gov.uk/education/resources/magna-carta/","Supports World civilisations in parallel (History page)","The king agreed to accept the terms of Magna Carta, which is dated 15 June 1215.")]},
 {id:"africa-south-mapungubwe-trades-gold-and-ivor",region:"africa-south",place:"Mapungubwe, South Africa",ys:1220,ye:1300,y:"1220-1290/1300",domain:"trade",also:[],t:"Mapungubwe trades gold and ivory to the coast",text:"Mapungubwe flourished as a city and trading centre. It sent gold and ivory to East African ports for trade with India and China, and received glass beads and cloth.",disputed:false,note:"",src:[SRCQ("Mapungubwe (ca. 1050-1270) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/en/essays/mapungubwe-ca-1050-1270","Supports World civilisations in parallel (History page)","Mapungubwe flourished as a city and trading center from 1220 to 1290/1300."),SRCQ("Mapungubwe Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1099/","Supports World civilisations in parallel (History page)","also enabled it to control trade, through the East African ports to India and China")]},
 {id:"africa-south-gold-foil-rhinoceros-made-at-ma",region:"africa-south",place:"Mapungubwe, South Africa",ys:1220,ye:1300,y:"c. 1220-1300",domain:"metallurgy",also:["arts"],t:"Gold foil rhinoceros made at Mapungubwe",text:"Gold objects found at Mapungubwe, including a famous gold foil rhinoceros, are early evidence of goldsmithing in southern Africa.",disputed:true,note:"Date given as the period when the city flourished; the object itself is not precisely dated in the quoted text.",src:[SRCQ("Mapungubwe (ca. 1050-1270) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/en/essays/mapungubwe-ca-1050-1270","Supports World civilisations in parallel (History page)","Most spectacular among these finds is a gold foil rhinoceros molded over what was likely a soft core of sculpted wood."),SRCQ("Mapungubwe (ca. 1050-1270) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/en/essays/mapungubwe-ca-1050-1270","Supports World civilisations in parallel (History page)","These finds provide evidence not only of the early smithing of gold in southern Africa")]},
 {id:"central-asia-karakorum-founded-as-mongol-imp",region:"central-asia",place:"Kharkhorum, Orkhon Valley, Mongolia",ys:1220,ye:1220,y:1220,domain:"governance",also:[],t:"Karakorum founded as Mongol imperial capital",text:"Chinggis Khan established Karakorum in 1220 as the capital of the vast Mongol Empire.",disputed:false,note:"",src:[SRCQ("Orkhon Valley Cultural Landscape – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1081/","Supports World civilisations in parallel (History page)","the grand capital of the vast Mongol Empire established by Chinggis Khaan in 1220.")]},
 {id:"west-asia-mosque-and-hospital-founded-at-div",region:"west-asia",place:"Divrigi, Turkey",ys:1228,ye:1229,y:"1228-1229",domain:"medicine",also:["architecture"],t:"Mosque and hospital founded at Divrigi",text:"Emir Ahmet Shah founded a mosque with an adjoining hospital at Divrigi in Anatolia. It is a masterpiece of Islamic architecture.",disputed:false,note:"",src:[SRCQ("Great Mosque and Hospital of Divrigi - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/358/","Supports World civilisations in parallel (History page)","In 1228–29 Emir Ahmet Shah founded a mosque, with its adjoining hospital, at Divrigi.")]},
 {id:"east-asia-tripitaka-koreana-carved-on-80-000",region:"east-asia",place:"Haeinsa, Gyeongsang, Republic of Korea",ys:1237,ye:1248,y:1242,domain:"writing",also:["learning"],t:"Tripitaka Koreana carved on 80,000 woodblocks",text:"Between 1237 and 1248, Korean craftsmen carved the Buddhist scriptures onto about 80,000 printing woodblocks, kept at Haeinsa temple.",disputed:false,note:"",src:[SRCQ("Haeinsa Temple Janggyeong Panjeon – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/737/","Supports World civilisations in parallel (History page)","engraved on 80,000 woodblocks between 1237 and 1248")]},
 {id:"east-asia-qin-jiushao-s-mathematical-treatis",region:"east-asia",place:"China",ys:1247,ye:1247,y:1247,domain:"maths",also:[],t:"Qin Jiushao's Mathematical Treatise in Nine Sections",text:"Qin Jiushao's Mathematical Treatise in Nine Sections appeared in 1247.",disputed:false,note:"",src:[SRCQ("Qin Jiushao – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Qin_Jiushao/","Supports World civilisations in parallel (History page)","Qin wrote his famous mathematical treatise Shushu Jiuzhang ( Mathematical Treatise in Nine Sections ) which appeared in 1247 .")]},
 {id:"oceania-polynesian-voyagers-settle-aotearoa-",region:"oceania",place:"Aotearoa New Zealand",ys:1250,ye:1300,y:1275,domain:"navigation",also:[],t:"Polynesian voyagers settle Aotearoa New Zealand",text:"Current understanding is that the first people arrived from East Polynesia between 1250 and 1300, on deliberate voyages using winds, currents and stars.",disputed:true,note:"Te Ara says 'The date of first settlement is a matter of debate'.",src:[SRCQ("History – Te Ara: The Encyclopedia of New Zealand","https://teara.govt.nz/en/history/page-1","Supports World civilisations in parallel (History page)","current understanding is that the first arrivals came from East Polynesia between 1250 and 1300 CE."),SRCQ("History – Te Ara: The Encyclopedia of New Zealand","https://teara.govt.nz/en/history/page-1","Supports World civilisations in parallel (History page)","navigating by making use of prevailing winds and ocean currents, and observing the stars.")]},
 {id:"africa-north-ibn-al-banna-writes-a-key-arith",region:"africa-north",place:"Marrakesh, Morocco",ys:1256,ye:1321,y:"1256-1321 (lifetime)",domain:"maths",also:[],t:"Ibn al-Banna writes a key arithmetic textbook",text:"Ibn al-Banna of Marrakesh wrote a summary of arithmetical operations that was widely studied in North Africa. He was one of the leading mathematicians of the Maghreb.",disputed:false,note:"",src:[SRCQ("Ibn al-Banna (1256 - 1321) - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Banna/","Supports World civilisations in parallel (History page)","Ibn al-Banna (1256 - 1321)"),SRCQ("Ibn al-Banna (1256 - 1321) - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Banna/","Supports World civilisations in parallel (History page)","Perhaps al-Banna's most famous work is Talkhis amal al-hisab (Summary of arithmetical operations)")]},
 {id:"west-asia-al-tusi-builds-the-maragheh-observ",region:"west-asia",place:"Maragheh, Iran",ys:1259,ye:1262,y:"1259-1262",domain:"astronomy",also:["learning"],t:"Al-Tusi builds the Maragheh observatory",text:"Nasir al-Din al-Tusi led the building of a great observatory at Maragheh, with help from Chinese astronomers. It was also a centre of learning.",disputed:false,note:"",src:[SRCQ("Nasir al-Din al-Tusi - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Tusi_Nasir/","Supports World civilisations in parallel (History page)","Construction of the Observatory began in 1259 west of Maragheh"),SRCQ("Nasir al-Din al-Tusi - Biography - MacTutor History of Mathematics","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Tusi_Nasir/","Supports World civilisations in parallel (History page)","The observatory at Maragheh became operational in 1262.")]},
 {id:"east-asia-yang-hui-records-the-pascal-triang",region:"east-asia",place:"Hangzhou, China",ys:1261,ye:1261,y:1261,domain:"maths",also:[],t:"Yang Hui records the 'Pascal' triangle",text:"In 1261 Yang Hui wrote a commentary on the Nine Chapters. It shows the number triangle later named after Pascal, which he credited to Jia Xian.",disputed:false,note:"",src:[SRCQ("Yang Hui – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Yang_Hui/","Supports World civilisations in parallel (History page)","In 1261 Yang wrote the Xiangjie jiuzhang suanfa"),SRCQ("Yang Hui – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Yang_Hui/","Supports World civilisations in parallel (History page)","He gives what today is called Pascal's triangle , up to the sixth row, saying that he learnt it from Jia Xian 's treatise.")]},
 {id:"east-asia-guo-shoujing-s-accurate-calendar-f",region:"east-asia",place:"Dadu (Beijing), China",ys:1280,ye:1281,y:1280,domain:"astronomy",also:[],t:"Guo Shoujing's accurate calendar for Kublai Khan",text:"Guo Shoujing built new instruments and by 1280 measured the year to within 26 seconds. The new calendar came into use the next year.",disputed:false,note:"",src:[SRCQ("Guo Shoujing – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Guo_Shoujing/","Supports World civilisations in parallel (History page)","The work was completed by 1280 , Guo having calculated the length of the year correct to within 26 seconds")]},
 {id:"africa-south-climate-change-ends-farming-at-",region:"africa-south",place:"Mapungubwe, South Africa",ys:1290,ye:1300,y:"end of 13th century",domain:"agriculture",also:[],t:"Climate change ends farming at Mapungubwe",text:"Mapungubwe supported a large population through farming, but climate change made the land unable to sustain it. The site was abandoned.",disputed:false,note:"",src:[SRCQ("Mapungubwe Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1099/","Supports World civilisations in parallel (History page)","Until its demise at the end of the 13th century AD"),SRCQ("Mapungubwe Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1099/","Supports World civilisations in parallel (History page)","the land could no longer sustain a high population using traditional farming methods")]},
 {id:"africa-west-cowrie-shells-introduced-as-loca",region:"africa-west",place:"Western Sudan (Sahel)",ys:1300,ye:1400,y:"14th century",domain:"trade",also:[],t:"Cowrie shells introduced as local currency",text:"Cowrie shells from the east coast came into use as currency in the western Sudan. Gold and salt stayed the main goods in long-distance trade.",disputed:false,note:"",src:[SRCQ("The Trans-Saharan Gold Trade (7th-14th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/gold/hd_gold.htm","Supports World civilisations in parallel (History page)","In the fourteenth century, cowrie shells were introduced from the eastern coast as local currency")]},
 {id:"africa-central-mbanza-kongo-becomes-capital-",region:"africa-central",place:"Mbanza Kongo, Angola",ys:1300,ye:1400,y:"14th century",domain:"architecture",also:["governance"],t:"Mbanza Kongo becomes capital of the Kingdom of Kongo",text:"Mbanza Kongo was the political and spiritual capital of the Kingdom of Kongo, one of the largest states in the region. The town grew around the royal residence and court.",disputed:false,note:"",src:[SRCQ("Mbanza Kongo, Vestiges of the Capital of the former Kingdom of Kongo - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1511/","Supports World civilisations in parallel (History page)","one of the largest constituted states in Southern Africa from the 14th to 19th centuries"),SRCQ("Mbanza Kongo, Vestiges of the Capital of the former Kingdom of Kongo - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1511/","Supports World civilisations in parallel (History page)","The historical area grew around the royal residence, the customary court and the holy tree")]},
 {id:"oceania-taputapu-tea-hub-of-polynesian-voyag",region:"oceania",place:"Raʻiātea, French Polynesia",ys:1300,ye:1800,y:1550,domain:"navigation",also:["governance"],t:"Taputapuātea: hub of Polynesian voyaging",text:"Marae at Taputapuātea were built from the 14th to the 18th century. Voyagers in outrigger canoes were formally welcomed there.",disputed:false,note:"",src:[SRCQ("Taputapuātea – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1529/","Supports World civilisations in parallel (History page)","from the 14th to the 18th century."),SRCQ("Taputapuātea – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1529/","Supports World civilisations in parallel (History page)","The building of outrigger canoes and ocean navigation were key skills in maintaining this network.")]},
 {id:"africa-east-husuni-kubwa-palace-built-at-kil",region:"africa-east",place:"Kilwa Kisiwani, Tanzania",ys:1310,ye:1333,y:"c. 1310-1333",domain:"governance",also:["architecture"],t:"Husuni Kubwa palace built at Kilwa",text:"The Husuni Kubwa palace, with its large octagonal bathing pool, was built for Kilwa's rulers. The traveller Ibn Battuta visited Kilwa in 1331-1332.",disputed:false,note:"",src:[SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","the palace Husuni Kubwa built between c1310 and 1333 with its large octagonal bathing pool"),SRCQ("Ruins of Kilwa Kisiwani and Ruins of Songo Mnara - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/144/","Supports World civilisations in parallel (History page)","In 1331-1332, the great traveler, Ibn Battouta made a stop here")]},
 {id:"africa-west-mansa-musa-s-pilgrimage-shows-ma",region:"africa-west",place:"Mali to Cairo",ys:1324,ye:1325,y:"1324-1325",domain:"trade",also:["governance"],t:"Mansa Musa's pilgrimage shows Mali's gold wealth",text:"Mansa Musa of Mali travelled to Mecca with so much gold that its price fell in Cairo. A Spanish map of 1375 shows the king of Mali holding a gold nugget.",disputed:false,note:"",src:[SRCQ("The Empires of the Western Sudan: Mali Empire - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/mali/hd_mali.htm","Supports World civilisations in parallel (History page)","Musa’s hajj (pilgrimage to Mecca) of 1324–25"),SRCQ("The Trans-Saharan Gold Trade (7th-14th Century) - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/gold/hd_gold.htm","Supports World civilisations in parallel (History page)","Mansa Musa’s arrival in Cairo carrying a ton of the metal (1324–25) caused the market in gold to crash")]},
 {id:"americas-meso-tenochtitlan-founded-on-lake-t",region:"americas-meso",place:"Lake Texcoco (Mexico City), Mexico",ys:1325,ye:1521,y:1423,domain:"governance",also:["architecture", "agriculture"],t:"Tenochtitlan founded on Lake Texcoco",text:"The Aztec capital Tenochtitlan was founded c. 1325 on marshes in Lake Texcoco and linked to the shore by causeways. About 400,000 people lived there by 1519.",disputed:true,note:"Population estimates for 1519 vary widely between scholars.",src:[SRCQ("Tenochtitlán – Britannica","https://www.britannica.com/place/Tenochtitlan","Supports World civilisations in parallel (History page)","Located at the site of modern Mexico City, it was founded c. 1325 in the marshes of Lake Texcoco."),SRCQ("Tenochtitlán – Britannica","https://www.britannica.com/place/Tenochtitlan","Supports World civilisations in parallel (History page)","The population in 1519 was estimated to be about 400,000 people")]},
 {id:"africa-north-ibn-khaldun-s-muqaddimah-an-ear",region:"africa-north",place:"Tunis and Cairo",ys:1332,ye:1406,y:"1332-1406 (lifetime)",domain:"learning",also:["governance"],t:"Ibn Khaldun's Muqaddimah: an early philosophy of history",text:"Ibn Khaldun, born in Tunis, wrote the Muqaddimah, one of the earliest non-religious philosophies of history. It analyses how states rise and fall.",disputed:false,note:"Dates shown are his lifetime; the source extract does not date the Muqaddimah itself.",src:[SRCQ("Ibn Khaldun | Britannica","https://www.britannica.com/biography/Ibn-Khaldun","Supports World civilisations in parallel (History page)","May 27, 1332, Tunis [Tunisia]"),SRCQ("Ibn Khaldun | Britannica","https://www.britannica.com/biography/Ibn-Khaldun","Supports World civilisations in parallel (History page)","May 27, 1332, Tunis [Tunisia]")]},
 {id:"west-asia-the-black-death-sweeps-through-the",region:"west-asia",place:"Constantinople, Alexandria, Cairo, Damascus and Baghdad (eastern Mediterranean and Middle East)",ys:1347,ye:1349,y:"1347–1349",domain:"medicine",also:[],t:"The Black Death sweeps through the Middle East",text:"The Black Death reached Constantinople and Alexandria in 1347 and Cairo and Damascus in 1348, then spread north into Anatolia and south-east to Mosul and Baghdad by 1349. The traveller Ibn Battuta, passing through Damascus in July 1348, saw the governor order three days of fasting during the pestilence; he wrote that deaths there did not reach two thousand a day, while in Cairo they reached twenty-four thousand.",disputed:false,note:"The route and dates follow modern historians. Ibn Battuta's daily death counts are a traveller's report, not a census, and are likely exaggerated; they show how the epidemic was experienced rather than its true toll. The plague kept returning to the region for centuries; it subsided in the Middle East by about 1351.",src:[SRCQ("Yaron Ayalon, 'The Black Death and the Rise of the Ottomans', ch. 1 of Natural Disasters in the Ottoman Empire: Plague, Famine, and Other Misfortunes (Cambridge University Press, 2015)","https://www.cambridge.org/core/books/natural-disasters-in-the-ottoman-empire/black-death-and-the-rise-of-the-ottomans/D83E412C0BB3C092E79683722AFFFC33","Supports World civilisations in parallel (History page)","Concurrently, plague traveled westward, arriving in the Crimea in 1346 and in Constantinople in 1347."),SRCQ("Yaron Ayalon, 'The Black Death and the Rise of the Ottomans', ch. 1 of Natural Disasters in the Ottoman Empire: Plague, Famine, and Other Misfortunes (Cambridge University Press, 2015)","https://www.cambridge.org/core/books/natural-disasters-in-the-ottoman-empire/black-death-and-the-rise-of-the-ottomans/D83E412C0BB3C092E79683722AFFFC33","Supports World civilisations in parallel (History page)","It reached Sicily, Marseille, and Alexandria in 1347; and made its way north into Italy and France in 1348,"),SRCQ("Yaron Ayalon, 'The Black Death and the Rise of the Ottomans', ch. 1 of Natural Disasters in the Ottoman Empire: Plague, Famine, and Other Misfortunes (Cambridge University Press, 2015)","https://www.cambridge.org/core/books/natural-disasters-in-the-ottoman-empire/black-death-and-the-rise-of-the-ottomans/D83E412C0BB3C092E79683722AFFFC33","Supports World civilisations in parallel (History page)","From Damascus, the plague spread north into Anatolia and southeast into Mosul and Baghdad by 1349."),SRCQ("Ibn Battuta, Travels in Asia and Africa 1325–1354, trans. and ed. H. A. R. Gibb (London: Broadway House, 1929) – Internet Medieval Sourcebook, Fordham University","https://sourcebooks.web.fordham.edu/halsall/source/1354ibnbattuta-plague.asp","Supports World civilisations in parallel (History page)"," on my return journey through Damascus, in the latter part of July 1348."),SRCQ("Ibn Battuta, Travels in Asia and Africa 1325–1354, trans. and ed. H. A. R. Gibb (London: Broadway House, 1929) – Internet Medieval Sourcebook, Fordham University","https://sourcebooks.web.fordham.edu/halsall/source/1354ibnbattuta-plague.asp","Supports World civilisations in parallel (History page)","God lightened their affliction; for the number of deaths in a single day at Damascus did not attain two thousand,")]},
 {id:"south-asia-madhava-s-infinite-series-in-the-",region:"south-asia",place:"Sangamagrama, Kerala, India",ys:1350,ye:1425,y:1388,domain:"maths",also:[],t:"Madhava's infinite series in the Kerala school",text:"Around 1400, Madhava of Sangamagrama found series for sine, cosine and arctangent, over 200 years before they were rediscovered in Europe.",disputed:false,note:"Madhava's own writings on these series do not survive; they are known from later Kerala-school authors such as Jyesthadeva.",src:[SRCQ("Madhava – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Madhava/","Supports World civilisations in parallel (History page)","around 1400 , which is over two hundred years before they were rediscovered in Europe.")]},
 {id:"southeast-asia-ayutthaya-siamese-capital-and",region:"southeast-asia",place:"Ayutthaya, Thailand",ys:1350,ye:1767,y:1558,domain:"governance",also:["trade"],t:"Ayutthaya: Siamese capital and global trading city",text:"Founded in 1350, Ayutthaya was the second Siamese capital and a centre of trade and diplomacy until it was destroyed in 1767.",disputed:false,note:"",src:[SRCQ("Historic City of Ayutthaya – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/576/","Supports World civilisations in parallel (History page)","The Historic City of Ayutthaya, founded in 1350, was the second capital of the Siamese Kingdom."),SRCQ("Historic City of Ayutthaya – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/576/","Supports World civilisations in parallel (History page)","The city was attacked and razed by the Burmese army in 1767")]},
 {id:"east-asia-jikji-printed-with-movable-metal-t",region:"east-asia",place:"Cheongju, Republic of Korea",ys:1377,ye:1377,y:1377,domain:"writing",also:[],t:"Jikji printed with movable metal type",text:"Jikji was printed in 1377 at Heungdeok-sa temple using movable cast-metal type. It is the oldest known book made this way.",disputed:false,note:"",src:[SRCQ("'Jikji', a treasure of the world of printing – Bibliothèque nationale de France","https://www.bnf.fr/en/jikji-treasure-world-printing","Supports World civilisations in parallel (History page)","It was printed in 1377 in what is now the city of Cheongju (Republic of Korea), 78 years before the Gutenberg Bible."),SRCQ("'Jikji', a treasure of the world of printing – Bibliothèque nationale de France","https://www.bnf.fr/en/jikji-treasure-world-printing","Supports World civilisations in parallel (History page)","It is considered by the international community, including UNESCO , to be the oldest known document printed using this process.")]},
 {id:"africa-west-oba-ewuare-strengthens-the-kingd",region:"africa-west",place:"Benin City, Nigeria",ys:1400,ye:1500,y:"15th century",domain:"governance",also:["trade"],t:"Oba Ewuare strengthens the Kingdom of Benin",text:"The Kingdom of Benin grew powerful under Oba Ewuare in the 15th century. Portuguese traders later sought commercial treaties with its rulers.",disputed:false,note:"",src:[SRCQ("Plaque with equestrian oba (king) and attendants, ca. 1540-70 - The Metropolitan Museum of Art","https://www.metmuseum.org/art/collection/search/310752","Supports World civilisations in parallel (History page)","During the fifteenth century reign of Oba Ewuare"),SRCQ("Plaque with equestrian oba (king) and attendants, ca. 1540-70 - The Metropolitan Museum of Art","https://www.metmuseum.org/art/collection/search/310752","Supports World civilisations in parallel (History page)","delegations of Portuguese traders assiduously sought to secure exclusive commercial treaties")]},
 {id:"africa-west-timbuktu-and-sankore-become-a-ca",region:"africa-west",place:"Timbuktu, Mali",ys:1400,ye:1600,y:"15th-16th centuries",domain:"learning",also:["architecture"],t:"Timbuktu and Sankore become a capital of learning",text:"Timbuktu, home of the Sankore university and other madrasas, was an intellectual and spiritual capital. Its great mosques recall its golden age.",disputed:false,note:"",src:[SRCQ("Timbuktu - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/119/","Supports World civilisations in parallel (History page)","Home of the prestigious Koranic Sankore University and other madrasas"),SRCQ("Timbuktu - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/119/","Supports World civilisations in parallel (History page)","was an intellectual and spiritual capital and a centre for the propagation of Islam throughout Africa in the 15th and 16th centuries")]},
 {id:"southeast-asia-melaka-sultanate-on-the-strai",region:"southeast-asia",place:"Melaka, Malaysia",ys:1400,ye:1511,y:1456,domain:"trade",also:[],t:"Melaka sultanate on the Straits trade route",text:"Melaka's history begins with the 15th-century Malay sultanate, which grew rich on trade between the Indian Ocean and East Asia.",disputed:false,note:"End date 1511 (Portuguese capture) is not stated on the UNESCO page, which says the Portuguese period began 'in the early 16th century'.",src:[SRCQ("Melaka and George Town, Historic Cities of the Straits of Malacca – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1223/","Supports World civilisations in parallel (History page)","in the 15th-century Malay sultanate")]},
 {id:"americas-andes-qhapaq-an-the-inca-road-syste",region:"americas-andes",place:"Andes (Colombia to Chile and Argentina)",ys:1400,ye:1532,y:1466,domain:"governance",also:["trade"],t:"Qhapaq Ñan: the Inca road system",text:"The Inca road network, over 30,000 km long, reached its peak in the 15th century. It carried goods, messages and armies across the empire.",disputed:false,note:"",src:[SRCQ("Qhapaq Ñan, Andean Road System – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1459/","Supports World civilisations in parallel (History page)","an extensive Inca communication, trade and defence network of roads"),SRCQ("Qhapaq Ñan, Andean Road System – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1459/","Supports World civilisations in parallel (History page)","It reached its maximum expansion in the 15th century")]},
 {id:"east-asia-zheng-he-s-seven-voyages-across-th",region:"east-asia",place:"Nanjing, China, to East Africa",ys:1405,ye:1433,y:1419,domain:"navigation",also:["trade"],t:"Zheng He's seven voyages across the Indian Ocean",text:"Between 1405 and 1433 the admiral Zheng He led seven fleets to South-East Asia, India, Arabia and East Africa.",disputed:false,note:"",src:[SRCQ("Zheng He timeline – Britannica","https://www.britannica.com/summary/Zheng-He-Timeline","Supports World civilisations in parallel (History page)","All voyages are suspended until 1431, when Zheng He embarks on a seventh voyage."),SRCQ("Zheng He timeline – Britannica","https://www.britannica.com/summary/Zheng-He-Timeline","Supports World civilisations in parallel (History page)","All voyages are suspended until 1431, when Zheng He embarks on a seventh voyage.")]},
 {id:"central-asia-ulugh-beg-s-madrasa-opens-on-th",region:"central-asia",place:"Samarkand, Uzbekistan",ys:1420,ye:1420,y:1420,domain:"learning",also:[],t:"Ulugh Beg's madrasa opens on the Registan",text:"Ulugh Beg's madrasa on Samarkand's Registan Square was completed in 1420. He appointed the best scientists he could find to teach there.",disputed:false,note:"",src:[SRCQ("Ulugh Beg – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Ulugh_Beg/","Supports World civilisations in parallel (History page)","The madrasah, fronting the Rigestan Square in Samarkand, was completed in 1420")]},
 {id:"central-asia-al-kashi-calculates-pi-to-16-de",region:"central-asia",place:"Samarkand, Uzbekistan",ys:1424,ye:1424,y:1424,domain:"maths",also:[],t:"Al-Kashi calculates pi to 16 decimal places",text:"Working in Samarkand, Jamshid al-Kashi calculated 2π to sixteen decimal places in July 1424, far beyond earlier results.",disputed:false,note:"",src:[SRCQ("al-Kashi – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Kashi/","Supports World civilisations in parallel (History page)","He produced his Treatise on the Circumference in July 1424")]},
 {id:"central-asia-ulugh-beg-s-observatory-and-sta",region:"central-asia",place:"Samarkand, Uzbekistan",ys:1424,ye:1437,y:1430,domain:"astronomy",also:[],t:"Ulugh Beg's observatory and star catalogue",text:"Ulugh Beg began an observatory at Samarkand in the 1420s. His star catalogue of 1437 gave positions of 992 stars.",disputed:true,note:"MacTutor's two biographies disagree on when construction began: 1424 (al-Kashi page) or 1428 (Ulugh Beg page).",src:[SRCQ("Ulugh Beg – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Ulugh_Beg/","Supports World civilisations in parallel (History page)","Ulugh Beg built an observatory at Samarkand, the construction of this beginning in 1428 ."),SRCQ("al-Kashi – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Al-Kashi/","Supports World civilisations in parallel (History page)","In 1424 Ulugh Beg began the construction of an observatory in Samarkand"),SRCQ("Ulugh Beg – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Ulugh_Beg/","Supports World civilisations in parallel (History page)","Published in 1437 , it gives the positions of 992 stars.")]},
 {id:"east-asia-king-sejong-creates-the-korean-alp",region:"east-asia",place:"Hanseong (Seoul), Republic of Korea",ys:1443,ye:1446,y:1444,domain:"writing",also:["learning"],t:"King Sejong creates the Korean alphabet, Hangul",text:"King Sejong completed a new Korean alphabet in 1443 and promulgated it in 1446 in the Hunminjeongum.",disputed:false,note:"",src:[SRCQ("Hunminjeongum Manuscript – UNESCO Memory of the World","https://www.unesco.org/en/memory-world/hunminjeongum-manuscript","Supports World civilisations in parallel (History page)","the Korean alphabet of the same name, now called han-gul, the development of which he completed in 1443."),SRCQ("Hunminjeongum Manuscript – UNESCO Memory of the World","https://www.unesco.org/en/memory-world/hunminjeongum-manuscript","Supports World civilisations in parallel (History page)","The manuscript published in the ninth lunar month of 1446")]},
 {id:"africa-south-khami-becomes-capital-of-the-to",region:"africa-south",place:"Khami, Zimbabwe",ys:1450,ye:1650,y:"1450-1650",domain:"governance",also:["architecture"],t:"Khami becomes capital of the Torwa dynasty",text:"After Great Zimbabwe declined, Khami became the capital of the Torwa dynasty. It continued the Zimbabwe stone-building tradition.",disputed:false,note:"",src:[SRCQ("Khami Ruins National Monument - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/365/","Supports World civilisations in parallel (History page)","The property was the capital of the Torwa dynasty"),SRCQ("Khami Ruins National Monument - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/365/","Supports World civilisations in parallel (History page)","which arose from the collapse of the Great Zimbabwe Kingdom between 1450 -1650")]},
 {id:"africa-south-khami-imports-goods-from-europe",region:"africa-south",place:"Khami, Zimbabwe",ys:1450,ye:1650,y:"15th-17th centuries",domain:"trade",also:[],t:"Khami imports goods from Europe and China",text:"Objects from Europe and China found at Khami show it was a major long-distance trading centre over a long period.",disputed:false,note:"",src:[SRCQ("Khami Ruins National Monument - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/365/","Supports World civilisations in parallel (History page)","The discovery of objects from Europe and China shows that Khami was a major centre for trade over a long period of time."),SRCQ("Khami Ruins National Monument - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/365/","Supports World civilisations in parallel (History page)","the diverse range of imported artefacts provide evidence of 15th and 17th century Spanish porcelain")]},
 {id:"americas-andes-machu-picchu-built-with-farmi",region:"americas-andes",place:"Machu Picchu, Cusco, Peru",ys:1450,ye:1532,y:1491,domain:"architecture",also:["agriculture"],t:"Machu Picchu built with farming terraces",text:"Machu Picchu was built in the 15th century with irrigation canals and farming terraces. It was abandoned after the Spanish conquest.",disputed:false,note:"",src:[SRCQ("Historic Sanctuary of Machu Picchu – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/274/","Supports World civilisations in parallel (History page)","Built in the fifteenth century Machu Picchu was abandoned when the Inca Empire was conquered by the Spaniards"),SRCQ("Historic Sanctuary of Machu Picchu – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/274/","Supports World civilisations in parallel (History page)","Numerous subsidiary centres, an extensive road and trail system, irrigation canals and agricultural terraces")]},
 {id:"europe-gutenberg-bible-printed-with-movable-",region:"europe",place:"Mainz, Germany",ys:1455,ye:1455,y:"c. 1455",domain:"writing",also:["learning"],t:"Gutenberg Bible printed with movable type",text:"Johann Gutenberg completed printing the Bible with movable metal type at Mainz. Printing spread books quickly across Europe.",disputed:false,note:"",src:[SRCQ("The Gutenberg Bible - Library of Congress Bible Collection","https://www.loc.gov/exhibits/bibles/the-gutenberg-bible.html","Supports World civilisations in parallel (History page)","The printing of the Bible was probably completed late in 1455 at Mainz, Germany.")]},
 {id:"africa-west-askia-mohamed-builds-his-tomb-at",region:"africa-west",place:"Gao, Mali",ys:1495,ye:1495,y:"1495",domain:"architecture",also:["governance"],t:"Askia Mohamed builds his tomb at Gao",text:"Askia Mohamed, emperor of Songhai, built a monumental earthen tomb in his capital Gao. It reflects the power of an empire that flourished in the 15th and 16th centuries.",disputed:false,note:"",src:[SRCQ("Tomb of Askia - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1139/","Supports World civilisations in parallel (History page)","was built by Askia Mohamed, the Emperor of Songhai, in 1495 in his capital Gao")]},
 {id:"africa-west-sukur-iron-smelting-and-terraced",region:"africa-west",place:"Sukur, Nigeria",ys:1500,ye:1600,y:"from 16th century",domain:"metallurgy",also:["agriculture"],t:"Sukur: iron smelting and terraced hill farming",text:"Sukur has a recorded history of iron smelting going back to the 16th century. Its terraced fields show intensive hill farming that still continues.",disputed:false,note:"",src:[SRCQ("Sukur Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/938/","Supports World civilisations in parallel (History page)","Sukur is an ancient settlement with a recorded history of iron smelting technology"),SRCQ("Sukur Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/938/","Supports World civilisations in parallel (History page)","dating back to the 16th century"),SRCQ("Sukur Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/938/","Supports World civilisations in parallel (History page)","The traditional terraced system of agriculture and its associated ritual systems are still flourishing")]},
 {id:"africa-central-kongo-court-commissions-ivory",region:"africa-central",place:"Kingdom of Kongo",ys:1500,ye:1600,y:"16th century",domain:"arts",also:[],t:"Kongo court commissions ivory carvings",text:"Carved ivories from the 16th century are among the earliest known royal commissions of the Kongo Kingdom. Kongo carvers worked ivory for centuries afterwards.",disputed:false,note:"",src:[SRCQ("Kongo Ivories - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/kong/hd_kong.htm","Supports World civilisations in parallel (History page)","from the sixteenth century are among the earliest known of the Kongo Kingdom’s royal commissions in ivory")]},
 {id:"europe-lisbon-monastery-commemorates-vasco-d",region:"europe",place:"Lisbon, Portugal",ys:1502,ye:1502,y:"1502",domain:"navigation",also:["architecture"],t:"Lisbon monastery commemorates Vasco da Gama's voyage",text:"The Jeronimos Monastery was begun in 1502 to commemorate Vasco da Gama's sea voyage to India. Portuguese voyages opened direct European sea routes around Africa.",disputed:false,note:"The voyage itself took place in 1497-1499 (not stated in the quoted source). These voyages were later tied to the Atlantic slave trade.",src:[SRCQ("Monastery of the Hieronymites and Tower of Belem in Lisbon - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/263/","Supports World civilisations in parallel (History page)","construction of which began in 1502"),SRCQ("Monastery of the Hieronymites and Tower of Belem in Lisbon - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/263/","Supports World civilisations in parallel (History page)","built to commemorate Vasco da Gama's expedition")]},
 {id:"africa-central-kongo-king-afonso-i-writes-le",region:"africa-central",place:"Mbanza Kongo, Angola",ys:1526,ye:1526,y:"1526",domain:"writing",also:["governance"],t:"Kongo king Afonso I writes letters to Portugal",text:"Nzinga Mbemba (Afonso I) wrote a series of letters to the king of Portugal. He asked for an end to the slave trade that was damaging his kingdom.",disputed:false,note:"",src:[SRCQ("Excerpt of letter from Nzinga Mbemba to Portuguese King Joao III | World History Commons (George Mason University)","https://worldhistorycommons.org/node/2382","Supports World civilisations in parallel (History page)","In 1526, the king of the Kongo, Nzinga Mbemba"),SRCQ("Excerpt of letter from Nzinga Mbemba to Portuguese King Joao III | World History Commons (George Mason University)","https://worldhistorycommons.org/node/2382","Supports World civilisations in parallel (History page)","began writing a series of twenty-four letters to the Portuguese King Joao III appealing for an end to the slave trade")]},
 {id:"africa-west-benin-brass-plaques-cast-for-the",region:"africa-west",place:"Benin City, Nigeria",ys:1540,ye:1570,y:"c. 1540-1570",domain:"arts",also:["metallurgy"],t:"Benin brass plaques cast for the royal palace",text:"A guild of brass casters made some 900 relief plaques to decorate the royal palace. They record court life and history.",disputed:false,note:"Date is the Met dating of this plaque (ca. 1540-70); the series spans a longer period.",src:[SRCQ("Plaque with equestrian oba (king) and attendants, ca. 1540-70 - The Metropolitan Museum of Art","https://www.metmuseum.org/art/collection/search/310752","Supports World civilisations in parallel (History page)","a remarkable series of some 900 rectangular brass plaques were cast in relief"),SRCQ("Plaque with equestrian oba (king) and attendants, ca. 1540-70 - The Metropolitan Museum of Art","https://www.metmuseum.org/art/collection/search/310752","Supports World civilisations in parallel (History page)","by a guild of brass casters for display across at the facade of the royal palace")]},
 {id:"europe-copernicus-places-the-sun-at-the-cent",region:"europe",place:"Frombork and Nuremberg",ys:1543,ye:1543,y:"1543",domain:"astronomy",also:[],t:"Copernicus places the Sun at the centre",text:"Copernicus published his full theory that the Sun, not the Earth, is at rest at the centre. It began a revolution in astronomy.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1500 - 1600","https://mathshistory.st-andrews.ac.uk/Chronology/8/","Supports World civilisations in parallel (History page)","1543 Copernicus publishes De revolutionibus orbium coelestium (On the revolutions of the heavenly spheres).")]},
 {id:"europe-vesalius-publishes-the-fabrica-on-hum",region:"europe",place:"Padua and Basel",ys:1543,ye:1543,y:"1543",domain:"medicine",also:[],t:"Vesalius publishes the Fabrica on human anatomy",text:"Vesalius, professor of anatomy at Padua, published a detailed, illustrated study of the human body based on dissection.",disputed:false,note:"",src:[SRCQ("Historical Anatomies on the Web: Vesalius - US National Library of Medicine","https://sites.wip.nlm.nih.gov/exhibition/historicalanatomies/vesalius_bio.html","Supports World civilisations in parallel (History page)","In 1543, his famous De corporis humani fabrica libri septem (Seven books on the fabric of the human body) was published"),SRCQ("Historical Anatomies on the Web: Vesalius - US National Library of Medicine","https://sites.wip.nlm.nih.gov/exhibition/historicalanatomies/vesalius_bio.html","Supports World civilisations in parallel (History page)","he moved to Padua in 1537, where he became a professor of anatomy")]},
 {id:"europe-world-s-first-botanical-garden-create",region:"europe",place:"Padua, Italy",ys:1545,ye:1545,y:"1545",domain:"learning",also:["agriculture", "medicine"],t:"World's first botanical garden created in Padua",text:"Padua created the first botanical garden, a place to grow and study plants scientifically.",disputed:true,note:"UNESCO calls it the first; earlier gardens existed elsewhere depending on definition.",src:[SRCQ("Botanical Garden (Orto Botanico), Padua - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/824/","Supports World civilisations in parallel (History page)","The world's first botanical garden was created in Padua in 1545.")]},
 {id:"americas-meso-mart-n-de-la-cruz-s-aztec-herb",region:"americas-meso",place:"Colegio de Santa Cruz, Tlatelolco, Mexico",ys:1552,ye:1552,y:1552,domain:"medicine",also:[],t:"Martín de la Cruz's Aztec herbal",text:"In 1552 the Nahua physician Martín de la Cruz wrote an illustrated book of Mexican medicinal plants, translated into Latin by Juan Badiano.",disputed:false,note:"The 1552 date is in the catalogue record ('1552') beside the quoted passage; the record is for a 1940 Smithsonian study of the manuscript.",src:[SRCQ("Concerning the Badianus manuscript, an Aztec herbal – Wellcome Collection","https://wellcomecollection.org/works/bbup7ftn","Supports World civilisations in parallel (History page)","Libellus de medicinalibus Indorum herbis, quem quidam Indus Collegii sancte crucis medicus composuit"),SRCQ("Concerning the Badianus manuscript, an Aztec herbal – Wellcome Collection","https://wellcomecollection.org/works/bbup7ftn","Supports World civilisations in parallel (History page)","There seems little doubt that the principal author of the manuscript is one Martin de la Cruz")]},
 {id:"east-asia-chinese-variolation-protection-aga",region:"east-asia",place:"Southern China",ys:1560,ye:1569,y:"By the 1560s",domain:"medicine",also:[],t:"Chinese variolation: protection against smallpox by the nose",text:"By the 1560s Chinese practitioners protected children against smallpox by deliberately infecting them with material from smallpox scabs, often blown into the nose as a dried powder. The Kangxi Emperor later had his own children inoculated this way.",disputed:true,note:"Where variolation began is unresolved: Needham and Chinese historians argue for China, others for India; stories of a 10th-11th-century Chinese origin are not supported by contemporary records. The method carried real risks and could spark outbreaks, so it is not comparable with modern vaccination.",src:[SRCQ("Iwo Amelung, 'Successful smallpox prevention and inoculation in China in the 17th and 18th centuries', Forschung Frankfurt 1.2021, Goethe University Frankfurt","https://www.uni-frankfurt.de/108535770.pdf","Supports World civilisations in parallel (History page)","Variolation had been known in China since the 1560s and was used above all in the south."),SRCQ("Iwo Amelung, 'Successful smallpox prevention and inoculation in China in the 17th and 18th centuries', Forschung Frankfurt 1.2021, Goethe University Frankfurt","https://www.uni-frankfurt.de/108535770.pdf","Supports World civilisations in parallel (History page)","Even today, it has not yet been conclusively decided whether variolation was indeed developed in China, as postulated by Needham and Chinese historians, or whether it in fact originated in India."),SRCQ("Indiana University Libraries exhibit: Qing Dynasty","https://collections.libraries.indiana.edu/iulibraries/s/smallpox-vaccine-exhibit/page/great-qing","Supports World civilisations in parallel (History page)","In 1678, the emperor arranged for his family to be variolated.")]},
 {id:"africa-east-konso-stone-walled-farming-terra",region:"africa-east",place:"Konso, Ethiopia",ys:1600,ye:1600,y:"by c. 1600",domain:"agriculture",also:["architecture"],t:"Konso stone-walled farming terraces",text:"The Konso people built stone-walled terraces and fortified villages on dry hills. This living farming tradition goes back at least 21 generations.",disputed:true,note:"Start date estimated from \"more than 400 years\" (UNESCO listing, 2011); the terracing may be older.",src:[SRCQ("Konso Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1333/","Supports World civilisations in parallel (History page)","a living cultural tradition stretching back 21 generations (more than 400 years)"),SRCQ("Konso Cultural Landscape - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1333/","Supports World civilisations in parallel (History page)","stone walled terraces and fortified settlements")]},
 {id:"africa-central-luba-model-of-statecraft-spre",region:"africa-central",place:"Luba and Lunda lands, DR Congo",ys:1600,ye:1600,y:"c. 1600",domain:"governance",also:[],t:"Luba model of statecraft spreads to the Lunda",text:"A Luba figure brought the Luba model of statecraft to the Lunda by marriage. The Luba and Lunda became major savanna states.",disputed:true,note:"Based on oral tradition; date is approximate.",src:[SRCQ("Kingdoms of the Savanna: The Luba and Lunda Empires - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/luba/hd_luba.htm","Supports World civilisations in parallel (History page)","introduced the Luba model of statecraft to the Lunda sometime around 1600 when he married a local princess")]},
 {id:"oceania-chief-roi-mata-s-domain",region:"oceania",place:"Efate, Lelepa and Artok, Vanuatu",ys:1600,ye:1630,y:1615,domain:"governance",also:[],t:"Chief Roi Mata's domain",text:"Three early 17th-century sites in Vanuatu are linked to Roi Mata, the last paramount chief of central Vanuatu. Taboos on them have been kept for 400 years.",disputed:false,note:"",src:[SRCQ("Chief Roi Mata’s Domain – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1280/","Supports World civilisations in parallel (History page)","It consists of three early 17th century AD sites on the islands of Efate, Lelepa and Artok"),SRCQ("Chief Roi Mata’s Domain – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1280/","Supports World civilisations in parallel (History page)","the tabu prohibitions on the use of Roi Mata’s residence and burial site have been observed for 400 years")]},
 {id:"europe-kepler-shows-planets-move-in-ellipses",region:"europe",place:"Prague",ys:1609,ye:1609,y:"1609",domain:"astronomy",also:[],t:"Kepler shows planets move in ellipses",text:"Kepler published his first two laws of planetary motion, based on observations of Mars.",disputed:false,note:"Place is where Kepler worked; not stated in the quoted entry.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1600 - 1625","https://mathshistory.st-andrews.ac.uk/Chronology/9/","Supports World civilisations in parallel (History page)","1609 Kepler publishes Astronomia nova (New Astronomy).")]},
 {id:"europe-napier-publishes-logarithms",region:"europe",place:"Edinburgh, Scotland",ys:1614,ye:1614,y:"1614",domain:"maths",also:[],t:"Napier publishes logarithms",text:"John Napier published logarithms, which made long calculations much faster for astronomers and navigators.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1600 - 1625","https://mathshistory.st-andrews.ac.uk/Chronology/9/","Supports World civilisations in parallel (History page)","1614 Napier publishes his work on logarithms")]},
 {id:"africa-west-kingdom-of-dahomey-rules-from-ab",region:"africa-west",place:"Abomey, Benin",ys:1625,ye:1900,y:"1625-1900",domain:"governance",also:["architecture", "arts"],t:"Kingdom of Dahomey rules from Abomey",text:"Twelve kings ruled the Kingdom of Dahomey from Abomey, each building a palace in the same walled area. The palaces are known for their coloured bas-reliefs.",disputed:true,note:"The same UNESCO page also gives 1620 to 1900.",src:[SRCQ("Royal Palaces of Abomey - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/323/","Supports World civilisations in parallel (History page)","From 1625 to 1900, 12 kings succeeded one another at the head of the powerful Kingdom of Abomey."),SRCQ("Royal Palaces of Abomey - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/323/","Supports World civilisations in parallel (History page)","The use of traditional materials and polychrome bas-reliefs are important architectural features.")]},
 {id:"africa-central-shyaam-unites-the-chiefdoms-o",region:"africa-central",place:"Kuba lands, DR Congo",ys:1625,ye:1625,y:"c. 1625",domain:"governance",also:[],t:"Shyaam unites the chiefdoms of the Kuba kingdom",text:"Shyaam aMbul aNgoong united the local chiefdoms and shaped Kuba political, social and economic life.",disputed:false,note:"",src:[SRCQ("Kingdoms of the Savanna: The Kuba Kingdom - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/en/essays/kingdoms-of-the-savanna-the-kuba-kingdom","Supports World civilisations in parallel (History page)","Sometime around 1625, an outsider unseated a rival ruler and unified the area’s chiefdoms under his leadership."),SRCQ("Kingdoms of the Savanna: The Kuba Kingdom - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/en/essays/kingdoms-of-the-savanna-the-kuba-kingdom","Supports World civilisations in parallel (History page)","Shyaam became the architect of Kuba political, social, and economic life.")]},
 {id:"south-asia-taj-mahal-built-for-mumtaz-mahal",region:"south-asia",place:"Agra, Uttar Pradesh, India",ys:1632,ye:1653,y:1642,domain:"architecture",also:["arts"],t:"Taj Mahal built for Mumtaz Mahal",text:"The Mughal emperor Shah Jahan had the Taj Mahal built from 1632 to 1648; the outer courtyard was finished in 1653.",disputed:false,note:"",src:[SRCQ("Taj Mahal – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/252/","Supports World civilisations in parallel (History page)","with construction starting in 1632 AD and completed in 1648 AD"),SRCQ("Taj Mahal – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/252/","Supports World civilisations in parallel (History page)","the outer courtyard and its cloisters were added subsequently and completed in 1653 AD")]},
 {id:"africa-east-fasil-ghebbi-becomes-the-ethiopi",region:"africa-east",place:"Gondar, Ethiopia",ys:1636,ye:1636,y:"1636",domain:"governance",also:["architecture"],t:"Fasil Ghebbi becomes the Ethiopian royal seat",text:"The fortress-city of Fasil Ghebbi at Gondar was the residence of Emperor Fasilides and his successors. It mixes Ethiopian, Arab and European building styles.",disputed:false,note:"UNESCO says 16th and 17th centuries; Fasilides himself reigned in the 17th century.",src:[SRCQ("Fasil Ghebbi, Gondar Region - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/19/","Supports World civilisations in parallel (History page)","In the 16th and 17th centuries, the fortress-city of Fasil Ghebbi was the residence of the Ethiopian emperor Fasilides")]},
 {id:"africa-central-lunda-ruler-opens-trade-route",region:"africa-central",place:"Lunda capital to Atlantic coast",ys:1650,ye:1650,y:"by 1650",domain:"trade",also:[],t:"Lunda ruler opens trade routes to the Atlantic",text:"By 1650 the Lunda ruler Mwaant Yaav Naweej had set up trade routes from his capital to the Atlantic coast. The Lunda also controlled the regional copper trade.",disputed:false,note:"",src:[SRCQ("Kingdoms of the Savanna: The Luba and Lunda Empires - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/luba/hd_luba.htm","Supports World civilisations in parallel (History page)","By 1650, the ruler Mwaant Yaav Naweej had established trade routes from his capital to the Atlantic coast"),SRCQ("Kingdoms of the Savanna: The Luba and Lunda Empires - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/toah/hd/luba/hd_luba.htm","Supports World civilisations in parallel (History page)","controlled the regional copper trade")]},
 {id:"africa-south-buchu-khoi-and-san-plant-medici",region:"africa-south",place:"Western Cape, South Africa (Khoi and San peoples)",ys:1652,ye:1800,y:"Recorded from the Cape colonial era (Khoi and San use older)",domain:"medicine",also:[],t:"Buchu: Khoi and San plant medicine adopted at the Cape",text:"The Khoi and San used buchu (Agathosma species), mixing the dried, powdered leaves with sheep fat as an ointment and chewing the leaves for stomach complaints. The name 'buchu' comes from Khoi-San languages, and the plant became a staple remedy of early Cape colonists.",disputed:false,note:"Khoi and San use long predates written records; the start date marks Dutch settlement at the Cape (1652), after which European use was recorded. Traditional uses are documented; modern clinical evidence for specific benefits is limited and is not claimed here. Part of this rests on one independent source.",src:[SRCQ("Agathosma crenulata – PlantZAfrica, South African National Biodiversity Institute","https://pza.sanbi.org/node/9673","Supports World civilisations in parallel (History page)","Buchu is part of cultural heritage of the Khoi and San people who used the dried and powered leaves mixed with sheep fat"),SRCQ("Agathosma crenulata – PlantZAfrica, South African National Biodiversity Institute","https://pza.sanbi.org/node/9673","Supports World civilisations in parallel (History page)","Leaves were also chewed to relieve stomach complaints."),SRCQ("Skosana, Aboua and Du Plessis, 'Buchu – The Multi-Purpose Ethnomedicinally Important Specie' (IntechOpen, 2014), Cape Peninsula University of Technology repository","https://digitalknowledge.cput.ac.za/handle/11189/7313?mode=full","Supports World civilisations in parallel (History page)","The word “Buchu” originated from the Khoi-San people of southern Africa,"),SRCQ("'buchu, n.', Dictionary of South African English (Dictionary Unit for South African English, Rhodes University), 2025","https://dsae.co.za/entry/buchu/e01320","Supports World civilisations in parallel (History page)","Buchu leaves were pounded into a powder by the Khoikhoi and used cosmetically, mixed with sheeps' fat, on their bodies."),SRCQ("'Medicinal Plants Used in the Western Cape', Western Cape Department of Cultural Affairs and Sport, Museum Service (Google Arts & Culture)","https://artsandculture.google.com/story/medicinal-plants-used-in-the-western-cape-department-of-cultural-affars-and-sport-western-cape/WwWR6tT1K2Tlrg?hl=en","Supports World civilisations in parallel (History page)","Dutch colonists adopted its indigenous use as a treatment for stomach problems and made buchu brandy for this purpose."),SRCQ("'Medicinal Plants Used in the Western Cape', Western Cape DCAS Museum Service","https://artsandculture.google.com/story/medicinal-plants-used-in-the-western-cape-department-of-cultural-affars-and-sport-western-cape/WwWR6tT1K2Tlrg?hl=en","Supports World civilisations in parallel (History page)","It was mixed with sheep fat to use for massage and to treat both physical and spiritual ailments.")]},
 {id:"europe-royal-society-of-london-founded",region:"europe",place:"London, England",ys:1662,ye:1662,y:"1662",domain:"learning",also:[],t:"Royal Society of London founded",text:"The Royal Society was founded to promote experimental science. It became one of the oldest scientific academies in continuous existence.",disputed:true,note:"The Society first met in 1660; it received its royal charter in 1662.",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1650 - 1675","https://mathshistory.st-andrews.ac.uk/Chronology/11/","Supports World civilisations in parallel (History page)","1662 The Royal Society of London is founded.")]},
 {id:"east-asia-seki-takakazu-studies-determinants",region:"east-asia",place:"Edo (Tokyo), Japan",ys:1683,ye:1683,y:1683,domain:"maths",also:[],t:"Seki Takakazu studies determinants",text:"In 1683 the Japanese mathematician Seki Takakazu studied determinants, ten years before Leibniz did so independently.",disputed:false,note:"",src:[SRCQ("Takakazu Seki – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Seki/","Supports World civilisations in parallel (History page)","Seki was the first person to study determinants in 1683 ."),SRCQ("Takakazu Seki – Biography – MacTutor, University of St Andrews","https://mathshistory.st-andrews.ac.uk/Biographies/Seki/","Supports World civilisations in parallel (History page)","Ten years later Leibniz , independently, used determinants to solve simultaneous equations")]},
 {id:"europe-newton-s-principia-sets-out-laws-of-m",region:"europe",place:"Cambridge and London, England",ys:1687,ye:1687,y:"1687",domain:"maths",also:["astronomy"],t:"Newton's Principia sets out laws of motion and gravity",text:"Newton explained motion, gravity, tides and planetary orbits with mathematics.",disputed:false,note:"",src:[SRCQ("MacTutor History of Mathematics (University of St Andrews): Chronology 1675 - 1700","https://mathshistory.st-andrews.ac.uk/Chronology/12/","Supports World civilisations in parallel (History page)","1687 Newton publishes The Principia")]},
 {id:"africa-west-asante-kingdom-reaches-its-peak",region:"africa-west",place:"Kumasi, Ghana",ys:1700,ye:1800,y:"18th century",domain:"architecture",also:["governance"],t:"Asante Kingdom reaches its peak",text:"The Asante Kingdom was influential, powerful and wealthy, with its own architectural style. Its traditional buildings near Kumasi survive today.",disputed:false,note:"",src:[SRCQ("Asante Traditional Buildings - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/35/","Supports World civilisations in parallel (History page)","Near Kumasi, a group of traditional buildings are the last remaining testimony of the great Asante civilization"),SRCQ("Asante Traditional Buildings - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/35/","Supports World civilisations in parallel (History page)","which reached its peak in the 18th century")]},
 {id:"africa-central-kuba-king-introduces-ndop-roy",region:"africa-central",place:"Kuba lands, DR Congo",ys:1700,ye:1700,y:"c. 1700",domain:"arts",also:["governance"],t:"Kuba king introduces ndop royal portrait sculpture",text:"King Mishe miShyaang aMbul introduced ndop, wooden portrait figures of Kuba kings. They became a key royal art form.",disputed:false,note:"",src:[SRCQ("Kingdoms of the Savanna: The Kuba Kingdom - The Metropolitan Museum of Art (Heilbrunn Timeline of Art History)","https://www.metmuseum.org/en/essays/kingdoms-of-the-savanna-the-kuba-kingdom","Supports World civilisations in parallel (History page)","Around 1700, King Mishe miShyaang aMbul introduced a new genre of wood portrait sculpture called ndop.")]},
 {id:"south-asia-jantar-mantar-observatory-built-a",region:"south-asia",place:"Jaipur, Rajasthan, India",ys:1700,ye:1735,y:1718,domain:"astronomy",also:[],t:"Jantar Mantar observatory built at Jaipur",text:"The Jantar Mantar at Jaipur, built in the early 18th century, has about 20 large fixed instruments for naked-eye astronomy.",disputed:false,note:"UNESCO says 'early 18th century'; the year range here simply represents that phrase.",src:[SRCQ("The Jantar Mantar, Jaipur – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1338/","Supports World civilisations in parallel (History page)","The Jantar Mantar, in Jaipur, is an astronomical observation site built in the early 18th century.")]},
 {id:"europe-coke-fired-blast-furnace-at-coalbrook",region:"europe",place:"Coalbrookdale, England",ys:1708,ye:1708,y:"1708",domain:"metallurgy",also:[],t:"Coke-fired blast furnace at Coalbrookdale",text:"The Coalbrookdale blast furnace marks the use of coke to smelt iron. It helped start the Industrial Revolution.",disputed:true,note:"Often dated 1709 for the first coke smelting; UNESCO gives the furnace as built in 1708.",src:[SRCQ("Ironbridge Gorge - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/371/","Supports World civilisations in parallel (History page)","Nearby, the blast furnace of Coalbrookdale, built in 1708, is a reminder of the discovery of coke.")]},
 {id:"americas-north-jamaican-maroons-win-freedom-",region:"americas-north",place:"Jamaica",ys:1739,ye:1740,y:1740,domain:"governance",also:[],t:"Jamaican Maroons win freedom by treaty",text:"After years of resistance, Maroon leaders Cudjoe (March 1739) and Quao (December 1739) signed treaties with the British; Nanny's followed a year later.",disputed:false,note:"The treaties granted freedom and land but also required Maroons to return future escapees, which is debated in Maroon history.",src:[SRCQ("The Jamaican Maroons – National Library of Jamaica","https://nlj.gov.jm/history-notes/The%20Maroons%20edited%20final.htm","Supports World civilisations in parallel (History page)","It was the first Maroon treaty and was signed by the fierce Leeward Maroon leader, Cudjoe, on 1st March 1739."),SRCQ("The Jamaican Maroons – National Library of Jamaica","https://nlj.gov.jm/history-notes/The%20Maroons%20edited%20final.htm","Supports World civilisations in parallel (History page)","which was eventually signed by the Windward Maroon leader, Quao, on 23rd December 1739.")]},
 {id:"europe-kew-gardens-founded-for-plant-science",region:"europe",place:"Kew, London",ys:1759,ye:1759,y:"1759",domain:"agriculture",also:["learning"],t:"Kew Gardens founded for plant science",text:"Kew's gardens have contributed to the study of plant diversity and economic botany since 1759. Much of this work was tied to colonial plant transfers.",disputed:false,note:"",src:[SRCQ("Royal Botanic Gardens, Kew - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1084/","Supports World civilisations in parallel (History page)","Since their creation in 1759, the gardens have made a significant and uninterrupted contribution"),SRCQ("Royal Botanic Gardens, Kew - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/1084/","Supports World civilisations in parallel (History page)","the study of plant diversity and economic botany")]},
 {id:"europe-harrison-s-h4-sea-clock-tested-on-voy",region:"europe",place:"Portsmouth to Jamaica",ys:1761,ye:1761,y:"1761",domain:"navigation",also:[],t:"Harrison's H4 sea clock tested on voyage to Jamaica",text:"John Harrison's H4 timekeeper was tested on a voyage to Jamaica. Accurate sea clocks let sailors find longitude.",disputed:false,note:"",src:[SRCQ("Longitude found - the story of Harrison's timekeepers | Royal Museums Greenwich","https://www.rmg.co.uk/stories/topics/harrisons-clocks-longitude-problem","Supports World civilisations in parallel (History page)","In 1761 the Commissioners gave permission for Harrison's son, William, to prepare for a voyage to Jamaica to trial the H4 timekeeper.")]},
 {id:"oceania-tupaia-charts-the-islands-of-the-pac",region:"oceania",place:"Raʻiātea and Tahiti, Society Islands",ys:1769,ye:1770,y:1770,domain:"navigation",also:["learning"],t:"Tupaia charts the islands of the Pacific",text:"In 1769–70 the Raʻiātean navigator Tupaia drew a chart of Pacific islands with crew of Cook's Endeavour, drawing on Polynesian navigation knowledge.",disputed:false,note:"",src:[SRCQ("Tupaia's Map – University of Potsdam","https://www.uni-potsdam.de/en/iaa-cult/staff/schwarz/tupaias-map","Supports World civilisations in parallel (History page)","in collaboration with various members of the crew of James Cook’s Endeavour in 1769/1770."),SRCQ("On tour with Tupaia – Natural History Museum","https://www.nhm.ac.uk/discover/on-tour-with-tupaia.html","Supports World civilisations in parallel (History page)","a chief custodian of important ancestral, astronomical and navigational knowledge.")]},
 {id:"europe-first-iron-bridge-erected",region:"europe",place:"Ironbridge, England",ys:1779,ye:1779,y:"1779",domain:"architecture",also:["metallurgy"],t:"First iron bridge erected",text:"Abraham Darby III built the Iron Bridge, a landmark in the use of cast iron in construction.",disputed:false,note:"\"First\" iron bridge is general knowledge, not stated in the quoted text.",src:[SRCQ("Ironbridge Gorge - UNESCO World Heritage Centre","https://whc.unesco.org/en/list/371/","Supports World civilisations in parallel (History page)","It was built in 1779 by Abraham Darby III from the drawings of the architect Thomas Farnolls Pritchard.")]},
 {id:"americas-north-haiti-first-state-born-of-a-s",region:"americas-north",place:"Saint-Domingue (Haiti)",ys:1790,ye:1804,y:1797,domain:"governance",also:[],t:"Haiti: first state born of a slave revolt",text:"After fourteen years of struggle by enslaved people, Jean-Jacques Dessalines proclaimed the independent Republic of Haiti on 1 January 1804.",disputed:false,note:"Start year derived from 'fourteen years'; the general uprising is usually dated to August 1791.",src:[SRCQ("National History Park – Citadel, Sans Souci, Ramiers – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/180/","Supports World civilisations in parallel (History page)","On 1 January 1804, after fourteen years of struggle by the island’s black slaves against the colonists,"),SRCQ("National History Park – Citadel, Sans Souci, Ramiers – UNESCO World Heritage Centre","https://whc.unesco.org/en/list/180/","Supports World civilisations in parallel (History page)","Since then, Haiti remains the first state in the world resulting from a slave revolt.")]},
 {id:"oceania-marshallese-stick-charts-teach-ocean",region:"oceania",place:"Marshall Islands",ys:1800,ye:1900,y:1850,domain:"navigation",also:["learning"],t:"Marshallese stick charts teach ocean swells",text:"Known to outsiders from the 19th century, Marshallese stick charts map swells and islands. Navigators used them to teach, not to carry at sea.",disputed:false,note:"The practice is older than the 19th-century European records; no earlier date is given by the source.",src:[SRCQ("Stick chart from the Marshall Islands – Royal Museums Greenwich","https://rmg.co.uk/collections/objects/rmgc-object-670368","Supports World civilisations in parallel (History page)","Known from the 19th century, these charts allowed Marshall islanders to negotiate the 34 low islands in the archipelago"),SRCQ("Stick chart from the Marshall Islands – Royal Museums Greenwich","https://rmg.co.uk/collections/objects/rmgc-object-670368","Supports World civilisations in parallel (History page)","The curved and diagonal sticks represent known swells and wave patterns.")]},
 {id:"africa-central-luba-lukasa-memory-boards-rec",region:"africa-central",place:"Luba region, south-eastern Democratic Republic of the Congo",ys:1800,ye:1950,y:"19th–mid-20th century",domain:"medicine",also:[],t:"Luba lukasa memory boards record history and medicinal practice",text:"Members of the Luba mbudye association used lukasa, hand-held boards studded with beads and pins or carved, as memory devices. Trained readers drew on them to recall royal genealogies, places of importance and medicinal practices.",disputed:false,note:"Lukasa are knowledge and memory devices rather than medical texts; medicine is one of several kinds of knowledge they encoded, and they could only be 'read' by initiated members. Dates are those of surviving museum examples; the practice may be older.",src:[SRCQ("Ways of Recording African History – The Met, Heilbrunn Timeline of Art History","https://www.metmuseum.org/en/essays/ways-of-recording-african-history","Supports World civilisations in parallel (History page)","One of the most intricate of these visual memory devices was the lukasa used by the mbudye association"),SRCQ("Ways of Recording African History – The Met, Heilbrunn Timeline of Art History","https://www.metmuseum.org/en/essays/ways-of-recording-african-history","Supports World civilisations in parallel (History page)","genealogical records of the ruler and titleholders, medicinal practices,"),SRCQ("Memory Board (Lukasa) – The Metropolitan Museum of Art","https://www.metmuseum.org/art/collection/search/690570","Supports World civilisations in parallel (History page)","Lukasa, or memory boards, are hand-held wooden objects that present a conceptual map of fundamental aspects of Luba culture."),SRCQ("Penn State / Palmer Museum of Art: African Brilliance, catalogue 55","https://exhibitions.psu.edu/s/african-brilliance/page/catalogue-55","Supports World civilisations in parallel (History page)","are used by the Mbudye society (men of memory) to recite genealogies")]},
 {id:"africa-south-isilimela-the-pleiades-as-the-d",region:"africa-south",place:"Southern Africa (Zulu and Xhosa communities)",ys:1800,ye:1900,y:"Recorded 19th century (older oral tradition)",domain:"astronomy",also:[],t:"IsiLimela: the Pleiades as the 'digging stars'",text:"In southern Africa the Pleiades, called isiLimela, were the 'digging stars': their appearance signalled that it was time to begin hoeing for the new growing season. Xhosa men also counted their years of manhood from the June rising of isiLimela.",disputed:false,note:"The knowledge is oral and much older than its written record; the 19th-century dates reflect when it was written down (for example by the missionary Henry Callaway), not when it began.",src:[SRCQ("South African star myths – Royal Museums Greenwich","https://www.rmg.co.uk/stories/space-astronomy/south-african-star-myths","Supports World civilisations in parallel (History page)","IsiLimela or the Pleiades were the 'digging stars', whose appearance in southern Africa warned of the coming need to begin hoeing the ground."),SRCQ("South African star myths – Royal Museums Greenwich","https://www.rmg.co.uk/stories/space-astronomy/south-african-star-myths","Supports World civilisations in parallel (History page)","Xhosa men counted their years of manhood from the time in June when IsiLimela first became visible.")]},
 {id:"africa-south-sotho-and-tswana-watch-for-cano",region:"africa-south",place:"Lesotho and Botswana / South Africa (Sotho and Tswana peoples)",ys:1800,ye:1950,y:"Recorded 19th–20th century (older oral tradition)",domain:"astronomy",also:[],t:"Sotho and Tswana watch for Canopus (Naka) to time the year",text:"Sotho and Tswana communities watched for the pre-dawn appearance of the bright star Canopus, called Naka, as a seasonal marker. Tswana herders took it as the signal to start breeding sheep, and Sotho chiefs rewarded whoever saw it first.",disputed:false,note:"Based on ethnographic records compiled in P. G. Alcock's 'Venus Rising' (2014) as published by the Astronomical Society of Southern Africa; the practice is undatable oral tradition and the dates reflect when it was recorded.",src:[SRCQ("African Ethnoastronomy – Astronomical Society of Southern Africa","https://assa.saao.ac.za/astronomy-in-south-africa/ethnoastronomy/","Supports World civilisations in parallel (History page)","When Naka appeared before sunrise, the Tswana knew it was time to start breeding their sheep."),SRCQ("African Ethnoastronomy – Astronomical Society of Southern Africa","https://assa.saao.ac.za/astronomy-in-south-africa/ethnoastronomy/","Supports World civilisations in parallel (History page)","Sotho chiefs awarded a cow for Naka’s earliest sighting."),SRCQ("University of Pretoria Sci-Enza","https://www.up.ac.za/sci-enza/news/dinaledi","Supports World civilisations in parallel (History page)","In the Sotho culture, the chief would even reward this person with a heifer.")]},
 {id:"europe-britain-abolishes-its-slave-trade-the",region:"europe",place:"London, United Kingdom",ys:1807,ye:1833,y:"1807 and 1833",domain:"governance",also:[],t:"Britain abolishes its slave trade, then slavery",text:"Britain ended its slave trade in 1807, after long campaigns by enslaved Africans, Black Britons and abolitionists. Slavery in British colonies continued until emancipation was passed in 1833.",disputed:false,note:"The 1833 Act took effect in 1834 with an \"apprenticeship\" period; this detail is not in the quoted source.",src:[SRCQ("Parliament and the British Slave Trade: Overview - UK Parliament","https://www.parliament.uk/about/living-heritage/transformingsociety/tradeindustry/slavetrade/overview/","Supports World civilisations in parallel (History page)","Although the British ended their slave trade in 1807"),SRCQ("Parliament and the British Slave Trade: Overview - UK Parliament","https://www.parliament.uk/about/living-heritage/transformingsociety/tradeindustry/slavetrade/overview/","Supports World civilisations in parallel (History page)","slavery itself continued in the British colonies until full emancipation in 1833")]},
 {id:"oceania-kamehameha-i-unites-the-hawaiian-isl",region:"oceania",place:"Hawaiian Islands",ys:1810,ye:1810,y:1810,domain:"governance",also:[],t:"Kamehameha I unites the Hawaiian Islands",text:"By 1810 Kamehameha I had united all the Hawaiian islands. His 'law of the splintered paddle' protected ordinary people from violent chiefs.",disputed:false,note:"",src:[SRCQ("Kamehameha I – Britannica","https://www.britannica.com/biography/Kamehameha-I","Supports World civilisations in parallel (History page)","who, by 1810, had united all the Hawaiian islands."),SRCQ("Kamehameha I – Britannica","https://www.britannica.com/biography/Kamehameha-I","Supports World civilisations in parallel (History page)","the law of the splintered paddle")]},
 {id:"americas-north-sequoyah-creates-the-cherokee",region:"americas-north",place:"Cherokee Nation (south-eastern USA)",ys:1821,ye:1821,y:1821,domain:"writing",also:["learning"],t:"Sequoyah creates the Cherokee syllabary",text:"By 1821 Sequoyah had created 86 symbols for the syllables of Cherokee. It spread rapidly and was used in the Cherokee Phoenix newspaper.",disputed:false,note:"",src:[SRCQ("Sequoyah – Britannica","https://www.britannica.com/biography/Sequoyah","Supports World civilisations in parallel (History page)","By 1821 he had created a system of 86 symbols, representing all the syllables of the Cherokee language."),SRCQ("Sequoyah – Britannica","https://www.britannica.com/biography/Sequoyah","Supports World civilisations in parallel (History page)","soon Cherokees throughout the nation were teaching it in their schools")]},
 {id:"africa-west-vai-syllabary-invented-in-liberi",region:"africa-west",place:"Vai country, Liberia",ys:1833,ye:1833,y:"c. 1833",domain:"writing",also:[],t:"Vai syllabary invented in Liberia",text:"Momolu Duwalu Bukele created a syllabic writing system for the Vai language. It is one of the best-known writing systems invented in West Africa.",disputed:true,note:"Sources give about 1833 or 1834.",src:[SRCQ("Vai syllabary - Omniglot (institutional source)","https://shh.mpg.de/2089042/evolution-of-writing","Supports World civilisations in parallel (History page)","The Vai script of Liberia was created from scratch in about 1834 by eight completely illiterate men who wrote in ink made from crushed berries")]},
 {id:"americas-north-slavery-abolition-act-takes-e",region:"americas-north",place:"British Caribbean colonies",ys:1833,ye:1834,y:1834,domain:"governance",also:[],t:"Slavery Abolition Act takes effect",text:"The UK Slavery Abolition Act received Royal Assent on 28 August 1833 and took effect in the Caribbean colonies on 1 August 1834.",disputed:false,note:"Formerly enslaved people were forced into 'apprenticeship' until 1838; slave-owners, not the enslaved, received compensation.",src:[SRCQ("Slavery Abolition Act – Britannica","https://www.britannica.com/topic/Slavery-Abolition-Act","Supports World civilisations in parallel (History page)","The act received Royal Assent on August 28, 1833, and took effect on August 1, 1834.")]},
 {id:"oceania-treaty-of-waitangi-signed",region:"oceania",place:"Waitangi, Aotearoa New Zealand",ys:1840,ye:1840,y:1840,domain:"governance",also:[],t:"Treaty of Waitangi signed",text:"On 6 February 1840 many leading Māori chiefs and the British representative William Hobson made the Treaty of Waitangi.",disputed:true,note:"The English and te reo Māori texts differ in meaning, especially on sovereignty; this remains contested.",src:[SRCQ("Treaty of Waitangi – Britannica","https://www.britannica.com/event/Treaty-of-Waitangi","Supports World civilisations in parallel (History page)","Treaty of Waitangi, (Feb. 6, 1840)"),SRCQ("Treaty of Waitangi – Britannica","https://www.britannica.com/event/Treaty-of-Waitangi","Supports World civilisations in parallel (History page)","by Britain’s designated consul and lieutenant governor William Hobson and many leading Maori chiefs")]},
 {id:"africa-central-the-kongo-dikenga-a-diagram-o",region:"africa-central",place:"Kongo region, lower Congo (Democratic Republic of the Congo)",ys:1850,ye:1920,y:"Documented late 19th–early 20th century (symbol older)",domain:"astronomy",also:[],t:"The Kongo dikenga: a diagram of the sun's daily path",text:"The dikenga, a cross within a circle, is a Kongo cosmological diagram that maps the sun's positions relative to the horizon and links them to the cycle of birth, death and rebirth. It appears on objects such as power figures made by ritual specialists (banganga).",disputed:false,note:"The Metropolitan Museum calls the symbol ancient, but it cannot be dated precisely; the dates here are for the documented museum object, not the origin of the idea. It is best understood as cosmology rooted in watching the sun, not as a measured astronomical record. Part of this rests on one independent source.",src:[SRCQ("Female power figure (nkisi), Kongo – The Metropolitan Museum of Art","https://www.metmuseum.org/art/collection/search/844658","Supports World civilisations in parallel (History page)","The dikenga is an ancient and many-layered symbol—a cosmological diagram for the perceived positions of the sun")]},
 {id:"africa-central-sona-sand-drawings-geometry-t",region:"africa-central",place:"Eastern Angola (Lunda Cokwe/Chokwe peoples)",ys:1900,ye:2023,y:"Recorded 20th century; UNESCO-listed 2023",domain:"maths",also:[],t:"Sona sand drawings: geometry traced around grids of dots",text:"Cokwe (Chokwe) storytellers in eastern Angola mark a grid of points in sand and trace lines around them, often as one continuous closed curve. Mathematicians have studied sona as graphs and symmetry problems, and UNESCO added the tradition to its Intangible Cultural Heritage list in 2023.",disputed:false,note:"The tradition is older than its written records, but its origin cannot be dated; the start year here is a placeholder for when outsiders began recording it, not when it began. Related tusona drawings are practised by Luchazi and neighbouring peoples in Zambia. Describing sona as 'mathematics' is a modern reading; for practitioners they carry stories and knowledge.",src:[SRCQ("Sona, drawings and geometric figures on sand – UNESCO Intangible Cultural Heritage","https://ich.unesco.org/en/RL/sona-drawings-and-geometric-figures-on-sand-01994","Supports World civilisations in parallel (History page)","Practitioners mark reference points on a wet floor covered in sand using their index finger and pinkie, then trace lines around these points."),SRCQ("Sona, drawings and geometric figures on sand – UNESCO Intangible Cultural Heritage","https://ich.unesco.org/en/RL/sona-drawings-and-geometric-figures-on-sand-01994","Supports World civilisations in parallel (History page)","In recent decades, educational institutes have started using Sona as a means of teaching and advancing knowledge about mathematics, ethnomathematics and anthropology, among others."),SRCQ("Demaine et al., 'Properties of sona drawings', Journal of Mathematics and the Arts","https://erikdemaine.org/papers/Sona_JMA/paper.pdf","Supports World civilisations in parallel (History page)","The Tshokwe people of the West Central Bantu area of Africa make similar drawings called sona.")]},
 {id:"africa-south-san-knowledge-of-hoodia-recogni",region:"africa-south",place:"Kalahari, South Africa (San peoples)",ys:2003,ye:2003,y:"2003 (traditional use far older)",domain:"medicine",also:[],t:"San knowledge of hoodia recognised in a benefit-sharing deal",text:"For thousands of years the San ate the bitter flesh of the hoodia succulent to suppress appetite. After South Africa's CSIR patented an appetite-suppressing extract, CSIR acknowledged the San's traditional knowledge in 2002, and in March 2003 the San reached a benefit-sharing agreement with CSIR.",disputed:false,note:"The agreement followed criticism by NGOs that CSIR had used San knowledge without consent or benefit-sharing. The event records the recognition of traditional knowledge; it does not claim that hoodia products are proven to work as slimming aids.",src:[SRCQ("Leveraging Economic Growth through Benefit Sharing – World Intellectual Property Organization","https://www.wipo.int/ipadvantage/en/details.jsp?id=2594","Supports World civilisations in parallel (History page)","In March 2003, the goals of the San people were realized when they reached a benefit sharing agreement with CSIR."),SRCQ("Leveraging Economic Growth through Benefit Sharing – World Intellectual Property Organization","https://www.wipo.int/ipadvantage/en/details.jsp?id=2594","Supports World civilisations in parallel (History page)","However, upon hearing of P57 and its origins, a group of non-governmental organizations (NGOs) criticized CSIR for exploiting the San people’s traditional knowledge."),SRCQ("'Case Study 7. The Commercial Development of Hoodia', document for the 6th meeting of the Ad Hoc Open-ended Working Group on Access and Benefit-sharing, Convention on Biological Diversity (drawing on Wynberg 2004; Wynberg and Chennells 2008)","https://www.cbd.int/doc/meetings/abs/abswg-06/other/abswg-06-cs-07-en.pdf","Supports World civilisations in parallel (History page)","long used to stave off hunger and thirst by the indigenous San peoples"),SRCQ("CBD ABS Working Group 6, Case Study 7: The Commercial Development of Hoodia","https://www.cbd.int/doc/meetings/abs/abswg-06/other/abswg-06-cs-07-en.pdf","Supports World civilisations in parallel (History page)","an acknowledgement by the CSIR that the San are the 'custodians of an ancient body of traditional knowledge and cultural values"),SRCQ("Cultural Survival, 'Sharing the Secrets of the Hoodia: San to Reap Financial Benefits of Traditional Knowledge' (2 May 2003)","https://www.culturalsurvival.org/news/sharing-secrets-hoodia-san-reap-financial-benefits-traditional-knowledge","Supports World civilisations in parallel (History page)","to suppress their hunger and thirst and boost their energy.")]},
];
